window.HRLEAD={"updated":"2026-10-28","updatedKR":"2026년 10월 28일","updatedEN":"28 October 2026","total":122,"mar":91,"top":[{"date":"2026-10-26","tag":"참여·웰빙","tagEN":"Engagement","k":"선원 행복지수 3분기 연속 하락해 6.81 — 상륙 5.46 최저, 선상 동료애가 육상 지원 공백을 가린다","e":"Seafarers Happiness Index falls for a third straight quarter to 6.81, with shore leave lowest at 5.46 as crew camaraderie masks weak shore support","url":"https://www.missiontoseafarers.org/news/seafarer-happiness-slips-as-crews-camaraderie-props-up-failing-shore-side-support"},{"date":"2026-10-23","tag":"심리적 안전","tagEN":"Psychological safety","k":"SSI 보고서: 선원 4분의 1~3분의 1은 우려·실수 보고가 안전하지 않다고 느껴 — 낮은 보고율이 곧 안전의 증거는 아니다","e":"SSI report: a quarter to a third of seafarers do not feel safe raising concerns or reporting mistakes, so low reporting is not proof of safety","url":"https://safety4sea.com/seafarer-welfare-emerges-as-key-indicator-of-maritime-safety-and-financial-risks/"},{"date":"2026-10-22","tag":"현장 리더십","tagEN":"Frontline leadership","k":"스웨덴 클럽 '의도 기반 리더십' — 허가 요청 대신 '이렇게 하겠습니다', 역량이 갖춰진 범위부터 단계적으로 위임","e":"The Swedish Club on intent-based leadership: replace permission-seeking with stated intent and delegate step by step","url":"https://safety4sea.com/cm-the-swedish-club-intent-based-leadership-can-strengthen-maritime-safety-culture/"},{"date":"2026-09-22","tag":"스피크업","tagEN":"Speak-up","k":"선원 행동강령 5년: 심각한 우려를 두려움 없이 말할 수 있다는 선원 59%뿐, '인원이 충분했다'는 49%","e":"Code of Conduct at five years: only 59% of seafarers feel safe raising serious concerns, and 49% say crewing was adequate","url":"https://www.missiontoseafarers.org/news/seafarer-welfare-is-improving-amongst-leading-companies-but-five-years-of-evidence-shows-this-progress-is-far-from-the-norm"},{"date":"2026-10-12","tag":"도선 중 소통","tagEN":"Master-pilot communication","k":"UK P&I, 일본 도선 중 중대사고 20건 분석 — 1순위 원인은 가정과 선입견, 도선사 오류를 아무도 지적하지 않았다","e":"UK P&I's review of 20 serious accidents under pilotage in Japan: assumptions came first, and nobody challenged the pilot's errors","url":"https://www.ukpandi.com/news-and-resources/news/article/pilotage-operations-and-navigational-safety-lessons-from-accident-investigations/"},{"date":"2026-10-24","tag":"교육·변화관리","tagEN":"Training and change","k":"OneOcean·Thetius 조사: 82% '현행 교육은 현대 선박 운항에 못 미친다' — 자격을 갖춘 선원도 실제 운항에서 자주 고전","e":"OneOcean-Thetius research: 82% say current training does not prepare seafarers for modern operations, and qualified crews often struggle","url":"https://www.maritimegateway.com/82-of-maritime-professionals-call-for-better-alignment-between-training-and-shipboard-operations/"},{"date":"2026-10-28","tag":"Just culture","tagEN":"Just culture","k":"[기고] '해양안전심판, 징계 위한 증거 수집으로 변질' — 조사와 심판을 분리한 독립 해양사고조사기구 신설 촉구","e":"[Opinion] Korea's marine tribunal has turned investigation into evidence-gathering for discipline; a professor urges an independent body separate from adjudication","url":"https://www.monthlymaritimekorea.com/news/articleView.html?idxno=58006"},{"date":"2026-10-23","tag":"스피크업","tagEN":"Speak-up","k":"DBR '회의에서 조용한 팀원, 정말 의욕이 없는 걸까?' — 침묵은 '말해 봐야 안 바뀐다'는 경험이 만든 학습의 결과","e":"DBR: silence in meetings is learned from experience that speaking up changes nothing, not a lack of motivation","url":"https://dbr.donga.com/teamleader/view/article_no/188"}],"groups":[{"code":"FRONT","kTitle":"현장 리더십 — 선장·기관장·현장 책임자","eTitle":"Frontline leadership - masters, chief engineers and supervisors","items":[{"code":"FRONT","date":"2026-10-22","src":"Safety4Sea","title":"스웨덴 클럽 '의도 기반 리더십': 허가 요청 대신 '이렇게 하겠습니다'로 — 역량·명확성이 갖춰진 범위부터 단계적으로 위임","eTitle":"The Swedish Club: Intent-Based Leadership Replaces Permission-Seeking With Stated Intent to Strengthen Shipboard Safety Culture","kSum":"The Swedish Club 팟캐스트 'Knot Another Lesson'(진행: 손해예방 매니저 Joakim Enström)에서 리더십 전문가 Jenny Jepsen은 미 해군 잠수함 USS Santa Fe 함장 David Marquet이 정립한 의도 기반 리더십을 선상에 적용하자고 제안했다. 승인을 구하는 대신 '무엇을 하겠다'고 밝히게 해 상황 판단과 주인의식을 드러내게 하고, 위임은 역량(기술 지식·기량)과 명확성(목표·책임 이해) 두 조건이 갖춰진 범위에서 단계적으로 늘린다. Enström은 사고 조사에서 사고를 막을 정보를 가진 사람이 말하지 않은 경우가 많다고 지적했고, Jepsen은 지시 전에 '어떻게 하면 좋겠나'를 묻는 일상 소통 습관이 심리적 안전과 브리지·기관실 팀워크를 키운다고 했다. 최종 책임은 리더에게 남으며, 주인의식을 요구해 놓고 설명 없이 결정을 뒤집으면 참여가 꺼진다고 경고했다.","eSum":"On The Swedish Club's 'Knot Another Lesson' podcast, hosted by loss prevention manager Joakim Enström, leadership expert Jenny Jepsen argued for applying David Marquet's intent-based leadership, developed aboard the US Navy submarine USS Santa Fe, to shipboard operations. Crew state what they intend to do instead of asking permission, and leaders widen delegation step by step only where competence and clarity of objectives exist. Enström noted that investigations often find someone held information that could have prevented an accident but did not speak up; Jepsen said asking crew what they think should be done before giving instructions builds psychological safety in bridge and engine-room teams. Accountability stays with the leader, and overruling a decision after asking for ownership, without discussion, undermines participation.","kImp":"사관 회의 리더십 세션에서 작업 브리핑을 '지시' 대신 '담당자가 의도를 설명하고 선임이 질문하는' 방식으로 바꿔 시연해 볼 만하다. 선박 방문 때 선장·기관장이 답을 바로 주기보다 질문을 먼저 하는지, 다른 의견을 내는 사관이 있는지를 관찰 항목으로 넣을 수 있다.","eImp":"Officers' conferences could rehearse briefings in which the person doing the job explains the intended action and the senior officer asks questions rather than issues orders. Ship visits can note whether masters and chief engineers ask before answering and whether junior officers voice differing views.","url":"https://safety4sea.com/cm-the-swedish-club-intent-based-leadership-can-strengthen-maritime-safety-culture/","prio":3,"mar":true,"tags":["FL","PS","SPEAK"]},{"code":"FRONT","date":"2026-10-21","src":"Ship Management International","title":"노티컬 인스티튜트, 11월 가나 아크라서 리더십·정신건강 워크숍 — 지나친 위계·말하기 주저를 다루는 시나리오 교육, Seafarers' Charity 후원석 제공","eTitle":"The Nautical Institute Brings Scenario-Based Leadership and Mental Health Workshops to Accra, With Sponsored Places Funded by The Seafarers' Charity","kSum":"The Nautical Institute가 11월 16일 '리더십·직업적 행동' 워크숍(리더십 효과성, 직업적 태도, 소통, 포용성, 동기부여, 의사결정)과 17일 '정신건강·웰빙' 워크숍(스트레스·악화 징후 인식, 지원 경로, 동료를 돕는 자신감)을 가나 아크라에서 대면으로 연다. The Seafarers' Charity가 후원석을 지원하며, 아크라는 리더십·정신건강 세션을 짝지어 여는 6개 대면 개최지 가운데 하나다. 프로그램은 부실한 소통, 지나친 위계, 관리되지 않는 스트레스, 포용성 부족, 말하거나 도움을 청하기를 주저하는 문제를 겨냥해 시나리오 기반·동료 학습 방식으로 진행된다. NI Academy 책임자 Somiyeh Djavanroodi는 리더가 소통을 잘하고 심리적 안전을 키우며 팀 웰빙을 지원해야 한다고 말했다.","eSum":"The Nautical Institute will run an in-person Leadership and Professional Behaviours workshop on 16 November and a Mental Health and Wellbeing workshop on 17 November in Accra, Ghana, with sponsored places supported by The Seafarers' Charity. Accra is one of six in-person locations in a programme pairing leadership and mental health sessions for seafarers, ship managers, engineers, regulators and policymakers. The interactive, scenario-based sessions target poor communication, excessive hierarchy, unmanaged stress, limited inclusivity and reluctance to speak up or ask for support. Somiyeh Djavanroodi, Head of The Nautical Institute Academy, said leaders need to communicate well, foster psychological safety and support team wellbeing.","kImp":"사관 회의나 승선 전 교육에 '위계 때문에 말하지 못한 상황'을 다루는 시나리오 토론을 넣고, 리더십 세션과 동료 정신건강 지원 세션을 짝지어 운영하는 구성을 참고할 만하다.","eImp":"Officers' conferences and pre-joining briefings could add scenario discussions on moments when hierarchy stopped someone from speaking, and pair leadership sessions with peer mental health support sessions as this programme does.","url":"https://www.shipmanagementinternational.com/news/the-nautical-institute-brings-leadership-and-mental-health-workshops-to-ghana","prio":1,"mar":true,"tags":["FL","PS","TRN"]},{"code":"FRONT","date":"2026-10-20","src":"Safety4Sea","title":"스웨덴 클럽 '4P 프레임워크': 철학·정책·절차·실제 작업 — 감사마다 절차를 덧붙이지 말고, 절차는 쓰는 사람이 쓰고, 육상은 안전 판단을 눈에 보이게 지지하라","eTitle":"The Swedish Club's Four Ps Framework: Turning Safety Philosophy Into Practice Through Crew-Written Procedures, Short Checklists and Visible Shore Backing","kSum":"The Swedish Club 팟캐스트에서 손해예방 매니저 Joakim Enström과 선장·도선사 출신으로 20년 넘게 교육센터를 운영한 Hans Hederström 선장은 안전을 철학(핵심 가치)·정책(의사결정 원칙)·절차(작업별 지침)·실제 작업(날씨·화물·일정·피로 속에서 실제로 하는 방식) 네 층으로 보는 4P 프레임워크를 설명했다. Hederström은 실제 작업은 문서 속 상상한 작업과 결코 같지 않으며, 절차에 지나치게 기대면 예상 못 한 상황에서 판단력이 약해지고 감사·사고 때마다 가치 평가 없이 절차를 추가하면 문서 과부하가 생긴다고 경고했다. 선원이 절차 작성에 참여해야 목적을 이해하고 주인의식을 갖게 되며, 육상이 자신의 판단을 지지해 준다는 확신이 없으면 안전 철학은 실효가 없다고 강조했다. 2013년 도입된 CSMART 프로그램에서 숙련 선장을 강사·코치로 선박에 보내 브리지 팀의 시스템 정착과 리더십을 지원한 사례, 회사 한계 안이었지만 강풍으로 입항을 미룬 결정을 회사가 칭찬한 경험을 소개했고, 체크리스트는 실제 작업자가 쓰고 한 쪽을 넘지 않으며 시뮬레이터로 시험하라고 권했다.","eSum":"On The Swedish Club's podcast, loss prevention manager Joakim Enström and Capt. Hans Hederström, a former master and pilot who ran training centres for over 20 years, described the Four Ps: philosophy (core safety values), policies (decision principles), procedures (task instructions) and practice (how work is really done amid weather, cargo, deadlines and fatigue). Hederström said work as done never matches work as imagined, that over-reliance on procedures weakens judgement in unforeseen situations, and that adding a procedure after every audit or incident without assessing its value creates documentation overload. Seafarers should help write procedures so they understand and own them, and a safety philosophy means little unless crews know shore management will back their decisions. He cited the CSMART programme introduced in 2013, which sent experienced captains to ships as coaches for bridge teams, recalled being commended for delaying a port entry in strong winds even though conditions were within company limits, and urged checklists written by the people who use them, no longer than one page and tested in simulators.","kImp":"다음 절차 개정 때 해당 작업을 하는 사관·부원이 직접 초안을 쓰게 하고, 최근 감사·사고 후 추가한 절차가 실제로 위험을 줄였는지 한 번 걸러 보는 검토를 해 볼 만하다. 한계 안이지만 안전을 이유로 일정을 늦춘 선장의 결정을 공개적으로 지지하는 사례를 사관 회의에서 공유하면 '육상이 지지한다'는 메시지가 분명해진다.","eImp":"In the next procedure revision, let the officers and ratings who do the task draft it, and screen procedures added after recent audits or incidents for whether they actually reduced risk. Sharing at officers' conferences a case where shore management backed a master who delayed operations for safety makes the backing visible.","url":"https://safety4sea.com/cm-swedish-club-four-ps-framework-helps-turn-safety-philosophy-into-practice/","prio":2,"mar":true,"tags":["FL","SS","TRN"]},{"code":"FRONT","date":"2026-10-19","src":"Gard","title":"Gard '브리지 제어 상실' 시리즈 3편: 인적 실패는 정상 — 숙련 선원도 제어 전환 단계를 건너뛴다, 안전 핵심 확인에는 폐쇄 루프 소통을","eTitle":"Gard: In Loss of Bridge Control, Human Failure Is Normal, So Control Transfers Need Closed-Loop Checks and Risk Assessments That Weigh Performance Influencing Factors","kSum":"Gard의 Mark Russell(클레임 총괄 부사장)은 브리지 제어 상실 시리즈 세 번째 글에서 인적 실패는 흔하고 예측 가능하므로 안전 핵심 작업의 위험성 평가에 수행영향요인(PIF)을 반영해야 한다고 썼다. 사례로 선장과 2등항해사가 서로 상대가 조이스틱 활성 여부를 확인할 것이라 여겨 폐쇄 루프 확인 없이 문서화된 전환 단계를 건너뛴 경우, 선원들이 문서와 다른 '자체 이해'로 비상조타를 설정한 경우, 피로가 조타 상실 대응을 흐린 군함 충돌 등을 들었다. 99.9% 잘 작동하는 시스템이 숙련자에게 핵심 단계를 일상 업무처럼 여기게 만들고, 비공식 관행이 절차를 대체해 잠재 위험을 만든다고 지적했다. 협수로 진입 전 브리핑, 3개월마다 하는 조타기실 비상훈련에서 실제 관행을 문서와 대조, 핵심 체크 단계의 폐쇄 루프 확인, 스피크업 문화와 제어 시스템 사용성에 대한 선원 피드백 수집을 권고했다.","eSum":"In the third article of its loss of bridge control series, Gard's Mark Russell argues that human failure is common and predictable, so risk assessments for safety-critical tasks should weigh performance influencing factors. Cases include a master and second mate who each assumed the other would confirm the joystick was active and skipped a documented transfer step without closed-loop communication, a crew whose own understanding of emergency steering differed from documented practice, and a naval collision in which acute fatigue shaped the response to a perceived steering loss. Systems that work 99.9 per cent of the time lead experienced crews to treat critical steps as routine, and informal local practice can quietly replace procedures. Gard recommends pre-entry bridge briefings, using the three-monthly emergency steering drills to check real practice against documentation, closed-loop confirmation of critical steps, and a speak-up culture that gathers crew feedback on control systems.","kImp":"조타기실 비상훈련 때 '절차서대로'가 아니라 '평소 우리가 하는 대로' 먼저 해 보게 한 뒤 문서와 비교하면 숨은 관행을 찾을 수 있다. 제어 전환처럼 안전 핵심 단계에는 복창·확인 응답을 의무화하는 브리지 습관을 사관 회의에서 다룰 만하다.","eImp":"During emergency steering drills, have crews first do it the way they normally do and then compare with the documented procedure to expose hidden local practice. Officers' conferences can reinforce read-back and confirmation for safety-critical steps such as control transfers.","url":"https://gard.no/en/insights/loss-of-bridge-control-human-failure-is-normal-context-is-key/","prio":2,"mar":true,"tags":["BRM","SPEAK","TRN"]},{"code":"FRONT","date":"2026-10-09","src":"Safety4Sea","title":"제17회 SAFETY4SEA 아테네 포럼: '안전문화는 선장·사관의 일상 행동이 만든다' — 작업중지 지지·근접사고 보고 독려, 말하기 주저는 리더십으로 조기 포착","eTitle":"17th SAFETY4SEA Athens Forum: Masters and Officers Shape Safety Culture Through Daily Behaviour, From Backing Stop-Work Calls to Catching Reluctance to Speak Up","kSum":"10월 8일 아테네에서 열린 제17회 SAFETY4SEA Athens Forum 안전문화 패널에서 American P&I Club 컨설턴트 Nikos Taktikos 선장은 선장·사관이 솔선수범, 작업중지 결정 지지, 근접사고 보고 독려, 실효성 있는 툴박스 미팅, 피로·웰빙 인식 같은 일상 행동으로 안전문화를 만들며 교육·인식만으로는 부족하고 좋은 관행이 습관이 돼야 한다고 말했다. 선원 복지 패널에서 UK P&I Club의 Konstantinos Karavasilis 선장은 피로·스트레스·고립·말하기 주저가 안전 수행을 해친다며 우려를 일찍 잡아내는 실천적 리더십과 선대 일괄 정책보다 개별 선박 상황 파악을 강조했고, J.H.I. Steamship의 Sotiris Kostouros는 고급사관이 행동 변화를 알아차리는 교육을 받고 회사와 열린 소통을 유지해야 한다고 했다. 인적요소 패널에서는 Columbia Shipmanagement의 Andreas Travlos가 인력 유지는 계약 예측 가능성·복지·신뢰할 수 있는 육상 관리 관계에 달렸다고 말했다. 포럼은 SAFETY4SEA 선원 복지 성숙도 지수 2026(7개 영역·6단계)도 소개했다.","eSum":"At the 17th SAFETY4SEA Athens Forum on 8 October, Capt. Nikos Taktikos of The American P&I Club told the safety culture panel that masters and officers shape safety culture through daily behaviour, including leading by example, supporting stop-work decisions, encouraging near-miss reporting, running effective toolbox talks and recognising fatigue, and that training and awareness only matter once good practice becomes habit. On the crew welfare panel, UK P&I Club's Capt. Konstantinos Karavasilis said fatigue, stress, isolation and reluctance to speak up undermine safe performance and called for practical leadership that catches concerns early and attention to conditions on individual ships rather than fleet-wide policies alone, while Sotiris Kostouros of J.H.I. Steamship said senior officers need training to recognise behavioural change and must keep open communication with the company. Andreas Travlos of Columbia Shipmanagement said retention depends on contract predictability, welfare and trusted relationships with shore management. The forum also presented the SAFETY4SEA Crew Welfare Maturity Index 2026, covering seven domains across six maturity stages.","kImp":"선박 방문 체크 항목에 '선장이 최근 작업중지나 근접사고 보고를 공개적으로 인정한 사례'를 넣어 리더 행동을 직접 확인해 볼 만하다. 고급사관 대상 교육에 선원의 행동 변화(고립·수면·말수 변화)를 알아차리고 육상에 알리는 경로를 포함하는 것이 좋다.","eImp":"Ship visit checklists can ask for recent cases where the master publicly backed a stop-work call or a near-miss report, checking leader behaviour directly. Senior officer training can cover spotting behavioural change in crew and the route for alerting shore support.","url":"https://safety4sea.com/2026-safety4sea-athens-forum-press-release/","prio":2,"mar":true,"tags":["FL","SPEAK","WELL"]},{"code":"FRONT","date":"2026-09-30","src":"Safety4Sea","title":"Britannia P&I 손해예방 책임자: 몰입형 브리지 시뮬레이션은 '평가 아닌 토론형 학습'일 때 안전문화를 키운다 — 멈추고 묻기: 정보 공유·가정·이의 제기","eTitle":"Britannia P&I: Immersive Bridge Simulation Strengthens Safety Culture When Used for Facilitated Learning on COLREG, BRM and Error Chains, Not Assessment","kSum":"Britannia P&I Club 손해예방 책임자 Jacob Damgaard는 기고에서 클럽이 회원 교육 프로그램에 운항 데이터로 브리지 환경과 항해 상황을 2D·3D로 재현하는 인터랙티브 시뮬레이션 플랫폼을 도입했다고 밝혔다. 진행자는 시나리오를 멈추고 브리지에서 정보가 공유되고 있는지, 검증된 데이터 대신 가정이 행동을 이끄는지, 팀에 이의 제기·응답 문화가 있는지를 묻는다. 서류상 단순한 횡단 상황도 밀집 교통·조종 제한·제한 시계·브리지 업무량이 더해지면 빠르게 악화되며, 참가자들은 대형 사고가 작은 결정과 검증되지 않은 가정, 놓친 기회가 이어진 오류 사슬에서 나온다는 것을 실시간으로 확인한다. 플랫폼은 시험·평가가 아닌 토론 도구로만 쓰여 선장·사관·감독·육상 직원이 같은 상황에 팀마다 왜 다르게 반응하는지 부담 없이 분석하게 하며, 그는 '기술만으로는 만능이 아니다'라고 덧붙였다.","eSum":"Jacob Damgaard, Head of Loss Prevention at Britannia P&I Club, writes that the club has added an interactive simulation platform to its member engagement programme, recreating bridge environments and navigational situations from operational data in two and three dimensions. Facilitators pause scenarios to ask whether information is being shared across the bridge, whether assumptions rather than verified data are driving actions, and whether the team has an active challenge-and-response culture. A crossing situation that looks simple under COLREG can escalate quickly with dense traffic, restricted visibility and bridge workload, and participants see in real time how accidents grow from chains of small decisions, untested assumptions and missed opportunities. The platform is used strictly for facilitated discussion, never assessment, so masters, officers, superintendents and shore staff can explore why teams respond differently; Damgaard stresses that technology alone is not a silver bullet.","kImp":"사관 회의에서 실제 사고 재구성 시나리오를 중간에 멈추고 '지금 이 브리지에서 누가 무엇을 알고 있나, 누가 이의를 제기해야 하나'를 묻는 토론형 세션으로 운영해 볼 만하다. 시뮬레이터 교육을 평가와 분리해야 솔직한 토론이 나온다.","eImp":"Officers' conferences can run accident reconstructions as discussion sessions, pausing to ask who on the bridge knows what and who should challenge. Keeping simulator sessions separate from assessment encourages candid discussion.","url":"https://safety4sea.com/why-digital-immersive-learning-can-improve-maritime-safety/","prio":2,"mar":true,"tags":["BRM","TRN","SPEAK"]},{"code":"FRONT","date":"2026-09-25","src":"MAIB","title":"MAIB 'Argos Georgia' 침몰(13명 사망) 보고서: 침수 대응은 '체계가 없었고' 조난 선포·퇴선이 늦어 구조 시간을 잃었다 — 회사엔 비상 상황을 평가·상향 보고할 체계가 없었다","eTitle":"MAIB on the Argos Georgia Foundering That Killed 13: An Unstructured Response and Late Distress and Abandonment Calls Cost Rescue Time, With No Shore System to Escalate Emergencies","kSum":"영국 MAIB가 2024년 7월 22일 포클랜드 스탠리항 동쪽 약 190해리에서 침몰해 승선자 27명 중 13명이 숨진 세인트헬레나 선적 연승어선 Argos Georgia 보고서(19/2026)를 냈다. 우현 양승 해치의 수동 고정장치가 걸려 있지 않았을 가능성이 높아 거친 바다에서 해치가 열렸고, 닫을 수 없게 되자 침수가 열린 풍우밀 문과 취약한 전기 계통을 따라 번져 선박이 복원력을 잃었다. MAIB는 선원들의 침수 대응이 '체계가 없었고' 조난 선포와 퇴선이 늦어 구조에 쓸 시간이 줄었으며, 퇴선 통제 부실·혹독한 기상·구명뗏목 손상이 냉수 노출을 키웠다고 결론지었다. 운항사에는 안전 핵심 위험을 관리하고 침수·퇴선·조난 비상을 평가·상향 보고·대응하는 체계가 없었다며 문서화된 안전관리시스템 도입이 권고됐고, Rob Loder 수석조사관은 문제가 생기면 '신속하고 명확하며 효율적인 비상 계획이 실행돼야 한다'고 말했다.","eSum":"The UK MAIB's report 19/2026 covers the St Helena-registered longliner Argos Georgia, which foundered about 190 nautical miles east of Port Stanley, Falkland Islands, on 22 July 2024, killing 13 of the 27 people on board. The manual securing mechanism of the starboard line-hauling hatch had likely not been applied, the hatch opened in heavy seas and could not be closed, and flooding spread through open weathertight doors and vulnerable electrical systems until the vessel lost stability. MAIB found the crew's response was unstructured and that delays in declaring distress and abandoning ship reduced the time available for rescue, while poor evacuation control, severe weather and liferaft damage increased cold-water exposure. The operator lacked effective systems for managing safety-critical risks and for assessing, escalating and responding to flooding, abandonment and distress emergencies and was recommended to implement a documented safety management system; Chief Inspector Rob Loder said a quick, clear and efficient emergency plan should be executed when problems arise.","kImp":"침수·퇴선 훈련에 '조난 선포를 언제, 누가 결정하는가'라는 시점 기준을 명시하고, 선상 판단이 늦어질 때 육상 비상대응팀이 먼저 조난 선포를 권고하는 상향 보고 흐름을 함께 연습해 볼 만하다.","eImp":"Flooding and abandon-ship drills can set explicit triggers for who declares distress and when, and rehearse an escalation route in which the shore emergency response team recommends declaring distress if the decision on board is slow.","url":"https://www.gov.uk/maib-reports/foundering-of-the-fishing-vessel-argos-georgia-with-the-loss-of-13-lives","prio":2,"mar":true,"tags":["FL","SS"]},{"code":"FRONT","date":"2026-08-28","src":"The Nautical Institute","title":"NI MARS 202629 '분리통항로 안개 속 충돌': 증원된 브리지 팀도 BRM·상황 인식이 약하면 소용없다 — 추월선 OOW는 시정 악화를 선장에게 알리지 않았다","eTitle":"Nautical Institute MARS 202629: A Reinforced Bridge Team Is No Guarantee Without BRM, as Two Ships Collide in Fog in a TSS","kSum":"NI MARS 보고(튀르키예 사고조사위원회 보고서 13/D-6/2023 편집)에 따르면 시정 약 350m 안개 속 분리통항로에서 7.6노트로 항행하던 만재 벌크선은 선장과 항해사 2명, 조타수로 브리지 당직을 강화했지만, 뒤에서 11.8노트로 추월하던 선박을 레이더 표적으로 추적하지 못했다. 추월선은 AIS를 송신하지 않고 레이더 반사도 간헐적이었으며 두 선박 모두 무중 신호를 울리지 않았고, 추월선 OOW는 시정 악화를 선장에게 알리지 않은 채 자동조타로 고속 항행했다. 벌크선 선장은 VTS가 추월선 위치를 모르는 상태에서 반대 항로가 비었다고 보고 횡단을 시작했고, 두 선박 간 VHF 교신은 후속 확인 없이 끊겨 결국 충돌했다. 교훈으로 AIS 과신 경계, 제한 시계에서 모든 물표의 레이더 추적, 가시거리 안에 정지할 수 있는 속력, 당직표가 아닌 실제 조건에 맞춘 브리지 팀 구성, 그리고 증원된 팀도 BRM이 부실하면 안전을 보장하지 못한다는 점을 제시했다.","eSum":"A Nautical Institute MARS report, edited from Turkish investigation report 13/D-6/2023, describes a loaded bulk carrier transiting a traffic separation scheme in fog at 7.6 knots with visibility of about 350 m and a reinforced bridge of the master, two navigating officers and a helmsman, which still failed to track a vessel overtaking from astern at 11.8 knots. The overtaking ship was not transmitting AIS and gave intermittent radar returns, neither ship sounded fog signals, and its officer of the watch did not tell the master about the reduced visibility while running on autopilot at high speed. The bulk carrier's master began crossing the opposite lane, which looked clear, while VTS did not know the other ship's position, and a VHF exchange between the ships ended without follow-up before they collided. Lessons include not over-relying on AIS, tracking every contact on radar in restricted visibility, keeping a speed that allows stopping within the visible range, setting bridge teams by actual conditions rather than routine schedules, and recognising that even a reinforced team is no guarantee without effective BRM.","kImp":"제한 시계 시 '선장 호출 기준'과 브리지 증원 시 각자의 역할(레이더 추적·VHF·견시)을 명시적으로 나누는 절차를 사관 회의 사례로 점검해 볼 만하다. VHF로 상대선을 불렀다면 의도 확인까지 끝내도록 하는 습관도 강조할 필요가 있다.","eImp":"Officers' conferences can use this case to check master-calling criteria in restricted visibility and to assign explicit roles for radar tracking, VHF and lookout when the bridge is reinforced. A VHF call to another ship should be followed through until intentions are confirmed.","url":"https://www.nautinst.org/resources-page/202629-collision-in-fog-in-a-tss.html","prio":1,"mar":true,"tags":["BRM","FL"]},{"code":"FRONT","date":"2026-08-27","src":"Safety4Sea","title":"West P&I 손해예방 책임자: 좌초·충돌의 뿌리는 장비가 아닌 절차·소통·리더십 실패 — 선장·고급사관은 낙인 없이 우려를 말할 환경을 만들어야","eTitle":"West P&I's Loss Prevention Head: Groundings and Collisions Reflect Failures of Procedures, Communication and Leadership, Not Equipment","kSum":"West P&I 손해예방 책임자 Simon Hodgkinson 선장(해상 25년, 그중 10년 해양선 선장)은 SAFETY4SEA 인터뷰에서 사고 조사가 피로, 약한 BRM, 잘못된 의사결정, 비효과적 감독, 약한 안전 리더십을 반복해 기여 요인으로 지목한다고 말했다. 좌초·충돌은 항해 계획·위치 확인·상황 인식 같은 기본기 부족에 자만과 결정에 이의를 제기하지 않는 태도가 겹친 것으로, 장비가 아닌 절차·소통·리더십의 실패라고 진단했다. 강한 리더십, 효과적 소통, 충분한 휴식, 불안전한 결정에 기꺼이 말하고 이의를 제기하는 문화가 사고 예방을 가르며, 선장과 고급사관은 선원이 낙인 없이 우려를 말하고 도움을 청할 환경을 만들어야 한다고 강조했다. 가족 사망 같은 민감한 소식은 복지 지원 경로로 전달해 선장이 당직 적합성을 판단할 수 있게 하고, 당직 중 개인 기기 사용 제한과 수면·디지털 습관 교육을 권했으며, 구조적 변화로 항만 일정에 상륙 휴가를 의무화하자고 제안했다.","eSum":"Capt. Simon Hodgkinson, Head of Loss Prevention at West P&I, who spent 25 years at sea including 10 as an offshore master, told SAFETY4SEA that investigations repeatedly find fatigue, weak bridge resource management, poor decision-making, ineffective supervision and weak safety leadership as contributing factors. Groundings and collisions often reflect shortfalls in passage planning, position verification and situational awareness compounded by complacency and failure to challenge decisions, which he called failures of procedures, communication and leadership rather than equipment. Strong leadership, effective communication, adequate rest and a culture in which people are willing to speak up and challenge unsafe decisions often determine whether an incident is prevented, and masters and senior officers should let crew raise concerns and seek support without stigma. He suggested routing sensitive news such as a bereavement through welfare support channels so the master can judge fitness for duty, restricting personal devices on watch while educating crews on sleep and digital habits, and making shore leave periods mandatory in port schedules.","kImp":"가족 부고 같은 민감한 소식을 선원에게 바로 알리기 전에 선장과 먼저 공유해 당직 조정을 판단하게 하는 육상 연락 절차를 점검해 볼 만하다. 선장 대상 브리핑에서 '이의 제기를 낙인 없이 받는 법'을 구체 사례로 다루는 것도 좋다.","eImp":"Check that shore contact procedures share sensitive news such as a bereavement with the master first so watch arrangements can be judged before the seafarer is told. Briefings for masters can cover, with concrete cases, how to receive challenges without stigma.","url":"https://safety4sea.com/cm-west-club-training-is-key-to-building-confidence-competence-and-a-strong-safety-culture/","prio":2,"mar":true,"tags":["FL","BRM","SPEAK"]},{"code":"FRONT","date":"2026-08-25","src":"Ship Management International","title":"노티컬 인스티튜트 5부작 팟캐스트 'Better Working Lives at Sea' — 이해 없이 '알겠다'고 답하는 위험, 높은 기준과 공감을 겸한 '친절한 리더십', 멘토링, 직급·문화를 넘어 이의 제기할 자신감","eTitle":"The Nautical Institute Launches 'Better Working Lives at Sea', a Five-Part Podcast on Communication, Kind Leadership, Mentoring and Soft Skills","kSum":"The Nautical Institute가 The Seafarers' Charity 후원으로 안전하고 성공적인 승선 경력을 뒷받침하는 소통·리더십·멘토링 기술을 다루는 5부작 팟캐스트 'Better Working Lives at Sea'를 내놓았다(진행: OneOcean의 학습·인재전략 책임자 Catherine Logie). Dunmore East 항만장 Deirdre Lane은 메시지를 완전히 이해하지 않고 수신만 확인하는 위험을 중심으로 효과적인 소통을, NI 런던지부장 Steve Cameron은 높은 기준과 공감을 함께 갖춘 '친절한 리더십'을, 25년 넘게 멘토로 활동한 Ann Pletschke 선장은 경력 전반의 멘토링을 다뤘다. 선장 출신인 Novellus Solutions의 Nippin Anand 박사는 안전문화에 대한 통념에 이의를 제기했고, NI 부회장 Neil Dulling은 소프트 스킬이 안전 운항에 필수인 이유를 설명했다. 대담들은 직급과 문화를 넘어 사람들이 결정에 의문을 제기하고 말할 자신감을 갖게 하는 방법을 다루며, 시리즈는 NI 팟캐스트 페이지·Spotify·Apple Podcasts·YouTube에서 들을 수 있다.","eSum":"The Nautical Institute, sponsored by The Seafarers' Charity, has launched Better Working Lives at Sea, a five-part podcast on the communication, leadership and mentoring skills behind safe and successful careers at sea, hosted by Catherine Logie of OneOcean. Dunmore East harbour master Deirdre Lane discusses effective communication and the risk of acknowledging a message without fully understanding it, NI London Branch chair Steve Cameron makes the case for kind leadership that combines high standards with empathy, and Capt. Ann Pletschke, a mentor with more than 25 years' experience, explains why mentoring matters throughout a career. Dr Nippin Anand, a former master and founder of Novellus Solutions, challenges conventional thinking about safety culture, and NI vice president Neil Dulling explains why soft skills are essential to safe operations. The conversations cover giving people across ranks and cultures the confidence to question decisions and speak up; the series is on the NI podcast page, Spotify, Apple Podcasts and YouTube.","kImp":"승선 전 교육이나 사관 회의 사전 과제로 에피소드 한 편을 듣고 '알겠다고 답했지만 이해하지 못했던 지시'를 사례로 나누는 토론을 해 볼 만하다. 신임 사관 멘토링 제도를 설계할 때 참고 자료로도 쓸 수 있다.","eImp":"Pre-joining training or officers' conferences could assign one episode as pre-work and discuss cases where an instruction was acknowledged but not understood. The series can also inform the design of mentoring for newly promoted officers.","url":"https://www.shipmanagementinternational.com/news/8sxkfyghxpf37x5-9jjxp-944a6-9kexd-b9y6g-kzrgc-ykzff-zzlx2-5heyr-2x6ll-3c6h7-lcrj7","prio":2,"mar":true,"tags":["FL","SPEAK","TRN"]},{"code":"FRONT","date":"2026-08-05","src":"Safety4Sea","title":"CHIRP 교훈(극지 해역): 첫 극지 항해 OOW의 육안 관찰은 결정에 반영되지 않았다 — 선장 권위와 경험 차이가 '누구 말을 듣는가'를 좌우","eTitle":"CHIRP Lesson in Polar Waters: A First-Trip Officer's Visual Observations Went Unheard as Rank and Experience Shaped the Bridge Team's Route Choice","kSum":"CHIRP Maritime 보고 사례에서 탐험선이 빙하 얼음·빙산이 섞인 6~7/10 밀도의 얼음 해역을 빠져나갈 때, 선장이 조선하고 1등항해사는 GPS·측심 3D 해저 화면을 보며 이전 선박의 전자 항적을 따르자고 했고, 첫 극지 항해인 OOW는 육안으로 대체 항로를 찾고 있었다. 견시원은 갑판에서 작업정을 고정하느라 브리지에 없었고 사전 통항 계획도, 상황 변화에 대비한 항로·비상 대책도 없었으며, 이전 항적 위의 빙산 몇 개는 평가에서 식별되지 않았다. CHIRP는 OOW의 관찰이 공유·반영되지 않은 소통 실패, 이전 항적을 검증된 경로로 여긴 과신, 정보원을 하나의 그림으로 합치지 못한 팀워크 부족, 진행 압박, 전자 화면 집중을 기여 요인으로 들었고, 상황을 가장 잘 볼 수 있던 OOW에게 평가를 묻지 않았으며 선장의 권위와 경험 차이가 누구 말이 들리는지를 좌우한 것으로 보인다고 지적했다. 관리자에게는 경로·대안·결정 지점을 정한 극지 통항 계획과 브리지 팀 누구나 결정에 이의를 제기할 수 있는 문화를, 선원에게는 보이는 것과 전자 정보가 다를 때 일찍 말하라고 권고했다.","eSum":"In a CHIRP Maritime report, an expedition vessel was leaving an area of 6 to 7 tenths ice with glacial ice and icebergs; the master had the con, the chief officer favoured following a previous vessel's electronic track on a 3D seabed display, and an officer of the watch on a first polar voyage was looking for alternative routes visually. The assigned lookout was on deck securing workboats, there was no pre-established passage plan or agreed contingency for changing conditions, and several icebergs on the old track were not identified. CHIRP cited the failure to share and act on the officer's observations, over-confidence in a previous track, poor teamwork in combining information, pressure to make progress and focus on electronic displays, noting that the officer best placed to observe was never asked for an assessment and that the master's authority and the experience gradient appear to have shaped who was heard. It urges managers to require polar passage plans with routes, alternatives and decision points and a culture in which every bridge team member can challenge decisions, and seafarers to speak up early when what they see does not match the electronic picture.","kImp":"브리지 의사결정 때 선장이 가장 경험이 적은 사관에게 먼저 의견을 묻는 '역순 질문' 습관을 사관 회의에서 제안해 볼 만하다. 얼음·협수로처럼 불확실성이 큰 구간은 통항 계획에 결정 지점과 대체 항로를 미리 적게 하는 것이 좋다.","eImp":"Officers' conferences can suggest that masters ask the least experienced officer first when making bridge decisions. For high-uncertainty passages such as ice or narrow channels, passage plans can set decision points and alternative routes in advance.","url":"https://safety4sea.com/lessons-learned-in-polar-waters-safe-navigation-requires-multiple-sources/","prio":2,"mar":true,"tags":["BRM","SPEAK","FL"]},{"code":"FRONT","date":"2026-08-04","src":"Safety4Sea","title":"'도선사도 사람이라 실수한다': 선장이 거듭 위치를 우려했지만 도선사는 '괜찮다'만 반복 — 기대 편향 속 두 차례 좌초, 지역 전문가에게 개입하길 주저하는 브리지","eTitle":"Pilots Are Human and Can Make Mistakes: A Master's Repeated Warnings Did Not Stop Expectation Bias From Grounding a Laden Bulk Carrier Twice","kSum":"The Nautical Institute가 공식 조사보고서에서 뽑은 교훈을 SAFETY4SEA가 소개한 사례로, 흘수 11.7m의 만재 벌크선이 조류가 있는 강을 거슬러 오를 때 교대한 도선사가 선박이 '좌현으로 파고든다'고 보고 의도적으로 수로 우현 밖으로 몰았고, 실제 조고가 예측의 절반도 안 돼 기대한 조류가 약했던 탓에 선수가 수로 밖 약 88m까지 벗어나 바닥에 닿았다. 재부상 후에도 도선사는 수로 한계에서 약 75m 우현 쪽을 계속 유지했고, 선장이 위치를 거듭 우려하고 우현 앞의 붉은 부표를 짚었지만 '괜찮다'는 답만 들었으며, 약 8분 뒤 선박은 다시 좌초해 여러 밸러스트·연료 탱크가 침수되고 사흘간 얹혀 있었다. 이 사례는 NTSB 보고서 MIR-26-06이 다룬 Algoma Verity호의 2025년 1월 델라웨어강 좌초로, The Maritime Executive에 따르면 피해는 약 660만 달러였고 NTSB는 도선사가 실제 선박 거동 대신 예상에 따라 움직인 '기대 편향'과 부족한 소통을 지적했다. 교훈은 도선 중에도 한 사람이 모든 결정을 이의 없이 내리는 단일 실패 지점을 막는 BRM, 계획에서 벗어난 행동을 즉시 공유해 같은 그림을 유지하는 것, 그리고 선장조차 현지 전문가에게 개입하길 주저한다는 점을 인정하고 이의를 제기할 의지를 갖는 것이다.","eSum":"In a case drawn by The Nautical Institute from an official investigation and published by SAFETY4SEA, a fully laden bulk carrier with an 11.7 m draft was upbound in a tidal river when the relieving pilot, believing the ship tended to dive to port, deliberately steered outside the starboard side of the channel; real tides were less than half the prediction, the expected current was weak, and the bow ended about 88 m outside the channel and touched bottom. After refloating, the pilot kept the ship about 75 m to starboard of the channel limit while the master repeatedly voiced concern and pointed out a red buoy ahead, receiving only reassurance, and about eight minutes later the ship grounded hard, flooding several ballast and fuel tanks and staying aground for three days. The case is the January 2025 grounding of Algoma Verity on the Delaware River covered by NTSB report MIR-26-06, which The Maritime Executive reported caused about USD 6.6 million in damage, with the NTSB citing expectation bias and poor communication. The lessons are that BRM with a pilot aboard must prevent a single point of failure, that deviations from the plan must be discussed to keep a shared mental model, and that bridge officers, even masters, are often hesitant to intervene with a local expert at the con and must be willing to challenge.","kImp":"선장이 도선사에게 지휘권을 다시 가져와야 하는 기준(예: 수로 이탈 거리, 반복된 우려에도 계획 미설명)을 사관 회의에서 사례와 함께 정리해 볼 만하다. '우려 제기 → 설명 요구 → 지휘권 회수'를 단계별 표현으로 연습하는 것도 좋다.","eImp":"Officers' conferences can use this case to agree when a master should take back the con from a pilot, such as a set distance outside the channel or concerns repeatedly met without an explained plan, and rehearse the wording for raising concern, demanding an explanation and resuming control.","url":"https://safety4sea.com/lessons-learned-pilots-are-human-and-can-make-mistakes/","prio":2,"mar":true,"tags":["BRM","SPEAK","FL"]},{"code":"FRONT","date":"2026-10-16","src":"DBR","title":"DBR '최악의 상사를 리더십 교재로' — 일을 비판하는 '요구가 많은 상사'와 사람을 깎아내리는 '파괴적 상사'를 구분해 교훈을 회수하라","eTitle":"DBR: Turning the Worst Boss Into Leadership Material - Separate the 'Demanding Boss' Who Criticises the Work From the 'Destructive Boss' Who Attacks the Person","kSum":"DBR 팀장클럽 리포트(10월 16일)는 편안한 강의실에서 듣는 리더십 이론보다 나쁜 상사와 일하며 매일 부딪힌 시행착오가 더 오래 기억에 남는다며, 이미 겪은 부정적 경험에서 앞으로의 리더십에 쓸 교훈을 찾아내라고 권했다. 다만 나쁜 상사도 두 유형으로 나눠야 한다고 했다. 높은 기준으로 '일'을 비판해 대화 뒤 '무엇을 어떻게 고칠지'가 남는 요구가 많은 상사와, '사람'을 모욕하고 인격을 깎아내려 피드백이 아닌 상처를 남기는 파괴적인 상사다. 글은 유형을 구분한 뒤 경험에서 배울 점을 회수하는 3단계를 제시한다(구독 기사, 공개된 앞부분 기준).","eSum":"A 16 October piece in DBR's team-leader series argues that lessons learned through daily friction with a bad boss last longer than leadership theory heard in a comfortable classroom, so managers should mine those negative experiences for lessons they can use. It says bad bosses must be split into two types: the demanding boss, who judges the work against high standards and leaves people knowing what to fix, and the destructive boss, who insults and belittles the person and leaves hurt rather than feedback. The article then sets out three steps for recovering lessons once the type is identified (subscriber article; summary based on the free opening section).","kImp":"사관 리더십 교육이나 사관 회의에서 '내가 겪은 최악의 상급 사관'을 익명 사례로 나누되, 기준이 높은 지적(일에 대한 비판)과 인격 비하(사람에 대한 공격)를 구분하는 토론을 하면 선상 괴롭힘 예방과 피드백 방식 개선을 함께 다룰 수 있다.","eImp":"Officer leadership training or officers' conferences could use anonymised 'worst senior officer' stories and discuss the line between demanding criticism of the work and personal attacks, which supports both anti-harassment efforts on board and better feedback habits.","url":"https://dbr.donga.com/teamleader/view/article_no/186","prio":1,"mar":false,"tags":["FL","TRN"]},{"code":"FRONT","date":"2026-10-06","src":"HR Dive","title":"관리자에게 부하 육성 시간이 있으면 '잔류 의향' 84%, 없으면 41% — Wiley 약 1,500명 조사","eTitle":"The biggest predictor of L&D success? How much time managers can spare.","kSum":"와일리 워크플레이스 인텔리전스가 9월 25일 발표한 약 1,500명 대상 경력 경로 조사에서, 관리자가 부하 육성에 시간을 낼 수 있을 때는 직원의 84%가 회사에 남을 가능성이 매우 높다고 답했지만 그렇지 않을 때는 41%에 그쳤다. 관리자가 곁에 있을 때 조직 문화에 열의를 느낀다는 응답도 76%로, 관리자가 없을 때(23%)의 3배를 넘었다. 몰입을 가장 높일 요인으로는 기술 개발·교육이 멘토링과 승진 투명성보다 많이 꼽혔다. 와일리는 관리자 시간을 보호하고 관리자 가용성을 '문화적 장식'이 아닌 인재 유지 지표로 다루라고 권했다.","eSum":"A Wiley Workplace Intelligence survey of nearly 1,500 people on career pathing, released on September 25, found that 84% of employees are very likely to stay when their manager has time to develop them, versus 41% when the manager does not. Some 76% said they are excited about the culture when their manager is available, compared with 23% when not. Skills development and training topped the factors that would most improve engagement, ahead of mentorship and advancement transparency. Wiley urges employers to protect manager time and treat manager availability as a retention metric, 'not a culture nicety'.","kImp":"선장·기관장·1등 사관이 서류와 점검 대응에 묶이면 하급 사관을 가르칠 시간이 가장 먼저 사라진다. 육상 지원 조직이 선박 행정 부담을 덜어 주는 일이 곧 선원 유지 대책이라는 근거로 쓸 수 있고, 상급 사관의 OJT·멘토링 시간을 따로 기록해 볼 만하다.","eImp":"When masters, chief engineers and chief officers are tied up with paperwork and inspections, time to develop junior officers is the first thing lost. Use this as evidence that cutting shipboard administration from shore is itself a retention measure, and start recording senior officers' time spent on on-the-job training and mentoring.","url":"https://www.hrdive.com/news/the-biggest-predictor-of-ld-success-how-much-time-managers-can-spare/832243/","prio":2,"mar":false,"tags":["FL","RET","TRN"]},{"code":"FRONT","date":"2026-09-22","src":"HR Dive","title":"'AI가 신입 업무를 가져가면 리더는 어디서 크나' — HR 전문가 78% 리더십 역량 개발 공백 우려(Talogy)","eTitle":"HR leaders worry about the loss of critical leadership skill development","kSum":"인재관리 기업 탤로지(Talogy)가 고위 HR 리더·채용 관리자·교육 전문가 200여 명을 조사한 결과, 78%가 AI가 신입 단계 업무를 대신하면서 핵심 리더십 역량 개발이 타격을 받을까 걱정한다고 답했다. 응답자들은 리더 파이프라인에 들어오는 사람이 줄면서 관리 역량이 예전처럼 자연스럽게 자라지 않을 수 있다고 우려했다. 기사에 인용된 IT 기업 GoTo 조사에서는 근로자의 39%, Z세대의 46%가 AI 의존으로 자신이 덜 유능하고 덜 똑똑해졌다고 답했다. 탤로지는 저절로 일어나던 현장 학습을 의도적으로 대체할 방법을 마련하고, 비판적 사고·적응력·협업 같은 인간 역량을 기르며, 리더십 개발을 경력 초기부터 시작하라고 권했다.","eSum":"A Talogy survey of more than 200 senior HR leaders, talent acquisition managers and learning experts found 78% worried that AI taking over entry-level tasks could harm the development of critical leadership skills, as managerial skills may no longer develop as naturally as they once did. A GoTo survey cited in the article found 39% of workers, and 46% of Gen Z, said relying on AI made them feel less competent and less intelligent. Talogy's Ali Shalfrooshan said teaching employees to work alongside AI tools 'simply isn't enough'. The recommendations are to replace lost on-the-job learning more purposefully, build human capabilities such as critical thinking, adaptability and collaboration, and start leadership development early in careers.","kImp":"자동화된 선교와 기관실에서는 하급 사관이 손으로 선위를 구하고 장비를 수동으로 다뤄 보며 판단력을 쌓던 기회가 줄어든다. 승선 교육 계획에 수동 항법·수동 운전 연습과 상급 사관이 자신의 판단 과정을 설명하는 시간을 의도적으로 넣어 '현장에서 저절로 배우던 것'을 메워 볼 만하다.","eImp":"On automated bridges and in automated engine rooms, junior officers get fewer chances to build judgment by fixing positions by hand or running equipment manually. Deliberately schedule manual navigation and manual plant operation practice, plus time for senior officers to talk through their reasoning, to replace the learning that used to happen on its own.","url":"https://www.hrdive.com/news/hr-leaders-worry-about-the-loss-of-critical-leadership-skill-development/830919/","prio":2,"mar":false,"tags":["TRN","AI","FL"]},{"code":"FRONT","date":"2026-09-15","src":"Harvard Business Review","title":"HBR \"승진할수록 '대화 독점·세세한 간섭'을 과소평가한다\" — 전문직 1만 명·고위 리더 400명 연구","eTitle":"You Think You're a Good Collaborator. Do the People You Manage Agree?","kSum":"하이디 가드너(하버드 로스쿨 석좌 펠로)와 이반 마트비악은 1만 명 이상의 전문직과 400명의 고위 리더를 연구한 결과, 사람은 승진할수록 협업을 해치는 두 행동인 대화 독점과 세세한 간섭(micromanaging)을 점점 더 과소평가한다고 밝혔다. 많은 고위 리더가 스스로 경청하고 권한을 주는 협업가라고 여기지만 함께 일하는 사람들의 데이터는 다르게 나타났다. 이런 습관은 전문성을 보여 주고 높은 품질을 고집하던, 과거 성공을 이끈 강점에서 자라난다. 필자들은 자기 행동에 대한 솔직한 데이터를 구하고, 비판적 피드백을 합리화하지 말고, 문제 습관을 구체적인 대체 행동으로 바꾸고, 간단한 자기 점검 장치를 두라고 권한다.","eSum":"Heidi K. Gardner, a distinguished fellow at Harvard Law School, and Ivan Matviak draw on research with more than 10,000 professionals and 400 senior leaders to show that as people advance they increasingly underestimate two collaboration-damaging behaviors: dominating conversations and micromanaging. Most senior leaders describe themselves as listeners who empower others, but data from the people they work with tell a different story. Both habits grow out of strengths that drove earlier success, such as showing expertise and insisting on quality work. The authors recommend seeking honest data on one's own behavior, resisting the urge to rationalize critical feedback, replacing problem habits with specific alternatives and setting up simple accountability structures.","kImp":"경험 많은 선장·기관장일수록 브리핑과 회의에서 말을 독점해 하급 사관의 의견을 막는 권위 경사가 생기기 쉽다. 선박 방문 때 하급 사관에게 상급자 행동을 익명으로 묻는 짧은 피드백을 받아 보고, 리더십 교육에서 '먼저 묻고 나중에 말하기' 같은 대체 행동을 연습시킬 만하다.","eImp":"The more experienced the master or chief engineer, the easier it is to dominate briefings and meetings, steepening the authority gradient that silences junior officers. On ship visits, gather short anonymous feedback from junior officers on senior officers' behavior, and practise replacement habits such as 'ask first, speak last' in leadership training.","url":"https://hbr.org/2026/09/you-think-youre-a-good-collaborator-do-the-people-you-manage-agree","prio":2,"mar":false,"tags":["FL","BRM"]},{"code":"FRONT","date":"2026-08-10","src":"SHRM","title":"SHRM \"지시형 관리만으론 부족, 코칭이 현장 관리자의 필수 역량\" — 상시 코칭 대화 실천법","eTitle":"Coaching Is Becoming a Core Leadership Skill for Frontline Managers","kSum":"SHRM 인도판은 인력의 기대 변화와 디지털화, 조직 전환으로 현장 관리자에게 지시형 관리만으로는 부족해졌고, 코칭이 문제가 커지기 전에 대응하는 선제적 역량이 됐다고 정리했다. 실천법으로 정답을 주기보다 직원이 문제를 풀고 선택지를 따져 보게 하기, 강점과 개선점을 짚는 정기 성장 대화, 적극적 경청과 건설적 피드백, 멘토링·동료 코칭·역할극 훈련, 연간 평가에만 기대지 않는 상시 코칭 대화를 제시했다. 리더 평가에 사업 성과뿐 아니라 직원 육성과 팀 역량 구축을 넣고, 디지털 학습 플랫폼과 대시보드는 코칭 대화를 돕되 대신하지 않게 하라고 권했다.","eSum":"SHRM India argues that changing workforce expectations, digitization and organizational transformation mean directive management alone is no longer enough for frontline managers, and that coaching is a proactive skill for tackling issues before they escalate. Recommended practices include asking employees to work through problems and weigh options instead of handing out instructions, regular development conversations, active listening with constructive feedback, and building coaching skill through mentoring, peer coaching and role-play, with coaching held regularly rather than only at annual reviews. It also advises adding employee development and team capability to leaders' appraisals and using digital platforms and dashboards to support, not replace, coaching conversations.","kImp":"1등 항해사나 1등 기관사가 하급 선원에게 답을 바로 주기보다 '어떻게 하겠나'를 먼저 묻는 코칭 방식은 선상 OJT에 그대로 옮길 수 있다. 상급 사관 평가 항목에 부하 육성 활동을 넣고, 사관 회의에서 코칭 대화 역할극을 해 볼 만하다.","eImp":"Having chief officers and second engineers ask juniors 'how would you handle it?' before giving the answer translates directly into shipboard on-the-job training. Add subordinate development to senior officers' appraisal criteria and role-play coaching conversations at officers' meetings.","url":"https://www.shrm.org/in/topics-tools/news/blogs/coaching-leadership-skill-frontline-managers","prio":1,"mar":false,"tags":["FL","TRN"]}]},{"code":"SAFE","kTitle":"심리적 안전·스피크업·Just culture","eTitle":"Psychological safety, speak-up and just culture","items":[{"code":"SAFE","date":"2026-10-28","src":"해양한국","title":"[기고] “해양안전심판, 징계 위한 증거 수집으로 변질” — 한종길 교수, 일본 JTSB처럼 징계권 없는 독립 해양사고조사위원회 신설과 조사·심판 분리 촉구","eTitle":"[Opinion] 'Korea's Marine Tribunal Has Turned Investigation Into Evidence-Gathering for Discipline': Professor Urges a Japan-Style Independent Accident Investigation Board","kSum":"한종길 성결대 교수는 해양안전심판원이 조사(기소)와 심판(재결) 기능을 한 기관에서 순환 보직으로 운영하면서 사고 조사의 목적이 '안전 권고'가 아닌 '징계를 위한 증거 수집'으로 변질됐고, '원인 불명' 결론을 사실상 금기시해 사소한 규칙 위반을 주요 원인으로 끼워 맞추는 바람에 근본 원인이 가려진다고 비판했다. 처벌 대상이 현장 해기사에서 육상 근무자와 직접 인과관계를 입증하기 어려운 선사 CEO까지 넓어지면서 면피성 서류 작업과 극단적인 방어적 운항이 늘고 있다고 지적했다. 그는 일본이 2008년 원인 규명·안전 권고를 맡는 운수안전위원회(JTSB)를 신설하고 징계는 해난심판소로 분리한 것이 IMO 해양사고 조사코드(MSC.255(84))의 기능적 독립성 권고에 부합한다며, 징계권이 없는 (가칭)국가해양사고조사위원회 신설과 해양안전심판원의 해기사 행정심판 기구로의 축소를 제안했다.","eSum":"Han Jong-gil, a professor at Sungkyul University, argues that because Korea's Maritime Safety Tribunal combines investigation (prosecution) and adjudication in one body staffed by rotation, accident investigation has shifted from producing safety recommendations to collecting evidence for discipline, and that an effective taboo on 'cause unknown' findings leads minor rule breaches to be cast as main causes, hiding root causes. He says punishment has spread from seafarers to shore staff and even shipping company chief executives whose direct causal role is hard to prove, breeding defensive paperwork and extremely defensive operation. Pointing to Japan, which in 2008 created the Japan Transport Safety Board for cause-finding and safety recommendations while leaving discipline to its marine accident tribunal, in line with the functional independence urged by the IMO Casualty Investigation Code (MSC.255(84)), he proposes an independent national marine accident investigation commission without disciplinary powers and a tribunal reduced to an administrative appeals body for officers.","kImp":"사내 사고 조사에서도 '원인 불명'이나 '복합 요인' 결론을 허용하고 징계 판단을 원인 조사와 분리된 절차로 두어, 진술한 사람이 불이익을 걱정하지 않게 하는 구조인지 점검해 볼 만하다.","eImp":"Internal investigations could allow 'cause undetermined' or 'multiple contributing factors' findings and keep disciplinary decisions in a process separate from cause analysis, so that people giving statements do not fear consequences.","url":"https://www.monthlymaritimekorea.com/news/articleView.html?idxno=58006","prio":2,"mar":true,"tags":["JUST","POL"]},{"code":"SAFE","date":"2026-10-28","src":"쉬핑뉴스넷","title":"부산항만공사, 협력업체 근로자 60여 명에 작업중지권·위험 보고 절차 교육 — “위험 발견 즉시 작업중지 요청하고 자유롭게 제안하는 문화” 강조","eTitle":"Busan Port Authority Trains About 60 Contractor Workers on Stop-Work Authority and Hazard Reporting, Calling for a Culture Where Workers Halt Work Without Hesitation","kSum":"부산항만공사는 대·중소기업 안전보건 상생협력사업의 하나로 신항지사 교육장에서 협력업체 근로자 60여 명을 대상으로 전문 강사를 초빙한 안전교육을 열어 작업중지권의 취지와 활용 방안, 위험상황을 발견했을 때의 대응·보고 절차, 안전제안제도 우수 운영사례, 근로자 참여를 통한 안전문화 확산 방안을 실제 사례 중심으로 다뤘다. 송상근 사장은 '근로자가 위험을 발견했을 때 즉시 작업중지를 요청하고 개선 의견을 자유롭게 제안할 수 있는 문화가 조성되어야 한다'고 말했다. 공사는 현장 의견을 들어 작업환경 개선을 지원하고, 사업장별 작업 특성과 주요 위험요인을 반영한 안전수칙과 작업중지권 현수막을 게시할 계획이다.","eSum":"As part of a large-small business safety and health partnership programme, Busan Port Authority brought in an expert trainer for about 60 contractor workers at its New Port branch, covering the purpose and use of stop-work authority, how to respond to and report hazards, good practice in safety suggestion schemes and ways to spread safety culture through worker participation, using real cases. President Song Sang-geun said a safe workplace needs a culture in which workers immediately ask to stop work when they spot danger and freely suggest improvements. The authority plans to gather site feedback to support improvements and to post site-specific safety rules and stop-work authority banners reflecting each workplace's main hazards.","kImp":"수리·검사·하역 인력 같은 협력업체가 승선할 때도 작업 전 회의에서 작업중지권과 보고 경로를 직접 설명하고, 안전을 이유로 작업을 멈춘 사람을 인정하는 순서를 넣어 볼 만하다.","eImp":"When contractors such as repair, survey or cargo teams come aboard, the pre-work meeting could explain stop-work authority and the reporting route directly and acknowledge anyone who has stopped a job for safety reasons.","url":"https://www.shippingnewsnet.com/news/articleView.html?idxno=72687","prio":1,"mar":true,"tags":["SPEAK","PS"]},{"code":"SAFE","date":"2026-10-23","src":"Safety4Sea","title":"SSI '복지에서 리스크로' 보고서: 선원 4분의 1~3분의 1은 우려·실수 보고가 안전하지 않다고 느껴 — 낮은 보고율이 안전의 증거는 아닐 수 있다","eTitle":"SSI's 'From Welfare to Risk' Report: A Quarter to a Third of Seafarers Do Not Feel Safe Raising Concerns, So Low Reporting May Not Mean Safer Ships","kSum":"Sustainable Shipping Initiative(SSI)가 학술연구·사고조사·보험 클레임 데이터·선원 설문 등 68개 자료를 검토한 보고서 'From Welfare to Risk: Tracing the Evidence for Insurers, Investors and Lenders'를 냈다. 피로가 선박 사고·부상과 가장 폭넓게 연결된 위험 요인이며, 인력 부족과 과중한 업무가 근무·휴식시간 기록 조작으로 이어져 만성 피로를 가린다고 봤다. 검토한 근거에 따르면 선원의 4분의 1~3분의 1은 우려 제기나 실수 보고를 안전하다고 느끼지 않아 사고·근접사고 보고가 억눌리며, 보고율이 낮다고 운항이 더 안전하다는 뜻은 아닐 수 있다. 근거가 주로 상관관계 수준이라 SSI는 복지 지표를 보험·금융 판단의 단독 기준이 아닌 기존 위험평가의 보완으로 쓰고, 같은 선박·선대의 복지·사고·검사·클레임 데이터를 연결해 추적하자고 권고했다.","eSum":"The Sustainable Shipping Initiative's report 'From Welfare to Risk: Tracing the Evidence for Insurers, Investors and Lenders' reviews 68 sources, including academic research, accident investigations, insurer claims data and seafarer surveys. Fatigue is the most extensively documented risk factor for casualties and injuries, and understaffing and heavy workloads can lead to falsified work and rest records that hide chronic fatigue. The evidence reviewed suggests that between a quarter and a third of seafarers do not feel safe raising concerns or reporting mistakes, which suppresses incident and near-miss reporting, so low reporting rates may not mean safer operations. Because the evidence is mainly correlational, SSI says welfare indicators should complement rather than replace conventional risk assessment, and urges linked welfare, incident, inspection and claims data for the same ships and fleets over time.","kImp":"근접사고 보고가 적은 선박을 곧바로 '우수 선박'으로 보지 말고, 선박 방문 때 익명 설문이나 면담으로 '보고했다가 불이익을 받을까 걱정되는가'를 함께 확인할 만하다. 휴식시간 기록이 지나치게 완벽한 선박은 실제 작업량과 교차 확인하는 것이 좋다.","eImp":"Ships with few near-miss reports should not be assumed to be the safest; ship visits can add anonymous questions on whether crew fear consequences for reporting. Rest-hour records that look perfectly compliant are worth cross-checking against actual workload.","url":"https://safety4sea.com/seafarer-welfare-emerges-as-key-indicator-of-maritime-safety-and-financial-risks/","prio":3,"mar":true,"tags":["PS","SPEAK","WELL"]},{"code":"SAFE","date":"2026-10-23","src":"Safety4Sea","title":"IMCA 교훈: 승인된 통로 없이 옆 선박으로 건너가려는 선원을 양쪽 브리지가 다 보고도 아무도 막지 않았다 — '개인 실수 아닌 감독·안전 주인의식의 실패'","eTitle":"IMCA Lesson: Both Bridges Saw a Crew Member Cross Between Vessels Without Approved Access and Nobody Intervened","kSum":"IMCA 사례에서 두 선박이 나란히 붙어 있을 때 한 선원이 승인된 갱웨이나 지정 통로 없이 옆 선박으로 건너가려 했고, 행위는 중단됐으며 부상자는 없었다. 이 시도는 양쪽 선박 브리지에서 모두 보였지만 그 단계에서 누구도 개입하지 않았고, 통로 안전 확인과 이동 승인을 누가 맡는지도 정해져 있지 않았다. IMCA는 반복된 이동에 익숙해지고 선박이 안정돼 보여 위험을 과소평가한 '정상화된 불안전 관행'과 절차는 있으나 집행되지 않은 점을 지적하며, 이를 개인 실수가 아닌 감독과 안전 주인의식의 실패로 규정했다. 작업 중지 권한은 안전관리시스템 문서에만 있지 말고 실제로 쓸 수 있게 적극 지지돼야 하며, 불안전한 이동을 본 사람은 누구든 이의를 제기하고 멈추게 하고, 이 사례를 안전회의·툴박스 미팅에서 '개입을 막는 장벽'을 짚는 데 쓰라고 권고했다.","eSum":"In an IMCA case, a crew member tried to move between two vessels lying alongside each other without an approved gangway or designated access; the attempt was stopped and nobody was hurt. The attempt was visible from both bridges, yet no one intervened at that stage, and responsibility for confirming safe access and authorising transfers had not been assigned. IMCA pointed to a normalised unsafe practice, as familiarity and the vessels' apparent stability led people to underestimate the risk, and to procedures that existed but were not enforced, calling it a failure of supervision and safety ownership rather than an individual error. Stop-work authority must be practical and actively supported, not just written into the safety management system; anyone who sees an unsafe transfer should challenge and stop it, and the case should be used in safety meetings and toolbox talks to examine barriers to intervention.","kImp":"안전위원회 회의에서 '봤지만 말하지 않았던 순간'을 한 가지씩 꺼내고 무엇이 개입을 막았는지 묻는 순서를 넣어 볼 만하다. 선박 간 작업 전에는 통로 확인과 이동 승인 담당자를 이름으로 지정하는 것이 좋다.","eImp":"Safety committee meetings can ask each person for one moment when they saw something unsafe but said nothing, and what stopped them. Before ship-to-ship work, name the person responsible for confirming access and authorising transfers.","url":"https://safety4sea.com/lessons-learned-safe-vessel-transfers-require-more-than-stationary-vessels/","prio":1,"mar":true,"tags":["SPEAK","FL"]},{"code":"SAFE","date":"2026-10-21","src":"Japan P&I Club","title":"일본 P&I 클럽 '선원을 위한 선상 안전문화' 웨비나 보고 — 선장·기관장 등 60여 명 참석, '개인 노력만으론 부족, 선원 지식을 모아야'","eTitle":"Japan P&I Club Reports on Its 'Onboard Safety Culture for Crew Members' Webinar for Over 60 Seafarers, Including Masters and Chief Engineers","kSum":"Japan P&I Club이 9월 29일 연 손해예방 웨비나 '선원을 위한 선상 안전문화'에 선장·기관장을 포함한 선원·선상 안전 담당자 60여 명이 참석했다. 프로그램은 벙커링 유류 유출 사고 3건의 원인·대책, 선원 부상 클레임의 부위·유형·원인·선종별 경향, 선상 위험성 평가와 선박-육상이 하나 된 안전관리, 안전 인식(Safety Awareness) 네 부분으로 구성됐다. 안전 인식 세션은 안전이 개인의 노력만으로는 부족하며 선원들의 지식을 모아 의도적인 안전 행동으로 이어가야 한다고 강조했고, 실제 장비를 쓰는 실습으로 안전 습관을 다루었다. 설문 응답자 43명 중 48.8%가 '매우 우수', 51.2%가 '우수'로 평가했으며 사례 연구와 웨비나 횟수를 늘려 달라는 요청이 있었다.","eSum":"Japan P&I Club held a loss prevention webinar, 'Onboard Safety Culture for Crew Members', on 29 September for more than 60 seafarers and shipboard safety personnel, including masters and chief engineers. Sessions covered three bunker spill cases, crew injury claims by location, type, cause and vessel type, practical onboard risk assessment with unified ship-shore safety management, and a safety awareness module. That module argued that safety needs more than individual effort and that crews must pool their knowledge into deliberate safety actions, with hands-on training on real equipment to build habits. Of 43 survey respondents, 48.8% rated the event excellent and 51.2% very good, and some asked for more case studies and more frequent sessions.","kImp":"선상 안전위원회 회의에서 일반적인 주의 당부 대신 '이번 달 우리 배가 함께 찾아낸 위험 한 가지'를 공유하는 순서를 두고, 부상 클레임 경향 자료를 사관 회의 사례로 쓰는 방식을 참고할 만하다.","eImp":"Shipboard safety committee meetings could replace general reminders with one hazard the crew identified together that month, and injury-claim trend data can serve as case material at officers' conferences.","url":"https://www.piclub.or.jp/en/news/45388","prio":1,"mar":true,"tags":["TRN","SS"]},{"code":"SAFE","date":"2026-10-20","src":"Safety4Sea","title":"InterManager: 1996년 이후 밀폐구역 사고 354건·선원 900여 명 설문 — '선원 탓 말고 시스템을 의심하라', 절차와 현장 현실의 격차 지적","eTitle":"InterManager Counts 354 Enclosed Space Accidents Since 1996 and Surveys Over 900 Seafarers, Urging the Industry to Question the System, Not Blame the Seafarer","kSum":"InterManager가 1996~2026년 밀폐구역 사고 354건을 집계하고 선원 900여 명을 설문한 최신 연구를 발표했다. 응답자들은 지나치게 복잡한 서류, 부족한 시간·인력, 상업적 압박, 실습 교육 부족, 사고 근본원인을 다루기 꺼리는 분위기를 절차와 선상 현실 사이 격차의 원인으로 꼽았고, 검사가 절차 준수 여부만 보고 실제 효과는 보지 않는다는 지적도 나왔다. Kuba Szymanski 사무총장은 주어진 시간·인원·장비로 이행할 수 없는 절차라면 '선원을 탓하지 말고 시스템을 의심해야 한다'며 더 단순한 절차, 더 나은 교육, 더 강한 리더십, 설계 개선, 사고 데이터 공유 확대를 우선과제로 제시했다. 선원이 따라야 할 안전 시스템·선박 설계·작업 방식을 만들 때 선원을 직접 참여시키라는 권고도 담겼다.","eSum":"InterManager published research recording 354 enclosed space accidents between 1996 and 2026, together with a survey of more than 900 seafarers. Respondents traced the gap between procedures and onboard reality to overly complex paperwork, inadequate time and manpower, commercial pressure, insufficient practical training and a reluctance to address root causes, and said inspections tend to check procedural compliance rather than whether measures work. Secretary General Capt. Kuba Szymanski said that where procedures cannot realistically be completed with the time, people and equipment available, the industry must question the system, not blame the seafarer, and named simpler procedures, better training, stronger leadership, improved ship design and far greater sharing of accident data as priorities. The research also calls for seafarers to be involved directly in developing the safety systems, designs and working arrangements they must follow.","kImp":"밀폐구역 진입 절차를 선상의 실제 인원·시간으로 직접 따라가 보는 점검을 하고, 선원이 '현실적으로 지킬 수 없는 단계'를 지적하면 비난 없이 절차 개정 의견으로 받는 창구를 열어 둘 만하다. 내부 심사에서는 허가서 서명 여부보다 가스 측정과 구조 준비가 실제로 작동하는지를 묻는 질문을 늘리는 것이 좋다.","eImp":"Walk through enclosed space entry procedures onboard with the people and time actually available, and treat crew reports of steps that cannot realistically be followed as blame-free input for revising procedures. Internal audits can test whether gas testing and rescue arrangements actually work rather than only whether permits are signed.","url":"https://safety4sea.com/intermanager-enclosed-space-deaths-demand-urgent-industry-action/","prio":3,"mar":true,"tags":["JUST","TRN","ENG"]},{"code":"SAFE","date":"2026-10-20","src":"한국해운신문","title":"해운협회 “원인 불분명한 사고로 육상 임직원 형사처벌은 부당” — 스텔라데이지호 항소심 금고형에 성명, 형사재판과 재발 방지 목적의 안전조사 구분 요구","eTitle":"Korea Shipowners' Association Says Punishing Shore Staff Is Unjust When an Accident's Cause Is Unclear, After Stellar Daisy Appeal Sentences","kSum":"한국해운협회는 10월 20일 '해양사고 책임체계 개선을 위한 성명서'를 내고, 2017년 3월 남대서양에서 침몰한 스텔라데이지호 사건 항소심(9월 17일 부산고법)이 선사 회장에게 금고 2년, 전 해사본부장에게 금고 1년 6개월(집행유예 3년), 공무감독에게 금고 10개월(집행유예 2년)을 선고한 데 깊은 유감을 표했다. 협회는 원인이 분명하지 않은 사고에서 결과만으로 육상 임직원을 처벌하면 종사자가 위축되고 회사가 무엇을 해야 할지 기준이 흐려져 유사 사고가 반복될 수 있다며, 재발 방지를 목적으로 하는 IMO 해양안전조사와 형사재판을 구분해야 한다고 주장했다. 또 법원이 한국선급(KR)의 사실 확인서를 특별한 이유 없이 배척했다고 지적하고 설계·건조·검사·운항·기상 등 복합 요인 속에서 임직원 개인의 구체적 기여를 엄격히 따질 것을 요구했으며, 사건은 쌍방 상고로 10월 15일 대법원 제3부에 배정됐다.","eSum":"In a statement on 20 October calling for reform of marine accident liability, the Korea Shipowners' Association expressed deep regret that the Busan High Court's 17 September appeal ruling on the Stellar Daisy, which sank in the South Atlantic in March 2017, imposed two years' imprisonment on the owning company's chairman, 18 months suspended for three years on its former marine division head and ten months suspended for two years on the ship's technical superintendent. The association argued that punishing shore staff on outcomes alone when the cause is unclear would discourage people from the industry, blur what companies should do and risk repeat accidents, and urged a clear separation between criminal trials and IMO-style safety investigations aimed at prevention. It also said the court had rejected a fact statement from Korean Register without good reason and asked for strict proof of each individual's contribution amid design, construction, survey, operational and weather factors; both sides have appealed and the case was assigned to the Supreme Court's third division on 15 October.","kImp":"조사 보고서가 형사 증거로 쓰일 수 있는 환경에서도 선원과 육상 직원이 사실을 말할 수 있도록, 사내 조사는 원인과 재발 방지 중심으로 쓰고 개인 비난 표현을 빼는 원칙을 조사팀과 다시 확인해 볼 만하다.","eImp":"Where investigation reports may end up as criminal evidence, it is worth reconfirming with investigation teams that internal reports focus on causes and prevention and avoid language assigning personal blame, so crew and shore staff keep speaking openly.","url":"https://www.maritimepress.co.kr/news/articleView.html?idxno=333548","prio":2,"mar":true,"tags":["JUST","POL"]},{"code":"SAFE","date":"2026-10-15","src":"Safety4Sea","title":"분석: MLC 준수 서류가 선원 보호를 보장하진 않는다 — 불만 신고가 적은 건 두려움 탓일 수도, '종결된 시정조치'가 문제 해결을 뜻하진 않아","eTitle":"Analysis: MLC Compliance Records Can Mask Fatigue and Fear of Reporting, So Low Complaint Numbers and Closed Corrective Actions Prove Little","kSum":"SAFETY4SEA 분석 기사는 인증서·검사·기록·심사로 이뤄진 MLC 준수가 필요하지만 선원이 실제로 보호받는지는 보여주지 못한다고 지적했다. 불만 건수가 적은 것은 좋은 여건 때문일 수도 있지만 신고 경로를 모르거나 신뢰가 낮거나 보복이 두려워서일 수도 있으며, WMU 설문에서 응답자 88.3%가 매달 한 번 이상 근무·휴식 한도를 넘긴다고 답했지만 기록을 조정한 적이 전혀 없다는 응답은 31.6%였고, 2024년 WMU 연구에서는 검사상 준수율 90~99.3%와 자기 보고 준수율 11.7~16.1%가 크게 엇갈렸다. 시정조치를 종결했다고 근본 문제가 풀린 것은 아니며, 선대 전반에 반복되는 지적은 개별 사건이 아닌 조직적 실패로 보고 인력·일정·예산을 결정하는 사람에게까지 책임이 닿아야 한다고 강조했다. 기밀 선원 설문과 구조화된 피드백을 기존 준수 체계와 병행하고, 지적이 반복되는 이유를 분석하며, 근무·휴식 기록을 업무량·인원·일정과 연결해 검증하라고 권고했다.","eSum":"A SAFETY4SEA analysis argues that MLC compliance through certificates, inspections, records and audits is necessary but does not show whether seafarers are actually protected. Low complaint numbers may reflect good conditions, poor awareness of reporting channels, weak trust or fear of retaliation; in a WMU survey 88.3% of respondents exceeded work and rest limits at least monthly while only 31.6% said they had never adjusted their records, and a 2024 WMU study set inspection compliance rates of 90% to 99.3% against self-reported compliance of 11.7% to 16.1%. Closing a corrective action does not mean the problem is solved, and recurring deficiencies across a fleet should be treated as organisational failures, with accountability reaching those who control manning, schedules and budgets. The article recommends confidential crew surveys alongside compliance systems, analysis of why deficiencies recur, and verification of rest records against workload, staffing and scheduling.","kImp":"같은 지적이 여러 선박에서 반복되면 선박별 시정조치 종결로 끝내지 말고 인원·일정·예산 결정 단계까지 근본원인 검토를 올려 볼 만하다. 불만·보고가 '0건'인 선박은 오히려 신고 경로 인지도와 신뢰를 익명 설문으로 확인하는 것이 좋다.","eImp":"When the same finding recurs across several ships, take the root-cause review up to manning, scheduling and budget decisions instead of closing each ship's corrective action. Ships reporting zero complaints are worth an anonymous check on awareness of and trust in reporting routes.","url":"https://safety4sea.com/cm-analysis-why-mlc-compliance-alone-is-not-enough-to-protect-seafarers/","prio":2,"mar":true,"tags":["SPEAK","JUST","WELL"]},{"code":"SAFE","date":"2026-10-15","src":"쉬핑뉴스넷","title":"인천항만공사 ‘2026 인천항 아차사고 콘테스트’(10.16~11.15) — 임직원·협력업체 근로자가 겪은 아차사고와 개선 아이디어 접수, 내년 위험성평가·교육 자료에 반영","eTitle":"Incheon Port Authority Runs a Month-Long Near-Miss Contest for Staff and Contractors, Feeding Submissions Into Next Year's Risk Assessments and Training","kSum":"인천항만공사는 현장 중심의 사고예방 문화를 정착시키려고 10월 16일부터 11월 15일까지 임직원과 협력업체 근로자를 대상으로 작업 현장에서 직접 겪거나 목격한 아차사고 사례와 개선 아이디어를 공사 SNS의 QR코드로 받는 '2026 인천항 아차사고 콘테스트'를 연다. 접수 사례는 구체성·시급성·개선 효과를 종합해 우수 사례를 뽑아 소정의 상품을 주고, 수집된 사례는 내년도 정기 위험성평가와 안전보건교육 자료에 반영해 인천항의 유해·위험요인 발굴과 개선에 쓴다. 공사는 기간과 관계없이 누구나 위험요인을 신고할 수 있는 '인천항 안전신문고'도 상시 운영하며, 사장은 '현장의 작은 아차 한 번을 그냥 넘기지 않는 것이 큰 사고를 막는 출발점'이라고 말했다.","eSum":"To embed a frontline accident-prevention culture, Incheon Port Authority is running the 2026 Incheon Port Near-Miss Contest from 16 October to 15 November, inviting its staff and contractor workers to submit near misses they experienced or witnessed at work, with improvement ideas, via a QR code distributed on its social media. Entries are judged on specificity, urgency and improvement effect, winners receive prizes, and the cases will be built into next year's regular risk assessments and safety and health training and used to find and fix hazards in the port. The authority also runs a year-round hazard reporting channel open to anyone, and its president said that not letting a single small near miss pass is the starting point for preventing major accidents.","kImp":"근접사고 보고를 한시적 캠페인으로 모아 구체성과 개선 효과로 평가하고, 선정 사례가 다음 해 위험성평가와 교육 자료에 실제로 반영됐다는 사실을 선원에게 돌려 알리면 보고 동기를 높일 수 있다.","eImp":"A time-limited near-miss drive judged on specificity and improvement effect, followed by telling crews which reports changed the next year's risk assessments and training, could strengthen the motivation to report.","url":"https://www.shippingnewsnet.com/news/articleView.html?idxno=72475","prio":1,"mar":true,"tags":["SPEAK"]},{"code":"SAFE","date":"2026-10-14","src":"Ship Management International","title":"런던 인적요소 패널: 부상은 승선 첫 3개월·오전 8~10시에 몰리지만 이를 위험 시기로 본 선원은 4.2% — '엄격한 위계는 두려움에 의한 순응을 낳는다'","eTitle":"London Human Factors Panel: Injuries Cluster in the First Three Months Aboard, Yet Only 4.2% of Surveyed Seafarers See That Period as Riskiest","kSum":"런던에서 열린 해사 안전·인적요소 패널에서 OneCare Group 심리학자 Loukia Pantelidi와 Marine Medical Solutions CEO Jens Tülsner 박사가 Gard의 2026년 선원 클레임 보고서와 OneCare 선원 위험 인식 설문 중간 결과를 비교했다. Gard 자료에서 부상은 계약 첫 3개월, 오전 8~10시, 계획된 일상 작업 중에 가장 많았지만, 설문에서 첫 3개월을 가장 위험한 시기로 꼽은 선원은 4.2%뿐이었고 60%는 위험이 계약 내내 비슷하다고, 절반은 야간 당직을 위험 시기로 봤다. Pantelidi는 엄격한 위계가 심리적 안전이 아닌 두려움에 의한 순응을 낳아 근접사고가 보고되지 않게 만든다고 했고, Tülsner는 출신 문화에 따라 우려를 표현하는 방식이 다르다는 점을 조직이 인식해야 하며 리더는 자기성찰과 진정성을 보여야 한다고 말했다. 패널은 피로를 맥락 속에서 측정하되, 사생활이 적은 선상에서 수면 추적 웨어러블이 또 하나의 통제 도구가 될 수 있다고 경고했다.","eSum":"A London maritime safety and human factors panel with OneCare Group psychologist Loukia Pantelidi and Marine Medical Solutions CEO Dr Jens Tülsner compared Gard's 2026 crew claims report with interim results from OneCare's survey of seafarers' risk perception. Gard's data put injuries mostly in the first three months of a contract, between 8am and 10am and during planned routine work, yet only 4.2% of surveyed seafarers named the first three months as the riskiest period, 60% thought risk stayed constant and half pointed to night watches. Pantelidi said strict hierarchies can produce compliance through fear rather than psychological safety, leaving near misses unreported, while Tülsner said organisations must recognise that seafarers from different cultures voice concerns differently and that leaders need self-reflection and authenticity. The panel urged measuring fatigue in context but warned that wearable sleep trackers could become another tool of control given limited privacy aboard.","kImp":"신규 승선자 첫 3개월과 오전 작업 시간대를 위험 구간으로 선원에게 명확히 알리고, 승선 직후 멘토 배정이나 첫 주 작업 브리핑을 강화해 볼 만하다. 국적별로 우려 표현 방식이 다르다는 점을 감안해 안전회의에서 공개 발언 외에 익명 메모나 일대일 확인 경로를 함께 두는 것이 좋다.","eImp":"Make the first three months aboard and morning work hours explicit risk periods for new joiners, with stronger first-week briefings or mentoring. Since crews of different nationalities voice concerns differently, safety meetings can offer anonymous notes or one-to-one check-ins alongside open discussion.","url":"https://www.shipmanagementinternational.com/news/r7hlhadfyf87dzh-zfkd8-pgwgk-hf6wx-rfm23-fj7c2-jad6a-6adm4-b9bc9-hdjnd-8l54d-p2skx-ylb8x-t9zkt-wb47e-s3d2d-84np4-c2s2p","prio":2,"mar":true,"tags":["PS","SPEAK","XC"]},{"code":"SAFE","date":"2026-10-13","src":"쉬핑뉴스넷","title":"2026 해사안전 리더상 후보 공모(10.14~11.10) — 선원·안전관리자에 더해 올해부터 안전투자 공시 선사 직원도 대상, 최대 4명 장관 표창","eTitle":"Korea Opens 2026 Maritime Safety Leader Award Nominations, Adding Staff of Shipping Companies That Disclose Safety Investment","kSum":"해양수산부와 한국해양교통안전공단은 현장에서 해양 안전을 지켜온 숨은 영웅을 발굴해 안전 문화를 확산하려고 2020년부터 운영해 온 '대한민국 해사안전 리더상'의 2026년 후보를 10월 14일부터 11월 10일까지 추천받는다. 선원과 선박 안전관리자에 더해 올해는 2026년부터 시행된 해사 안전 투자 공시 제도에 따라 안전 분야 투자 내역을 공시한 선사 직원도 대상에 포함되며, 기관·단체·개인 누구나 추천할 수 있다. 공적심사위원회 심의를 거쳐 12월에 최대 4명을 확정해 장관 표창과 포상금 500만 원을 주고 공적을 해수부 누리집 등에 알린다.","eSum":"The Ministry of Oceans and Fisheries and the Korea Maritime Transportation Safety Authority are taking nominations from 14 October to 10 November for the 2026 Maritime Safety Leader Award, run since 2020 to recognise unsung frontline heroes of maritime safety and spread safety culture. Seafarers and ship safety managers are eligible, and this year staff of shipping companies that have disclosed their safety investment under the disclosure scheme introduced in 2026 are also included; any organisation, group or individual may nominate. After review by a merit committee, up to four winners will be confirmed in December and receive a ministerial commendation and KRW 5 million, with their achievements publicised on the ministry website.","kImp":"근접사고를 먼저 보고하거나 작업을 멈춰 사고를 막은 선원·안전관리자의 사례를 정리해 추천하고, 같은 사례를 선단 안전 회람에서 공유해 '말한 사람이 인정받는다'는 신호를 줄 만하다.","eImp":"Cases where a seafarer or safety manager prevented an accident by reporting a near miss early or stopping work could be written up for nomination and shared in fleet safety circulars, signalling that speaking up is recognised.","url":"https://www.shippingnewsnet.com/news/articleView.html?idxno=72433","prio":1,"mar":true,"tags":["FL","POL"]},{"code":"SAFE","date":"2026-10-06","src":"Safety4Sea","title":"IMCA 교훈: 날씨가 나빠지는데도 두 선장 모두 작업을 멈추지 않았다 — 화물 슬링으로 연결된 채 선미 접촉, '작업 중지 권한은 모두에게'","eTitle":"IMCA Lesson: Neither Master Stopped a Deteriorating Alongside Transfer, Ending in Stern Contact While Still Linked by a Cargo Sling","kSum":"IMCA 사례에서 두 선박이 나란히 붙어 자재를 옮기던 중 바람과 너울이 빠르게 강해졌고, 한 척이 선수 방향·위치 제어를 잃고 다른 선박 쪽으로 밀렸으나 화물 슬링이 여전히 두 선박을 잇고 있어 떨어질 수 없었고 결국 선미끼리 접촉해 양쪽이 손상됐다. 위치 유지가 한계에 이르렀는데도 어느 선장도 작업 중지 권한을 쓰지 않았고 아무도 작업 종료를 분명히 결정하지 않았으며, 두 브리지 사이에 상황 인식 공유와 선제적 의사결정이 약했다. 위험성 평가에 최대 풍속·파고 같은 측정 가능한 중지 기준이 없어 이미 어려운 상황에서 판단에 맡겨진 것도 원인으로 지적됐다. 작업 전 수치화된 '레드 라인' 설정·공유, 두 선박 합동 사전 브리핑(책임·통신·분리 절차·한계), 선장부터 갑판원까지 상업적 불이익 걱정 없이 작업을 멈출 수 있는 환경을 권고했다.","eSum":"In an IMCA case, two vessels transferring materials alongside saw wind and swell build quickly; one lost heading and position control and drifted into the other, and because a cargo sling still connected them neither could pull clear, so they made stern contact and both were damaged. Neither master used their authority to suspend the operation as position-keeping became marginal, nobody clearly decided to end the work, and the two bridges lacked shared situational awareness and proactive decision-making. The risk assessment set no measurable weather limits such as maximum wind speed or wave height, leaving the stop decision to judgement once conditions were already difficult. Recommendations include measurable red lines agreed before work, a joint pre-operation briefing on responsibilities, communication, separation procedures and limits, and an environment where anyone from master to deck crew can stop work without fear of commercial repercussions.","kImp":"선박 간 작업이나 협력 작업의 위험성 평가에 '이 수치를 넘으면 멈춘다'는 정량 기준을 넣고, 작업 전 툴박스 미팅에서 누구나 중지를 외칠 수 있다는 점과 그 신호를 명시적으로 확인해 볼 만하다. 작업을 멈춘 사례를 안전위원회에서 칭찬 사례로 공유하는 것도 좋다.","eImp":"Risk assessments for ship-to-ship or joint operations can set numeric stop limits, and toolbox talks can confirm explicitly that anyone may call a stop and how. Safety committees can share cases where work was stopped as examples to praise.","url":"https://safety4sea.com/lessons-learned-everyone-has-authority-to-stop-unsafe-operations/","prio":2,"mar":true,"tags":["SPEAK","BRM","FL"]},{"code":"SAFE","date":"2026-10-02","src":"Safety4Sea","title":"CHIRP 교훈: 너울 속 텐더 예인 준비 중 VHF 지연·CCTV 정지로 선장이 위치 판단 못 해 — '통제를 잃었을 때 멈추는 것은 실패가 아니다'","eTitle":"CHIRP Lesson: VHF Delays and Frozen CCTV Left the Bridge Unable to Judge a Tender's Position in Heavy Swell, and Stopping Is Not a Failure","kSum":"CHIRP 보고 사례에서 높은 너울 속에 텐더를 예인하려고 본선 옆에 붙여 두고 갑판장은 텐더 위에서, 갑판원은 예인 훅을 풀고, 1등항해사는 펜더로 텐더를 선체에서 떼어 놓고 있었다. 1등항해사가 VHF로 선장에게 '조금 전진'을 요청했지만 통신이 끊겨 응답이 늦었고, 카메라 영상이 멈추거나 지연돼 선장은 텐더 위치를 판단해 추진을 고르지 못했으며, 텐더가 난간에 끼여 난간이 휘었다(부상자 없음). CHIRP는 통신과 감시가 나빠지자 팀의 공유된 이해가 약해졌다고 보고, 통신·감시·확실한 통제 중 하나라도 믿을 수 없게 되면 통제가 회복될 때까지 작업을 멈추라는 규칙을 제시하며 이때 멈추는 것은 실패가 아니라 필수 안전 통제라고 강조했다. 관리자에게는 통신 저하와 시야 상실에 대비한 비상 계획과 동적 위험성 평가를 권고했다.","eSum":"In a CHIRP report, a tender was being readied for tow alongside in high swell, with the bosun on the tender, a deck hand disconnecting the towing hook and the chief officer holding the tender off with a fender. The chief officer's VHF request for the captain to bump ahead was delayed by communication interruptions, and frozen, delayed camera images left the captain unable to judge the tender's position, so it became trapped against the rail, which was bent; no one was hurt. CHIRP said the team's shared understanding weakened once communication and monitoring degraded, and set a stop rule: if communication, monitoring or positive control becomes unreliable, pause until control is restored, because stopping then is not a failure but an essential safety control. Managers are urged to plan for degraded communications and loss of visual monitoring and to use dynamic risk assessment.","kImp":"계류·예인·보트 작업 브리핑에 'VHF가 끊기거나 시야를 잃으면 무조건 정지'라는 사전 합의와 대체 신호(수신호·호각)를 넣어 볼 만하다. 사관 회의에서 '멈춘 것은 실패가 아니다'라는 메시지를 경영진이 직접 전하는 것이 효과적이다.","eImp":"Mooring, towing and boat-handling briefings can agree in advance that loss of VHF or visual monitoring means an automatic stop, with backup hand or whistle signals. Senior management can state at officers' conferences that stopping is not a failure.","url":"https://safety4sea.com/lessons-learned-good-seamanship-is-knowing-when-to-stop-and-reassess/","prio":1,"mar":true,"tags":["SPEAK","BRM","SS"]},{"code":"SAFE","date":"2026-09-22","src":"The Mission to Seafarers","title":"'선원 행동강령 5년' 보고서: 심각한 우려를 두려움 없이 말할 수 있다는 선원 59%뿐 — 정신건강 지원이 있어도 17%는 이용이 안전하지 않다고 느껴","eTitle":"Five Years of the Seafarers' Rights Code of Conduct: Only 59% of Seafarers Would Feel Safe Raising a Serious Concern Without Fear of Consequences","kSum":"SSI·IHRB·Mission to Seafarers·Rafto 재단·RightShip·TURTLE이 함께 낸 'Five Years into the Code of Conduct: What's Changed for Seafarers?' 보고서는 RightShip 선원복지 자가평가(CWSA, 1,000여 개사·13,000척 이상·선원 약 30만 명)와 새로 의뢰한 선원 연구 2건을 바탕으로 했다. 심각한 우려를 불이익 걱정 없이 제기할 수 있다는 선원은 59%에 그쳤고 나머지는 '아니다' 또는 '모르겠다'였으며, 직전 계약에서 피로나 휴식시간 위반 없이 안전하게 일할 만큼 인원이 충분했다는 응답은 49%였다. 정신건강 지원은 56%가 있고 안심하고 쓸 수 있다고 답했지만 17%는 지원이 있어도 이용이 안전하지 않다고 느꼈고 27%는 아예 없었다. CWSA 참여사 이행률은 공정 고용조건 90%, 인력 배치 88%, 선원 웰빙 76%(최저)였고, 정신건강 교육은 2024년 64%에서 76%로 늘었으며 인터넷 요금을 받는 회사는 18.4%에서 8.5%로 줄었다.","eSum":"'Five Years into the Code of Conduct: What's Changed for Seafarers?', published by SSI, IHRB, the Mission to Seafarers, the Rafto Foundation, RightShip and TURTLE, draws on RightShip's Crew Welfare Self-Assessment, covering more than 1,000 companies, over 13,000 vessels and around 300,000 seafarers, plus two new seafarer studies. Only 59% of seafarers said they would feel safe raising a serious concern without fear of consequences, with the rest saying no or unsure, and 49% said their last contract had enough crew to work safely without excessive fatigue or rest-hour breaches. While 56% had confidential mental health support they would feel safe using, 17% had support but would not feel safe using it and 27% had none. Among CWSA participants, attainment was 90% for fair terms, 88% for crewing and 76% for crew wellbeing, the lowest area; mental health training rose from 64% in 2024 to 76%, and companies charging for internet fell from 18.4% to 8.5%.","kImp":"회사의 스피크업 경로가 있어도 선원 10명 중 4명은 쓰지 않을 수 있다는 전제로, 선박 방문 때 '최근 말하기 어려웠던 우려'를 익명으로 받는 짧은 설문을 돌려 볼 만하다. 정신건강 지원 창구의 비밀 보장 방식을 승선 전·선상 회의에서 구체적으로 설명하면 이용 장벽을 낮출 수 있다.","eImp":"Assume that even with company speak-up channels about four in ten crew may not use them, and run short anonymous ship-visit surveys on concerns that felt hard to raise. Explaining exactly how confidentiality works in mental health support, before joining and at shipboard meetings, can lower the barrier to using it.","url":"https://www.missiontoseafarers.org/news/seafarer-welfare-is-improving-amongst-leading-companies-but-five-years-of-evidence-shows-this-progress-is-far-from-the-norm","prio":3,"mar":true,"tags":["SPEAK","PS","WELL"]},{"code":"SAFE","date":"2026-09-17","src":"MarineLink","title":"ClassNK Saito 선장 기고: '형식적 준수는 출발점일 뿐' — 사람은 오류의 원천이자 이상 상황이 사고로 번지는 걸 막는 회복력의 원천, 자동 권고에 기대면 시스템에 이의 제기를 덜 하게 된다","eTitle":"ClassNK's Capt. Naoki Saito: Compliance Is the Baseline, People Are a Source of Resilience, and Over-Reliance on Automation Erodes the Willingness to Challenge","kSum":"ClassNK 사이버보안·선박관리시스템 부서장 Naoki Saito 선장은 Maritime Reporter 기고에서 절차와 규정은 일관성과 책임을 주는 공통 최저선이지만 형식적 준수는 목표가 아닌 출발점이며, 요건을 다 갖춘 선박도 성과는 나쁠 수 있다고 썼다. 사람은 오류의 원천일 뿐 아니라 이상 상황이 사고로 번지는 것을 막는 회복력의 원천이며, 조직의 성숙도는 문서의 양이 아니라 예측·대응·회복·학습 능력과 절차의 목적을 이해하는 구성원으로 판단해야 한다고 했다. 자동화된 권고에 크게 기대면 독자적인 상황 해석 능력이 약해지고 시스템에 이의를 제기하려는 의지가 줄어 수동적 수용으로 흐를 수 있으며, 안전 책임은 알고리즘으로 넘어가지 않는다고 경고했다. TMSA·DryBMS·SIRE 2.0·RightShip RISQ 3.2가 절차의 존재보다 실제 운영 효과·인적 요소·역량·행동을 보는 쪽으로 옮겨 가고 있다며, 심사도 문서 완비 확인에서 실제로 안전이 작동하는지를 보는 위험 기반·예외 기반 방식으로 바뀔 수 있다고 내다봤다.","eSum":"In a bylined contribution to Maritime Reporter, Capt. Naoki Saito, head of ClassNK's cyber security and ship management systems department, writes that procedures and regulations provide a common minimum, consistency and accountability, but formal compliance should be the baseline rather than the goal, and a ship can meet every requirement and still perform poorly. People are a source of resilience as well as error, often stopping abnormal situations from becoming accidents, and organisational maturity should be judged by the ability to anticipate, respond, recover and learn, and by staff who understand the purpose of procedures, not by the volume of documentation. Heavy reliance on automated recommendations can erode independent interpretation and make operators less willing to challenge a system, and responsibility for safety does not transfer to algorithms. Saito notes that TMSA, DryBMS, SIRE 2.0 and RightShip's RISQ 3.2 are shifting toward operational effectiveness, human factors, competency and behaviour, and expects audits to move from checking documents toward risk-based and exception-based assessment of whether safety works in practice.","kImp":"사고·근접사고 검토에 '누가 무엇을 해서 사고로 번지지 않았나'를 함께 기록해 잘된 대응을 공유하는 칸을 만들어 볼 만하다. 항해·기관 자동화 장비의 권고를 사관이 교차 확인하고 이의를 제기한 사례를 사관 회의에서 다루는 것도 좋다.","eImp":"Incident and near-miss reviews can add a field recording who did what to stop the event escalating, so good responses are shared too. Officers' conferences can discuss cases where officers cross-checked and challenged recommendations from automated navigation or engine systems.","url":"https://www.marinelink.com/news/human-perspective-future-maritime-safety-543022","prio":1,"mar":true,"tags":["SPEAK","AI","TRN"]},{"code":"SAFE","date":"2026-09-16","src":"Safety4Sea","title":"ShipIn·NorthStandard '해사 리스크 보고서 2026': 선박 29%가 사고의 약 70% 차지 — 사고 잦은 선박엔 무인 브리지·당직 중 휴대폰 같은 작은 신호가 수천 번 반복","eTitle":"ShipIn and NorthStandard's Maritime Risk Report 2026: About 29% of Vessels Account for Nearly 70% of Accidents, With Small Warning Signs Repeated Beforehand","kSum":"ShipIn Systems와 NorthStandard가 관리선 600여 척의 운항 데이터(ShipIn FleetVision)와 Lloyd's List Intelligence SeaSearcher 사고 데이터를 결합한 'Maritime Risk Report 2026'을 냈다. 선박의 약 29%가 보고된 사고의 70% 가까이를 차지했고, 사고율이 높은 선박일수록 평상시 운항에서 조기 경고 신호가 더 자주 나타났다. 정박 중 무인 브리지, 당직 중 휴대폰 사용, PPE 위반, 불안전한 갑판 작업 같은 신호는 하나하나는 사소하지만 해당 선박에서는 한 해 수천 번 기록될 만큼 반복되며, 사고 관련 패턴이 몇 주~몇 달 전부터 있었을 수 있다고 보고서는 밝혔다. 보고서는 선대 일률적 안전 관리 대신 위험이 몰린 곳에 관심을 집중하고 안전을 사후가 아닌 사전에 측정하자고 제안했으며, 누락된 점검·일관성 없는 감독·늦은 대응을 인력 부족에 따른 업무 압박과 연결했다.","eSum":"ShipIn Systems and NorthStandard's Maritime Risk Report 2026 combines operational data from about 600 managed vessels on ShipIn's FleetVision platform with casualty data from Lloyd's List Intelligence SeaSearcher. About 29% of vessels accounted for nearly 70% of reported accidents, and vessels with higher incident rates showed early warning signs more often in routine operations. Signals such as an unattended bridge at anchor, phone use on watch, PPE breaches and unsafe deck procedures are minor individually but can be recorded thousands of times a year on affected ships, and incident-related patterns may be present for weeks or months beforehand. The report argues against uniform fleet-wide safety approaches in favour of targeting attention where risk concentrates and measuring safety before incidents, linking missed checks, inconsistent supervision and delayed responses to workload pressure from crew shortages.","kImp":"선박 방문·내부 심사 일정을 선대에 고르게 나누기보다 근접사고·점검 지적·인원 교체 같은 선행 지표가 몰린 선박에 먼저 배정해 볼 만하다. 당직 중 휴대폰 사용 같은 '작은 신호'를 선장과 정기적으로 함께 짚는 것도 좋다.","eImp":"Ship visits and internal audits can be prioritised toward ships where leading indicators such as near misses, inspection findings and crew turnover cluster, rather than spread evenly. Small signals such as phone use on watch are worth reviewing regularly with masters.","url":"https://safety4sea.com/study-a-small-share-of-vessels-accounts-for-most-maritime-accidents/","prio":2,"mar":true,"tags":["FL","AI"]},{"code":"SAFE","date":"2026-09-08","src":"Safety4Sea","title":"기고: 선원 웰빙은 복지 프로그램이 아닌 안전 의무 — 교대 기간·정원·당직 패턴을 정하는 사람이 심리사회적 위험의 주인, 보고는 '조직 정의'에 대한 신뢰에 달렸다","eTitle":"Opinion: Crew Wellbeing Is a Safety Obligation Owned by Those Who Set Rotations, Manning and Watch Patterns, and Reporting Depends on Organisational Justice","kSum":"Wellbeing Daily 창업자 Ian Collins는 SAFETY4SEA 기고에서 선원행복지수가 2015~2016년 6점대 초반에서 2026년 1분기 7.18까지 올랐다가 2분기 6.87로 떨어졌고 상륙 휴가가 5.72로 최저라며, 지난 10년의 개선은 회사가 제공한 것에서 나왔을 뿐 위험을 만드는 조건은 바뀌지 않았다고 주장했다. 업무량·직무 통제·대인관계와 괴롭힘·조직 정의 같은 ISO 45003 심리사회적 위험은 교대 기간·정원·당직 패턴·통신 예산 같은 육상 결정에서 비롯되므로 그 결정을 내리는 사람이 위험을 소유해야 한다는 것이다. 안전관리시스템은 보고에 의존하고 보고는 '보고하면 조치되고 다음 계약까지 따라오지 않는다'는 신뢰에 달려 있으며, 소형 선박에서는 설문이 개인을 드러낼 수 있어 깨끗한 결과가 낮은 위험이 아니라 낮은 신뢰를 뜻할 수 있다고 지적했다. 30척 선대에서는 휴업재해 1건의 재분류로 LTIF가 약 3분의 1 움직일 수 있다며, 선박별 심리사회적 위험 평가를 위험 등록부에 올리고, 휴식시간 기록이 한도 근처에 몰리는지 분석하며, 밀폐구역·계류·고소작업 같은 치명 위험 통제의 실태를 매달 점검하라고 권고했다.","eSum":"In a SAFETY4SEA opinion piece, Ian Collins, founder of Wellbeing Daily, notes that the Seafarers Happiness Index rose from the low sixes in 2015-2016 to 7.18 in Q1 2026 before falling to 6.87 in Q2, with shore leave lowest at 5.72, and argues that a decade of gains came from what companies provide while the conditions that create risk have not changed. ISO 45003 psychosocial hazards such as workload, job control, interpersonal relationships and harassment, and organisational justice originate in shoreside decisions on rotations, manning, watch patterns and connectivity, so whoever makes those decisions should own the hazard. Safety management systems depend on reporting, which depends on trust that reports will be acted on and will not follow seafarers to later contracts, and on small ships surveys can identify individuals, so a clean result may reflect low trust rather than low risk. Noting that reclassifying one lost-time case can shift a 30-ship fleet's LTIF by about a third, he recommends vessel-level psychosocial assessments in the risk register, analysis of whether rest-hour records cluster near the limit, and monthly checks that controls for fatal risks such as enclosed space entry, mooring and working aloft are in place.","kImp":"선박별 휴식시간 기록 분포를 뽑아 한도 바로 아래에 몰린 선박을 찾고, 선박 방문 때 실제 작업량과 맞춰 보는 점검을 해 볼 만하다. 소형 선박 설문 결과는 개인이 드러나지 않게 선대 단위로 묶어 공유하는 것이 좋다.","eImp":"Plot each ship's rest-hour records to find those clustering just under the limit and compare them with actual workload during visits. Small-ship survey results are best aggregated at fleet level so individuals cannot be identified.","url":"https://safety4sea.com/crew-wellbeing-is-a-safety-obligation-not-a-welfare-programme/","prio":1,"mar":true,"tags":["JUST","WELL","SPEAK"]},{"code":"SAFE","date":"2026-08-26","src":"Safety4Sea","title":"마셜제도 조사: 벤젠 탱크 들어간 1등항해사 사망 — '육상·선상 모두 안전문화 비효과적', 선장은 구조하러 직접 진입, 부원들은 작업중지 권한 쓸 자신 없었을 수도","eTitle":"RMI Investigation: A Chief Officer Dies in a Benzene Cargo Tank Amid an Ineffective Safety Culture Ashore and Aboard","kSum":"마셜제도(RMI) 해사청 조사에 따르면 2025년 8월 25일 오전 벤젠을 운송한 뒤 탱크 세정·가스 프리를 하던 유조·케미컬선에서 1등항해사가 개인용 가스 검지기 없이 3번 좌현 탱크에 들어갔다가 약 5분 만에 쓰러져 숨졌다. 가스 프리가 효과적이지 않았고 진입 전 회사 절차대로 대기를 측정하지 않았으며, 선장은 안전 총책임자로서의 역할과 달리 호흡구를 쓰고 직접 탱크에 들어가 구조를 도왔다. 조사는 육상과 선상 모두의 안전문화가 비효과적이었고 육상 관리와 선장이 세정·가스 프리·진입을 효과적으로 감독하지 못했으며, 갑판 부원들이 불안전 조건을 알아채지 못했거나 작업중지 권한을 쓸 자신이 없었을 수 있다고 결론지었다. 밀폐구역 구조훈련이 실제 비상 대비가 아닌 각본대로 진행됐을 가능성, 부정확한 근무·휴식 기록도 함께 지적됐다.","eSum":"An investigation by the Marshall Islands Maritime Administrator found that on the morning of 25 August 2025, during tank washing and gas freeing after a benzene cargo, the chief officer of an oil and chemical tanker entered No. 3 port cargo tank without a personal gas detector and collapsed within about five minutes, later pronounced dead. Gas freeing had not been effective, the atmosphere had not been tested before entry as company procedures required, and the master, contrary to his overall responsibility for safety, entered the tank himself with breathing apparatus to help. The investigation concluded that safety culture was ineffective both ashore and on board, that shore management and the master provided ineffective oversight of cleaning, gas freeing and entry, and that deck ratings may not have recognised unsafe conditions or felt confident using stop-work authority. It also found enclosed space rescue drills were likely pre-scripted rather than realistic and that work and rest records were not accurately kept.","kImp":"밀폐구역 구조훈련을 각본 없이 '예고 없는 시나리오'로 돌리고, 훈련 중 선장이 직접 진입하지 않고 지휘에 머무는지를 관찰 항목으로 넣어 볼 만하다. 부원이 상급 사관의 진입을 멈춰 세울 수 있는지 안전위원회에서 직접 물어보는 것도 좋다.","eImp":"Run enclosed space rescue drills as unscripted scenarios and observe whether the master stays in command instead of entering. Safety committees can ask ratings directly whether they would feel able to stop a senior officer's entry.","url":"https://safety4sea.com/rmi-investigation-chief-officer-dies-after-entering-cargo-tank/","prio":3,"mar":true,"tags":["SPEAK","FL","SS"]},{"code":"SAFE","date":"2026-08-25","src":"Safety4Sea","title":"OCIMF 신임 MD Don Davis: '문화는 조직이 꾸준히 용인·장려·보상하는 것을 비춘다' — 사고 조사는 절차 준수 여부를 넘어 '그 결정을 만든 조건'을 봐야","eTitle":"OCIMF's Don Davis: Culture Reflects What an Organisation Tolerates, Encourages and Rewards, So Investigations Must Examine the Conditions Behind Decisions","kSum":"2026년 7월 Chevron Shipping에서 파견돼 OCIMF 대표(Managing Director)를 맡은 Don Davis는 SAFETY4SEA 인터뷰에서 인적 요소를 기술·운항 안전과 분리해 다루는 관행을 멈춰야 하며, 절차·장비·안전 시스템은 시간 압박 속에서 그것을 쓰는 사람만큼만 효과가 있다고 말했다. 사고 검토는 절차를 따랐는지에 그치지 말고 그 절차가 실행 가능했는지, 교육은 됐는지, 역할이 분명했는지, 어떤 상충 압박이 있었는지, 작업 환경이 안전한 행동을 도왔는지 막았는지를 따져야 한다고 했다. 서류상 절차가 탄탄해도 운항 압박이 사람을 불안전한 지름길로 밀 수 있으며, 문화는 조직이 꾸준히 용인하고 장려하고 보상하는 것을 반영하므로 리더십이 핵심이라고 강조했다. SIRE 2.0은 체크리스트에서 선박이 실제로 어떻게 운항되고 절차가 어떻게 적용되는지를 보는 쪽으로 옮겨 갔으며, 판단 기반 검사를 위해 검사관 교육과 선원이 검사의 의미를 이해하는 것이 중요하다고 덧붙였다.","eSum":"Don Davis, who became OCIMF Managing Director in July 2026 on secondment from Chevron Shipping, told SAFETY4SEA the industry must stop treating human factors as separate from technical and operational safety, since procedures, equipment and safety systems are only as good as the people using them under time pressure. Incident reviews should go beyond whether a procedure was followed to ask whether it was practical, whether people were trained, whether roles were clear, what competing pressures existed and whether the work environment helped or hindered safe action. A company can have strong procedures on paper while operational pressure still pushes people toward unsafe shortcuts, and because culture reflects what an organisation consistently tolerates, encourages and rewards, leadership is central. He said SIRE 2.0 has shifted inspections from checklists toward how ships are actually operated and procedures applied, which requires well-trained inspectors and crews who understand why inspections matter.","kImp":"사고·부적합 조사 양식에 '절차가 현실적으로 실행 가능했나, 역할이 분명했나, 어떤 압박이 있었나'를 묻는 항목을 넣어 볼 만하다. 안전위원회에서 '우리가 사실상 용인하고 있는 지름길'을 한 가지씩 꼽는 것도 문화를 점검하는 좋은 방법이다.","eImp":"Incident and non-conformity investigation forms can ask whether the procedure was practical, whether roles were clear and what pressures existed. Safety committees can name one shortcut the organisation effectively tolerates as a quick culture check.","url":"https://safety4sea.com/cm-ocimf-sharing-good-quality-data-can-produce-valuable-insights-to-improve-safety/","prio":2,"mar":true,"tags":["JUST","FL"]},{"code":"SAFE","date":"2026-08-21","src":"Fleet Management","title":"Fleet Management '글로벌 선원 참여 세미나': 승선 전 실제 사고·근접사고로 배우는 세션 25회 이상·선원 4,500여 명 — '모든 근접사고엔 교훈이 있다, 다음 배에 닿게 하라'","eTitle":"Fleet Management's Global Crew Engagement Seminars Use Real Incidents and Near Misses to Teach Speaking Up Before Seafarers Rejoin","kSum":"선박관리사 Fleet Management는 2025년 1월 시작한 '글로벌 선원 참여 세미나(GCES)'가 2025~2026년 25회 이상 열려 인도·필리핀·중국·인도네시아 등의 선원 4,500여 명과 만났다고 밝혔다. 세미나는 선원이 승선하기 전 실제 사고와 근접사고 사례로 사고가 어떻게 일어나고 어떻게 막는지 보여주며, 공무·운항·QHSE 팀이 함께 진행하고 초급 사관과 부원 세션을 번갈아 연다. 다루는 주제는 검사 준비, 툴박스 미팅 이끌기, 장비 정비, 이상하다고 느낄 때 말하기이며, 누구나 위험하다고 보는 작업을 멈출 수 있는 '강한 개입 문화'를 강조한다. 회사는 80명 규모 QHSE 팀이 사고·근접사고를 검토해 한 선박의 교훈을 다른 선박으로 전한다고 했으며, 2025년 LTIF 0.34(INTERTANKO 평균 0.41), TRCF 0.87을 제시했지만 이 성과를 세미나 효과로 직접 돌리지는 않았다.","eSum":"Ship manager Fleet Management says its Global Crew Engagement Seminars, launched in January 2025, have run more than 25 sessions across 2025 and 2026 and reached over 4,500 seafarers from countries including India, the Philippines, China and Indonesia. The sessions use real incidents and near misses before seafarers return to sea to show how accidents happen and how to prevent them, are delivered jointly by technical, operations and QHSE teams, and alternate between junior officers and ratings. Topics include preparing for inspections, leading toolbox meetings, maintaining equipment and speaking up when something looks wrong, within a strong intervention culture that lets anyone stop a task they see as dangerous. The company says its 80-strong QHSE team reviews incidents and near misses so lessons reach other vessels, and reports a 2025 LTIF of 0.34 against an INTERTANKO average of 0.41 and a TRCF of 0.87, without attributing these results directly to the seminars.","kImp":"휴가 중 선원 대상 세미나에서 최근 근접사고를 '어떻게 막을 수 있었나'보다 '누가 언제 말할 수 있었나' 중심으로 다루고, 사관·부원 세션을 나눠 각자 말하기 쉬운 자리를 만드는 구성을 참고할 만하다.","eImp":"Seminars for seafarers on leave can review recent near misses around who could have spoken up and when, and run separate sessions for officers and ratings so each group can talk more freely.","url":"https://www.fleetship.com/insights/global-crew-engagement-seminars-turning-experience-into-safer-operations","prio":1,"mar":true,"tags":["SPEAK","TRN"]},{"code":"SAFE","date":"2026-08-17","src":"Container News","title":"싱가포르, CHIRP 모델 '근접사고 기밀 보고제도' 출범 — CHIRP가 독립 접수·익명화하고 해상안전위원회가 교훈을 업계에 공유","eTitle":"Singapore Launches a Confidential Near Miss Reporting System Modelled on CHIRP, With Reports Received Independently and Shared Anonymously","kSum":"싱가포르 국가해상안전위원회(National Maritime Safety at Sea Council)와 싱가포르선주협회(SSA)가 제13회 Singapore Safety@Sea Week 개막에 맞춰 해역 이용자가 온라인으로 근접사고를 기밀 보고하는 'Singapore Near Miss Reporting System'을 출범시켰다. 영국의 기밀 인적요소 보고 프로그램 CHIRP를 본떠, CHIRP가 보고를 독립적으로 접수하고 익명화한 정보만 위원회에 넘기면 위원회가 핵심 안전 교훈을 정리해 업계 전체에 공유하는 구조다. Murali Pillai 법무·교통 선임국무장관은 기술의 책임 있는 활용, 새로운 위험에 대한 조기 대비, 사람을 안전의 중심에 두는 것을 우선과제로 꼽았고, MPA 청장 Ang Wee Keong은 8월 20일 NI 싱가포르 컨퍼런스 개회사에서 사람들이 근접사고를 자유롭게 말할 수 있는 문화를 목표로 한다고 말했다. 같은 자리에서 MPA는 통합 항만운영 지휘·통제·통신(IPOC) 시스템 가동과 Ocean Infinity와의 자율·원격 운항 시험 MoU도 발표했다.","eSum":"Singapore's National Maritime Safety at Sea Council and the Singapore Shipping Association launched the Singapore Near Miss Reporting System at the opening of the 13th Singapore Safety@Sea Week, giving sea space users a confidential online channel to report near misses. Modelled on the UK's Confidential Human Factors Incident Reporting Programme, it has CHIRP receive submissions independently and pass only anonymised information to the Council, which distils key safety lessons for the wider maritime community. Senior Minister of State for Law and Transport Murali Pillai named responsible use of technology, early preparation for emerging risks and keeping people at the centre of safety as priorities, and MPA chief executive Ang Wee Keong told the Nautical Institute Singapore conference on 20 August that the aim is a culture in which people feel free to speak up about near misses. MPA also announced its operational Integrated Port Operations Command, Control and Communications system and an MoU with Ocean Infinity on autonomous and remote operations trials.","kImp":"사내 근접사고 보고와 별도로 회사를 거치지 않는 제3자 기밀 보고(CHIRP 등) 경로가 있다는 점을 승선 전 교육에서 안내해 볼 만하다. 사내 보고제도도 '누가 보고를 읽고 이름은 어떻게 보호되는가'를 명시하면 신뢰가 높아진다.","eImp":"Pre-joining training can tell crews that, besides company near-miss reporting, they can report confidentially to an independent third party such as CHIRP. Company schemes earn more trust when they state who reads reports and how names are protected.","url":"https://container-news.com/mpa-launches-maritime-safety-initiatives/","prio":2,"mar":true,"tags":["SPEAK","JUST"]},{"code":"SAFE","date":"2026-10-23","src":"DBR","title":"DBR '회의에서 조용한 팀원, 정말 의욕이 없는 걸까?' — 침묵은 태도가 아니라 '말해 봐야 안 바뀐다'는 학습의 결과, 질문을 늘리기 전에 팀장이 주는 위압감부터 걷어야","eTitle":"DBR: Quiet Team Members Are Not Necessarily Unmotivated - Silence Is Learned From 'Speaking Up Changes Nothing', So Leaders Should Remove the Intimidation Before Asking More Questions","kSum":"DBR 팀장클럽 리포트에서 리더십 작가 김진영은 회의 때 침묵하던 팀원들이 회의가 끝난 뒤 탕비실·엘리베이터에서는 다양한 의견을 나누는 현상을 짚으며, 질문 횟수를 늘리거나 '편하게 말하라'고 독려하는 것만으로는 침묵을 깰 수 없다고 했다. 10월 20일 글은 같은 질문도 팀장이 위압적으로 느껴지면 팀원에게 '무슨 답을 원하나', '잘못 답하면 어떻게 되나'라는 계산을 낳는다며, 그 위압감은 성격보다 반대 의견에 한 번 정색한 장면, 평가·업무 배분 권한, 늘 결론을 먼저 말하는 습관이 쌓인 인식에서 생긴다고 설명했다. 10월 23일 후속 글은 의욕과 실제 주어지는 기회의 간극이 클수록 침묵이 늘고, 침묵은 대개 '말해 봐야 아무것도 안 바뀌더라'는 경험이 반복된 학습의 결과라고 짚었다(구독 기사, 공개된 앞부분 기준).","eSum":"In DBR's team-leader series, leadership writer Kim Jin-young notes that team members who stay silent in meetings often share their views freely in the pantry or the lift afterwards, and argues that asking more often or urging people to speak freely will not break the silence. A 20 October piece says the same question can feel like a threat when a leader is seen as forceful, prompting staff to calculate what answer is wanted and what happens if they get it wrong; that perception is built less by personality than by a single sharp reaction to dissent, control over appraisals and work allocation, and a habit of announcing the conclusion first. A follow-up on 23 October says silence grows with the gap between motivation and real opportunity, and is usually learned after repeated experiences that speaking up changes nothing (subscriber articles; summary based on the free opening sections).","kImp":"선상 안전회의나 툴박스 미팅에서 선장·기관장이 먼저 결론을 말하지 않고 하급 사관·부원의 의견을 먼저 듣는 순서로 바꿔 보고, 지난 회의에서 나온 제안이 실제로 무엇을 바꿨는지 다음 회의 첫머리에 알려 '말하면 바뀐다'는 경험을 쌓게 할 만하다.","eImp":"In shipboard safety meetings and toolbox talks, masters and chief engineers could hear junior officers and ratings before giving their own view, and open each meeting by reporting what the last round of suggestions actually changed, so crews learn that speaking up makes a difference.","url":"https://dbr.donga.com/teamleader/view/article_no/188","prio":2,"mar":false,"tags":["PS","SPEAK","FL"]},{"code":"SAFE","date":"2026-09-22","src":"HR Insight","title":"회의가 15분 일찍 끝나는 팀이 위험하다 — 이모지 동의 뒤에 숨은 ‘가짜 조화’, 솔직해도 괜찮다는 신뢰가 없으면 리스크가 묻힌다","eTitle":"Beware the Meeting That Ends 15 Minutes Early: How 'Artificial Harmony' Buries Risk When Teams Lack Vulnerability-Based Trust","kSum":"유준희 조직문화 공작소 대표는 팀장이 이견을 물어도 정적 뒤에 동의 이모지만 남고 회의가 예정보다 15분 일찍 끝나는 장면을 들어, 반대하면 '까칠한 사람'으로 찍힐까 넘기는 '친절함의 함정'이 생기고 슬랙·노션·생성형 AI 같은 도구가 갈등 회피를 더 정교하게 만든다고 진단했다. 패트릭 렌치오니의 '가짜 조화(Artificial Harmony)' 개념을 빌려, 이는 솔직하게 말해도 비난이나 불이익이 없다는 취약성 기반 신뢰가 없을 때 나타나는 방어기제이며 그 결과 프로젝트의 결함과 리스크가 테이블에 오르지 못한다고 지적했다. 억눌린 불만은 뒷담화로 '발효'되고 문제를 감지한 구성원은 자기 판단을 의심하며 입을 닫거나 가장 먼저 지쳐 떠난다며 '아홉 번의 불편함을 삼킨 조직은 열 번째에 가장 치명적인 방식으로 갈등을 터뜨릴 수 있다'고 경고했다(구독 기사로 진단 신호 목록 등 후반부 비공개).","eSum":"Yoo Jun-hee, head of an organisational culture consultancy, describes a team that answers the leader's call for objections with silence and approving emojis and finishes its meeting 15 minutes early, arguing that a 'niceness trap', in which people let things pass for fear of being seen as difficult, is made more sophisticated by tools such as Slack, Notion and generative AI. Drawing on Patrick Lencioni's concept of artificial harmony, he calls it a defence mechanism that appears when there is no vulnerability-based trust that candour will not be punished, so project flaws and risks never reach the table. Suppressed doubts ferment into gossip, people who sense problems start doubting their own judgement and fall silent or burn out and leave first, and an organisation that swallows discomfort nine times may let conflict erupt in the most damaging way the tenth time (subscriber article; the list of warning signs and later sections are not public).","kImp":"안전위원회나 출항 전 회의에서 이견이 하나도 나오지 않으면 바로 끝내지 말고 '이 계획이 실패한다면 이유는 무엇일까'를 한 사람씩 묻는 순서를 넣어 볼 만하다.","eImp":"When a safety committee or pre-departure meeting produces no objections at all, the chair could ask each person in turn how the plan might fail before closing the meeting.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=114&bi_pidx=39593","prio":2,"mar":false,"tags":["SPEAK","PS"]},{"code":"SAFE","date":"2026-09-14","src":"SHRM","title":"SHRM \"심리적 안전은 '편안함'이 아니라 어려운 일을 안전하게 하는 조건\" — '산만한 근무' 경고","eTitle":"Why Workplaces Need to Think Differently About Psychological Safety","kSum":"SHRM의 캐서린 메이어 기자가 인터뷰한 리더십 컨설턴트 스티브 로빈스(S.L. Robbins & Associates 창업자)는 심리적 안전이 효과가 눈에 잘 띄지 않아 과소평가되지만 참여·연결·존중감처럼 조직이 중시하는 가치의 바탕에 있다고 말한다. 그는 비난을 피하고 무엇을 말해도 안전한지 살피느라 주의를 쓰는 상태를 '산만한 운전'에 빗대 '산만한 근무(distracted working)'라 부르며, 심리적 안전은 어려운 대화를 피하거나 기준을 낮추거나 책임을 없애는 것이 아니라고 강조한다. 그는 HR이 심리적 안전을 소프트 스킬이 아닌 인간 성과의 조건으로 다루고, 리더가 '이 환경은 사람들에게 정신적·감정적 에너지를 어디에 쓰게 만드는가'를 물어야 한다고 제안한다.","eSum":"In a SHRM interview by Kathryn Mayer, leadership consultant Steve Robbins, founder of S.L. Robbins & Associates, argues that psychological safety is underrated because its effects are hard to see, yet it underpins the participation, connection and sense of value organizations say they care about. He likens the attention people spend avoiding blame and judging what is safe to say to distracted driving, calling it 'distracted working', and stresses that psychological safety does not mean avoiding hard conversations, lowering standards or removing accountability. He urges HR to treat it as a condition for human performance rather than a soft-culture issue and to ask what the environment requires people to spend their mental and emotional energy on.","kImp":"질책을 피하려 눈치 보는 데 쓰는 주의만큼 당직과 작업 집중력이 줄어든다는 논리는 선상 안전 교육에서 심리적 안전을 '성과 조건'으로 설명하는 언어가 된다. 선박 방문 때 '무언가를 보고하기 전에 가장 신경 쓰이는 것이 무엇인가'를 물어 선원들이 에너지를 어디에 쓰는지 확인해 볼 만하다.","eImp":"The idea that attention spent dodging blame is attention taken from watchkeeping and hands-on work gives shipboard safety training a performance-based way to explain psychological safety. On ship visits, ask crews what worries them most before they report something, to see where their mental energy is going.","url":"https://www.shrm.org/topics-tools/news/inclusion-diversity/workplaces-psychological-safety","prio":2,"mar":false,"tags":["PS","SPEAK"]}]},{"code":"XCOMM","kTitle":"다문화·선박-육상 소통","eTitle":"Cross-cultural and ship-shore communication","items":[{"code":"XCOMM","date":"2026-10-19","src":"Safety4Sea","title":"스웨덴 클럽 팟캐스트 '압박 속 좋은 도선이란': 도선사 상세 계획을 승선 전에 배로 보내고, 도선사는 '생각을 소리 내어' 말하고, 사관은 PACE로 이의를 제기하라","eTitle":"The Swedish Club on Good Pilotage Under Pressure: Send the Pilot's Plan Before Boarding, Have Pilots Think Aloud and Use PACE to Speak Up","kSum":"The Swedish Club 팟캐스트에서 스웨덴 도선사이자 선장 출신인 Magnus Andersson은 숙련자도 실수하므로 도선을 지휘하는 사람 주변에 안전장치가 필요하며, 좋은 도선은 브리지 팀이 기대치를 알고 진행을 감시하다 계획에서 벗어나면 개입할 수 있는 '공유된 머릿속 그림'에 달려 있다고 말했다. IMO 결의 A.960에 따른 선장-도선사 정보교환(MPX)은 체크리스트 완료가 아니라 안전 여유·위험 요소·속력 제한·진입 금지 구역 합의가 핵심이며, 스웨덴의 'On the Right Course' 프로젝트(MTO Safety와 공동)는 도선사의 상세 항로를 승선 전에 배로 보내 브리지 팀이 선석 간 계획에 넣고 초급 사관도 조선 의도와 한계를 미리 익히게 했다. 그는 도선사가 변침 이유 같은 의도를 '소리 내어 생각하며' 설명하고, 사관은 항적·속력·위험물과의 거리가 예상과 다르면 탐색(Probe)→경고(Alert)→이의 제기(Challenge)→비상 조치(Emergency) 단계로 일찍 문제를 제기해야 하며, 긴 침묵, 특히 현지어 교신을 옮겨 주지 않는 침묵은 해롭다고 지적했다. 사고를 개인 역량 실패로만 보지 말라며, 선주에게는 스웨덴 클럽 'Passage Plan Plus' 지침 검토와 상세 도선 정보를 활용하는 브리지 팀 준비를 권했다.","eSum":"On The Swedish Club's podcast, Swedish pilot and master mariner Magnus Andersson said that because even experienced professionals make mistakes, pilotage needs safeguards around the person directing the ship, and good pilotage rests on a shared mental model in which the bridge team knows what to expect, monitors progress and is ready to intervene if the ship departs from the agreed plan. A master-pilot exchange under IMO Resolution A.960 is more than a checklist; the team must agree safety margins, hazards, speed limits and no-go areas, and Sweden's On the Right Course project with MTO Safety found that sending the pilot's detailed route to the ship before boarding improved preparation and let junior officers learn intended manoeuvres and limits in advance. Andersson urged pilots to think aloud about their intentions and officers to question unexpected changes in track, speed or distance from hazards using the PACE steps of probe, alert, challenge and emergency, warning that long silences on the bridge, especially when local-language exchanges go unrelayed, are unhelpful. He cautioned against treating incidents only as individual competence failures and recommended that owners review the club's Passage Plan Plus guidance and prepare bridge teams to use detailed pilotage information.","kImp":"도선 구역 진입 전 도선사 계획을 미리 받아 항해 계획에 넣는 관행을 선박에 권장하고, 브리지에서 도선사가 현지어로 교신하면 내용을 영어로 알려 달라고 요청하는 문구를 MPX 항목에 넣어 볼 만하다.","eImp":"Ships can be encouraged to request the pilot's plan before the boarding ground and build it into the passage plan, and the master-pilot exchange can include a request that local-language radio exchanges be summarised in English for the bridge team.","url":"https://safety4sea.com/cm-what-does-good-pilotage-actually-looks-like-when-the-pressure-is-on/","prio":2,"mar":true,"tags":["BRM","SPEAK","SS"]},{"code":"XCOMM","date":"2026-10-12","src":"UK P&I Club","title":"UK P&I, 일본 도선 중 중대사고 20건 분석: 컨테이너선 약 40%·충돌이 최다 — 원인 1순위는 '가정과 선입견', 도선사 오류를 아무도 지적하지 않았다","eTitle":"UK P&I Analyses 20 Serious Accidents Under Pilotage in Japan and Urges a Structured Master-Pilot Exchange and the PACE Challenge Model","kSum":"UK P&I Club의 Akshat Arora·Hiroshi Sekine은 일본운수안전위원회(JTSB) 보고서 중 2010~2026년 공개된 1,000톤 이상 선박의 도선 중 중대사고 20건을 분석했다. 컨테이너선이 약 40%를 차지했고 선박 간 충돌이 가장 많았으며, 원인은 가정·선입견(특히 타선 움직임에 대한 가정), 조선·항해 기술 문제, BRM 결함 세 갈래로 나뉘었고 그중 가정이 가장 흔했다. BRM 결함인 정보 공유, 팀워크, 도선사 의도에 대한 이해 부족의 공통 요인은 브리지 팀 소통이었고, 브리지 팀이 초기 오류를 발견하거나 지적하지 못해 사고로 번지는 경우가 많았다. 필자들은 통과 계획·예상 조선·예인선·제약·비상 대책을 담아 도선 내내 이어지는 표준화된 선장-도선사 정보교환(MPX)과, 의도 확인(Probe)→경고(Alert)→이의 제기(Challenge)→비상 조치(Emergency)로 단계적으로 개입하는 PACE 모델을 권고하며 '안전한 도선은 공동 책임'이라고 강조했다.","eSum":"UK P&I Club's Akshat Arora and Hiroshi Sekine analysed 20 serious accidents involving ships of 1,000 gt or more under pilotage in Japan, drawn from JTSB reports published between 2010 and 2026. Container ships accounted for about 40% and collisions between two vessels were the most common type; causes fell into assumptions and preconceived notions (most often about other vessels' movements), ship handling and navigation problems, and BRM weaknesses, with assumptions the largest group. Bridge team communication was the common factor behind failures in information sharing, teamwork and understanding the pilot's intentions, and accidents typically grew from an early error the bridge team did not detect or challenge. The authors recommend a standardised master-pilot exchange that continues throughout pilotage and the PACE model (Probe, Alert, Challenge, Emergency) for structured intervention, stressing that safe pilotage is a shared responsibility.","kImp":"도선 전 MPX를 체크리스트 확인에 그치지 말고 '도선사의 다음 두 조선 의도'를 당직 사관이 말로 되풀이하게 하고, PACE 단계 표현을 사관 회의에서 역할극으로 연습해 볼 만하다. 도선 중 근접사고 보고에서 '누가 이상을 알아챘고 말했는가'를 별도 항목으로 보는 것도 좋다.","eImp":"Beyond the checklist, the officer of the watch can repeat back the pilot's next two intended manoeuvres after the master-pilot exchange, and officers' conferences can role-play PACE escalation phrases. Near-miss reports under pilotage can record who noticed the problem and whether they spoke.","url":"https://www.ukpandi.com/news-and-resources/news/article/pilotage-operations-and-navigational-safety-lessons-from-accident-investigations/","prio":3,"mar":true,"tags":["BRM","SPEAK"]},{"code":"XCOMM","date":"2026-10-08","src":"Ship Management International","title":"VIKAND: 호르무즈처럼 끝이 안 보이는 위기엔 '변한 것 없음'이라도 계속 알려라 — 침묵은 선원을 뉴스·SNS 해석에 홀로 남긴다","eTitle":"VIKAND Urges Companies to Keep Talking to Crews Through Prolonged Crises Such as Hormuz, Even When Nothing Has Changed","kSum":"해사 의료서비스 기업 VIKAND의 정신웰빙 담당 이사 Martin Hedman은 세계 정신건강의 날(10월 10일)을 앞두고, 호르무즈 해협 긴장처럼 끝이 분명하지 않은 장기 위기에서 회사가 선원과 소통을 이어가야 한다고 촉구했다. 불확실성 자체가 스트레스이며, 긴 침묵은 선원들이 뉴스와 소셜미디어를 홀로 해석하게 만든다는 것이다. 그는 '실질적으로 달라진 것은 없고 계속 지켜보고 있다' 같은 짧은 메시지도 회사가 사안을 진지하게 다룬다는 확신을 준다며, 문제가 생기기 전에 누구에게 연락하고 어디서 도움을 받는지 알려 두고 정기 웰빙 확인·우려 제기 경로·원격 의료와 정신건강 지원을 평상시 운영에 넣으라고 권했다. 기사는 우울증이 있는 선원일수록 회사가 직원을 아낀다고 답하는 비율이 낮았다는 예일대 연구와, 지원적 리더십과 신뢰할 수 있는 소통이 있는 곳에서 사기가 높았다는 2026년 2분기 선원행복지수를 함께 인용했다.","eSum":"Ahead of World Mental Health Day on 10 October, Martin Hedman, VIKAND's Director of Mental Wellness Practices, urged shipping companies to keep communicating with seafarers through prolonged crises with no clear end point, such as tensions around the Strait of Hormuz. Uncertainty is itself stressful, and long silences leave crews to interpret news and social media alone. Hedman said even a brief message that nothing has materially changed and the company is still monitoring reassures crews, and that seafarers should know in advance whom to contact and where to get help, with welfare check-ins, routes for raising concerns and medical, mental health and telehealth support built into normal operations. The article cites a Yale University study finding that seafarers with depression were less likely to say their company cared about employees, and the Q2 2026 Seafarers Happiness Index finding of better morale where leadership was supportive and communication reliable.","kImp":"고위험 해역 통항이나 장기 위기 때 '변동 없음'도 정해진 주기로 알리는 선박-육상 업데이트 일정을 비상대응 계획에 넣어 볼 만하다. 위기 시 연락 창구와 지원 경로를 승선 전에 한 장짜리 안내로 주는 것도 좋다.","eImp":"Emergency response plans for high-risk transits or prolonged crises can include fixed-interval ship-shore updates, even when the message is that nothing has changed. A one-page guide to crisis contacts and support routes can be handed out before joining.","url":"https://www.shipmanagementinternational.com/news/p6sz79lpxrbah22-4bkcf-zbcsd-nc48r-lx2wh-phcly-5gefa-43xp8-gck8j-8jhf3-9zgbg-efhdy-thclp-eyz4k-wrxmz-ln64a-2zdrr-3zws9-6stby","prio":1,"mar":true,"tags":["SS","WELL"]},{"code":"XCOMM","date":"2026-10-07","src":"쉬핑뉴스넷","title":"해운협회, 국적선 승선 앞둔 인도네시아 해기사 30여 명에 현지 직무교육 시범 — ‘한국문화의 이해’로 선내 조직문화·세대 간 소통 예절부터 가르쳐","eTitle":"Korea Shipowners' Association Pilots Pre-Boarding Training for About 30 Indonesian Officers, Starting With Onboard Culture and Cross-Generational Communication","kSum":"한국해운협회는 국적선대에서 외국인 해기사의 승선 비중이 계속 늘자 한국해양대, 자카르타 해양대(STIP JAKARTA)와 함께 국적선사에 승선할 인도네시아 해기사 약 30명을 대상으로 승선 전 직무교육 시범사업을 현지에서 열었다. 공통 과목으로 국적선 내 조직문화와 세대 간 소통 예절을 다루는 '한국문화의 이해'와 최신 점검 경향을 반영한 'PSC 실무대응'을, 항해 분야는 항해계획·ECDIS·선박조종시뮬레이터·안전설비 관리를, 기관 분야는 선내 전기·기관 운전 실습·전자제어 엔진을 가르쳤다. 양창호 상근부회장은 '외국인 해기사의 초기 적응과 실무 역량이 선박 안전 운항과 직결된다'며 참여 선사와 교육생의 만족도와 효과를 검증한 뒤 확대·정례화를 검토하겠다고 밝혔다.","eSum":"With the share of foreign officers on Korean-flag ships rising steadily, the Korea Shipowners' Association ran a pilot pre-boarding course in Jakarta with Korea Maritime and Ocean University and STIP Jakarta for about 30 Indonesian officers due to join Korean-flag ships. Common modules covered 'Understanding Korean Culture', on onboard organisational culture and cross-generational communication etiquette, and practical PSC response reflecting recent inspection trends, while deck officers studied passage planning, ECDIS, ship-handling simulators and safety equipment and engineers covered shipboard electrical systems, engine operation and electronically controlled engines. Vice chairman Yang Chang-ho said foreign officers' early adaptation and practical competence are directly linked to safe operation, and the association will consider expanding the course and making it regular after assessing satisfaction and effectiveness among participating companies and trainees.","kImp":"새 국적의 사관을 받을 때 기술 교육 외에 선내 위계·보고 방식·세대 간 소통 예절을 승선 전에 설명하는 짧은 모듈을 넣고, 승선 후 첫 몇 주 안에 선장이 적응 상태를 묻는 면담을 두어 볼 만하다.","eImp":"When officers of a new nationality join, a short pre-joining module on onboard hierarchy, reporting habits and cross-generational etiquette could sit alongside technical training, followed by a master's check-in on adaptation within the first few weeks on board.","url":"https://www.shippingnewsnet.com/news/articleView.html?idxno=72359","prio":2,"mar":true,"tags":["XC","TRN"]},{"code":"XCOMM","date":"2026-09-29","src":"The Nautical Institute","title":"NI MARS 202633 '분리통항로 충돌': 비원어민끼리의 영어 VHF 교신을 OOW가 모국어로 선장에게 옮기며 뜻이 정반대로 — 선장은 교신을 직접 듣지 않았다","eTitle":"Nautical Institute MARS 202633: An Ambiguous VHF Exchange Between Non-Native English Speakers, Relayed to the Master in Another Language, Reversed Its Meaning Before a TSS Collision","kSum":"NI MARS 보고(MAIB 보고서 7/2018 편집)에 따르면 야간 양호한 시정의 분리통항로에서 16노트 이상으로 탱커를 추월하던 벌크선 선장이 최근접점(CPA)이 줄어들자 OOW에게 탱커를 VHF로 부르게 했다. 비원어민끼리 영어로 나눈 교신은 모호했고, OOW가 이를 자기 모국어로 선장에게 전달한 내용은 탱커 쪽 이해와 정반대였으며, 선장은 교신을 직접 듣지 않은 채 그 요약에 따라 음향신호 없이 작은 좌현 조타를 이어갔다. 14시간 넘게 당직을 선 탱커 선장은 피로한 상태에서 횡단선과 통항로 변침에 정신이 팔려 선미 확인과 음향신호 없이 좌현 전회두를 지시했고, 두 선박이 충돌해 큰 구조 손상을 입었다(인명·오염 피해 없음). 교훈으로 VHF는 충돌예방규칙 준수를 대신할 수 없고 쓰더라도 일찍 명확한 계획을 합의할 것, 교신을 위임했다면 책임자가 직접 들을 것(특히 언어 중계가 끼는 경우), 작은 조타의 연속 대신 분명하고 큰 변침, 원거리 탐색 유지를 제시했다.","eSum":"A Nautical Institute MARS report, edited from MAIB report 7/2018, describes a bulk carrier overtaking a tanker at over 16 knots at night in a traffic separation scheme, whose master, worried by a shrinking CPA, had the officer of the watch call the tanker on VHF. The English exchange between non-native speakers was ambiguous, the officer relayed it to the master in their own language with a meaning opposite to the tanker's understanding, and the master, who had not listened to the call himself, made small port helm changes without sound signals. The tanker's master, probably fatigued after more than 14 hours on the bridge and distracted by a crossing vessel and a turn in the scheme, ordered a full round turn to port without checking astern, and the ships collided with significant structural damage but no injuries or pollution. Lessons: VHF is no substitute for the Collision Regulations and, if used, must come early enough to agree an unambiguous plan; whoever delegates a VHF call should listen to it directly, especially with a language relay; alterations should be clear and decisive; and long-range scanning must be maintained.","kImp":"다국적 브리지 팀에서는 선박 간 VHF 교신 내용을 선장이 직접 듣거나 영어 원문 그대로 복창하게 하는 규칙을 두고, 사관 회의에서 '모국어 중계'가 만든 오해 사례로 활용해 볼 만하다.","eImp":"Multinational bridge teams can require that the master hears ship-to-ship VHF exchanges directly or that the officer repeats them verbatim in English, and officers' conferences can use this case to show how a language relay creates misunderstanding.","url":"https://www.nautinst.org/resources-page/202633-collision-in-a-tss.html","prio":2,"mar":true,"tags":["XC","BRM"]},{"code":"XCOMM","date":"2026-09-17","src":"Safety4Sea","title":"IMCA 교훈: 합의된 히빙라인 대신 예고 없이 줄 발사기를 쏴 — 유능한 두 선박 팀도 계획을 같게 이해하지 못하면 위험, '준비 완료'의 뜻부터 맞춰라","eTitle":"IMCA Lesson: A Vessel Interface Fails the Moment One Side Changes the Agreed Method, as a Tanker Fires a Line-Throwing Apparatus Without Warning","kSum":"IMCA 사례에서 예인 와이어 연결을 준비하던 탱커 갑판원이 약 10m 뒤에서 후진 조선 중이던 상대 선박에 예고 없이 줄 발사기(LTA)를 쐈고, 발사체가 쪼개지며 일부가 상대 선박 윈치에 맞았다(부상·손상 없음). 합의된 순서는 상대 선박 브리지가 VHF로 준비 완료를 알린 뒤 승인된 히빙라인을 쓰는 것이었는데, 탱커가 상대 측에 알리거나 동의를 받지 않고 방법을 바꿨고 상대 선원들은 히빙라인을 가정하고 위치를 잡고 있었다. IMCA는 비효과적 소통, 합의 절차 미준수, 선박 간 접점 관리 부족을 원인으로 들며, 유능한 두 팀도 계획을 같게 이해하지 못하면 불안전한 작업을 만들 수 있다고 지적했다. 조직 경계를 넘는 작업에는 누가 교신하고 누가 각 단계를 승인하며 계획이 바뀌면 어떻게 하는지를 정한 실무 접점 장치, 방법·채널·순서·책임을 담은 합동 사전 체크리스트, '준비 완료'의 공통 정의, 계획 변경 시 일단 멈추고 재합의, 누구나 쓸 수 있는 작업 중지 권한을 권고했다.","eSum":"In an IMCA case, a tanker's deck crew preparing to connect a tow wire fired a line-throwing apparatus without warning while another vessel was manoeuvring about 10 metres astern; the projectile split and part of it struck the other vessel's winch, though no one was hurt. The agreed sequence was for the receiving vessel's bridge to confirm readiness by VHF and then for an approved heaving line to be used, but the tanker changed the method without notice or agreement while the other crew positioned themselves expecting a heaving line. IMCA cited ineffective communication, failure to follow the agreed procedure and poor control of the vessel-to-vessel interface, noting that two competent crews can still create an unsafe operation if they do not share the same understanding of the plan. It recommends an interface mechanism defining who communicates, who authorises each step and what happens if plans change, a joint pre-transfer checklist, a common meaning for 'ready', pausing to re-agree any revised method, and stop-work authority for anyone.","kImp":"선박 간·선박-부두 합동 작업 전에 양측이 방법·채널·순서·'준비 완료'의 뜻을 한 장으로 확인하고, 현장에서 방법을 바꿀 때는 무조건 멈추고 다시 합의한다는 규칙을 툴박스 미팅에서 확인해 볼 만하다.","eImp":"Before joint ship-to-ship or ship-shore operations, both sides can confirm method, channel, sequence and what 'ready' means on a single sheet, and toolbox talks can restate that any change of method on site means stop and re-agree.","url":"https://safety4sea.com/lessons-learned-safe-vessel-interfaces-depend-on-agreed-methods-and-clear-communication/","prio":1,"mar":true,"tags":["SS","SPEAK"]},{"code":"XCOMM","date":"2026-09-14","src":"Safety4Sea","title":"IMCA 교훈: 도선사의 '선미 줄부터 시작하라'를 갑판원은 '지금 풀라'로 받아 — 표준 계류 명령과 복창 확인 없이 '이해했으려니' 가정한 결과","eTitle":"IMCA Lesson: A Pilot's 'Start With the Stern Ropes' Was Taken as an Order to Let Go, Showing Why Mooring Needs Standard Commands and Closed-Loop Checks","kSum":"IMCA 사례에서 도선사가 승선한 선박이 출항을 준비할 때, 교통관제는 다른 선박이 선미를 지나갈 때까지 부두에 머물고 그때까지 스러스터도 쓰지 말라고 했다. 도선사가 선장에게 '선미 줄부터 시작하라'고 말하자 선장이 이를 갑판원에게 전했고, 갑판원은 준비 지시가 아닌 즉시 해방 명령으로 받아들여 선미 줄 2개를 모두 풀었다. 선미 스프링은 이미 회수돼 있었지만 캡스턴 위치와 사각지대 때문에 브리지는 이를 몰랐고, 선수 스프링도 장력이 부족해 강한 강물 흐름 속에 선박이 다른 선석 쪽으로 밀려 나갔으며, 선장이 후진과 측면 스러스터로 제어를 되찾은 뒤 줄 하나가 선미 밑으로 들어간 사실이 보고됐다. IMCA는 모호한 지시, 표준 계류 명령 대신 쓴 비공식 표현, 폐쇄 루프 소통 부재와 '공유된 이해'에 대한 가정, BRM 붕괴를 원인으로 들며 '아무것도 가정하지 말라'고 강조했다.","eSum":"In an IMCA case, a vessel with a pilot aboard was preparing to sail when traffic control said it must stay alongside, without using thrusters, until another vessel had passed astern. The pilot told the master to start with the stern ropes first, the master passed this on, and the deck crew took it as an order to release rather than prepare, letting go both stern lines. The aft spring had already been taken in, unseen from the bridge because of the capstan's position and a blind spot, and the forward spring was poorly tensioned, so the stern was pushed by a strong river current and the ship surged toward another berth until the master regained control with astern propulsion and thrusters, after which a rope was reported under the stern. IMCA cited an ambiguous instruction, informal wording instead of standard mooring commands, no closed-loop communication, assumed shared understanding and a breakdown of BRM, summing up the lesson as assume nothing.","kImp":"계류 작업 브리핑에서 '준비'와 '해방'을 구분하는 표준 명령어를 정하고, 브리지-선수·선미 간 지시는 반드시 복창 후 실행하도록 해 볼 만하다. 도선사의 비공식 표현은 선장이 표준 명령으로 바꿔 전달하는 습관을 사관 회의에서 다룰 수 있다.","eImp":"Mooring briefings can fix standard commands that separate 'prepare' from 'let go' and require read-back before any bridge order to the mooring stations is executed. Officers' conferences can practise masters translating a pilot's informal phrasing into standard commands.","url":"https://safety4sea.com/lessons-learned-ensure-everyone-clearly-understands-what-is-happening/","prio":2,"mar":true,"tags":["BRM","SS"]},{"code":"XCOMM","date":"2026-08-28","src":"The Nautical Institute","title":"NI MARS 202631 '예인선 이름 혼동': 도선사 무전 카드에 두 예인선 이름이 뒤바뀌어 명령이 엇갈려 부두 충돌 — 모두가 계획은 알았지만 아무도 어긋난 명령을 못 잡았다","eTitle":"Nautical Institute MARS 202631: Transposed Tug Names on a Pilot's Radio Card Sent Orders to the Wrong Tugs, and No One on the Bridge Caught It","kSum":"NI MARS 보고(NTSB 보고서 MIR-26-05 편집)에 따르면 야간에 예인선 2척의 도움으로 이안하던 탱커에서 도선사가 무전 참고 카드에 선수·선미 예인선 이름을 뒤바꿔 적는 바람에, 선미 예인선에 줄 명령이 선수 예인선으로, 반대도 마찬가지로 전달됐다. 선수가 빠르게 부두에서 떨어지는 사이 선미는 1.9노트 조류를 받으며 부두 쪽으로 붙었고, 선장의 '선미가 너무 가깝다'는 경고는 뒤늦게 나와 선박이 부두 북동쪽 모서리에 부딪혀 선체 좌현과 부두가 손상됐다. 선장과 도선사는 계획을 공유했지만 실제 예인선 명령과 머릿속 그림을 맞춰 보지 않았고, 선수 예인선과의 무전에서 위치 불일치가 드러났는데도 도선사는 접촉 후에야 오전달을 알아챘다. 교훈으로 브리지 팀 전원이 같은 작업 그림을 가져 불일치를 일찍 잡을 것, 예인선을 이름 대신 위치(선수·선미)나 번호(앞쪽부터 1·2번)로 부를 것을 제시했다.","eSum":"A Nautical Institute MARS report, edited from NTSB report MIR-26-05, describes a tanker unberthing at night with two tugs, where the pilot transposed the bow and stern tug names on his radio reference card, so orders meant for the stern tug went to the bow tug and vice versa. As the bow was pulled rapidly off the berth, the stern closed on the pier in a 1.9-knot current; the master's warning that the aft end was too close came late, and the ship struck the corner of the pier, damaging its port side and the berth. The master and pilot had shared the plan but never checked their mental models against the actual tug orders, and although a VHF exchange with the bow tug revealed a positional discrepancy, the pilot recognised the miscommunication only after contact. Lessons include giving the whole bridge team the same mental model so inconsistencies are caught early and referring to tugs by position or number rather than by name.","kImp":"이·접안 브리핑에서 예인선을 이름 대신 '1번(선수)·2번(선미)'처럼 위치·번호로 부르기로 정하고, 당직 사관이 도선사의 예인선 명령을 계획과 대조해 소리 내어 확인하는 습관을 넣어 볼 만하다.","eImp":"Berthing briefings can agree to call tugs by number and position, such as tug 1 forward and tug 2 aft, instead of by name, and have the officer of the watch check each tug order against the plan out loud.","url":"https://www.nautinst.org/resources-page/202631-tug-name-mix-up.html","prio":2,"mar":true,"tags":["BRM","SS"]},{"code":"XCOMM","date":"2026-09-25","src":"Harvard Business Review","title":"HBR \"익숙한 말투를 '소통 능력'으로 착각한다\" — 말하는 방식이 직무 기회를 가른다","eTitle":"Research: How Speech Patterns Shape Opportunity at Work","kSum":"HBS 워킹 놀리지의 에이버리 포먼이 소개한 카딤 노레이의 연구는 수십 년간의 노동시장 데이터와 음성 녹음을 분석해, 말하는 방식이 능력을 제대로 보여 주지 않는데도 관리자들이 '익숙함'을 사회적 역량으로 착각한다고 밝혔다. 직장 규범과 말하는 방식이 비슷한 사람일수록 사람을 상대하는 대인 업무 중심 직무로 더 많이 이동했고, 지역 노동시장을 한 집단이 지배할수록 이 효과가 커져 '다르게 들리는' 사람의 기회가 좁아졌다. 기사는 AI가 분석 업무를 자동화할수록 소통의 비중이 커질 것이라며, 리더가 '적합성(fit)'의 정의를 넓히고 구조화된 인재 결정 방식을 써서 말투 때문에 소수 집단 지원자가 불이익을 받지 않게 하라고 권한다.","eSum":"An HBS Working Knowledge piece by Avery Forman describes research by Kadeem Noray that draws on decades of labor-market data and audio recordings and finds that managers often mistake familiar speech for social skill, even though speech patterns do not reliably signal ability. Workers whose communication style matches workplace norms are more likely to move into people-oriented, socially intensive roles, and the effect is stronger where one group dominates the local labor market, narrowing opportunities for people who sound different. The piece expects communication to matter more as AI automates analytical work and urges leaders to broaden their definition of 'fit' and use structured talent decisions so minority applicants are not penalized for how they sound.","kImp":"다국적 선원 평가와 진급 추천에서 영어 억양이나 말투가 익숙한지가 '소통 능력' 점수를 좌우할 위험이 있다. 사관 평가서의 소통 항목을 지시 복창·보고 정확성 같은 관찰 가능한 행동 기준으로 바꾸고, 진급 심사 결과에 국적별 편차가 없는지 점검해 볼 만하다.","eImp":"When evaluating and promoting multinational crews, how familiar an officer's English accent sounds can quietly drive 'communication' scores. Anchor the communication item in appraisals to observable behaviors such as closed-loop read-backs and accurate reporting, and check promotion outcomes for gaps by nationality.","url":"https://hbr.org/2026/09/research-how-speech-patterns-shape-opportunity-at-work","prio":2,"mar":false,"tags":["XC","DI"]},{"code":"XCOMM","date":"2026-08-03","src":"Harvard Business Review","title":"HBR \"좋은 조언의 기준은 문화마다 다르다\" — 미국은 자율, 인도는 분명한 지시, 중국은 여러 갈래 검토","eTitle":"What to Consider Before Giving Advice on a Global Team","kSum":"나므라타 고얄(에사데 경영대학원)과 크리슈나 사바니(홍콩이공대) 교수는 문화마다 어떤 조언이 도움이 되고 존중받으며 지지적인지에 대한 기대가 다르다는 새 연구를 소개했다. 미국인은 받는 사람의 자율성을 지켜 주는 조언을, 인도인은 조언자의 헌신을 보여 주는 분명하고 지시적인 권고를, 중국인은 여러 가능한 경로를 탐색하고 복잡성을 인정하는 조언을 더 높이 평가하는 경향이 있었다. 필자들은 이런 기대 차이를 아는 리더가 신뢰를 쌓고 멘토링과 글로벌 팀 협업을 강화할 수 있다며, 한 가지 방식이 모두에게 통한다고 가정하지 말고 조언의 의도를 분명히 밝히라고 권한다.","eSum":"Namrata Goyal of Esade Business School and Krishna Savani of Hong Kong Polytechnic University describe new research showing that people from different cultures hold different assumptions about what makes advice helpful, respectful and supportive. Americans tended to value advice that preserves the recipient's autonomy, Indians preferred clear, directive recommendations that signal the adviser's commitment, and Chinese respondents favored advice that explores multiple possible paths and acknowledges complexity. The authors say leaders who recognize these expectations can build trust, strengthen mentoring and improve global team collaboration, and urge them to make the intent behind their advice explicit rather than assume one style fits everyone.","kImp":"다국적 선원이 함께 일하는 선상에서는 같은 조언도 국적에 따라 '간섭'이나 '무책임'으로 받아들여질 수 있다. 선장·기관장이 하급 사관에게 조언할 때 지시인지 선택지 제시인지를 먼저 밝히도록 하고, 리더십 교육에 국적별 기대 차이를 다루는 사례를 넣어 볼 만하다.","eImp":"On ships with multinational crews, the same advice can land as interference with one nationality and as a lack of commitment with another. Encourage masters and chief engineers to say up front whether they are giving an instruction or offering options, and add cases on differing national expectations to leadership training.","url":"https://hbr.org/2026/08/what-to-consider-before-giving-advice-on-a-global-team","prio":2,"mar":false,"tags":["XC","FL"]}]},{"code":"CHANGE","kTitle":"변화관리·업무 혁신·AI","eTitle":"Change management, work innovation and AI","items":[{"code":"CHANGE","date":"2026-10-28","src":"한국해운신문","title":"[칼럼] “질문하는 도구였던 AI가 일을 맡기는 도구로” — 정한희 교수, 생성형 AI는 해운의 불확실성을 없애지 못해도 다루는 방식은 바꾼다","eTitle":"[Column] 'AI Went From a Tool I Ask to a Tool I Delegate To': Generative AI Cannot Remove Shipping's Uncertainty but Changes How People Handle It","kSum":"정한희 동명대 초빙교수는 생성형 AI를 검색창처럼 쓰다가 이메일 작성, 계약서 비교, 교신 정리까지 맡기면서 몇 시간 걸리던 논문 요약·계약서 차이 파악이 몇 분으로 줄었지만, AI가 엉뚱한 숫자를 내놓거나 유창한 답도 사실 확인이 필요해 결국 자신의 지식을 다시 꺼내야 했다고 밝혔다. 해운회사는 항로·연료 최적화, 고장·항만 혼잡 예측 등 관리·예측·결정의 효율화를 기대하지만, 대기는 본질적으로 혼돈계이고 2023년 파나마운하 가뭄 때 8월 대기 선박이 160척을 넘고 하루 통항 한도가 36척에서 12월 22척으로 줄었던 것처럼 해운의 불확실성은 사라지지 않는다고 짚었다. 그는 AI의 의미는 미래를 맞히는 데 있지 않고 볼 수 있는 범위를 넓히는 데 있으며 '같은 AI를 가지고도 무엇을 묻고 어디까지 일을 맡기느냐에 따라 결과는 크게 달라진다'고 결론냈다.","eSum":"Chung Han-hee, a visiting professor at Tongmyong University, writes that he moved from using generative AI like a search box to delegating emails, contract comparisons and correspondence summaries, cutting hours-long tasks such as summarising papers or spotting contract differences to minutes, yet the AI sometimes produced wrong figures and fluent answers still had to be fact-checked, forcing him to fall back on his own expertise. Shipping companies hope AI will make management, forecasting and decisions more efficient through route and fuel optimisation and breakdown and congestion prediction, but the atmosphere is inherently chaotic and uncertainty persists, as when drought at the Panama Canal in 2023 left more than 160 ships waiting in August and cut daily transits from 36 to 22 by December. He concludes that AI's value lies not in predicting the future but in widening what people can see, and that results depend heavily on what users ask and how much work they hand over.","kImp":"AI로 초안을 쓴 운항·안전 문서에는 수치와 사실을 사람이 확인하는 단계를 명시하고, 어떤 업무를 어디까지 AI에 맡길지 부서별로 정한 짧은 지침을 만들어 볼 만하다.","eImp":"AI-drafted operational and safety documents could carry an explicit human check of figures and facts, alongside a short guideline setting out which tasks each department may hand to AI and how far.","url":"https://www.maritimepress.co.kr/news/articleView.html?idxno=333588","prio":1,"mar":true,"tags":["AI","WR"]},{"code":"CHANGE","date":"2026-10-24","src":"Maritime Gateway","title":"OneOcean·Thetius 조사: 82% '현행 교육은 디지털 선박 운항에 못 미친다' — 52% '자격 갖춘 선원도 실제 운항에서 자주 고전'","eTitle":"OneOcean-Thetius Research: 82% of Maritime Professionals Say Current Training Does Not Prepare Seafarers for Modern Digital Vessel Operations","kSum":"OneOcean이 의뢰하고 Thetius가 수행한 보고서 두 편('Competent or Compliant?', 'Decision-optimised or overloaded?')은 선장·사관·기관사·감독·교육·크루잉·육상 운항 담당자 설문과 인터뷰를 바탕으로, 응답자 82%가 현행 교육이 현대 선박 운항에 충분히 대비시키지 못한다고 답했다(충분하다 18%)고 밝혔다. 52%는 자격을 갖춘 선원이 실제 운항에서 '자주' 또는 '매우 자주' 고전한다고 했고 56%는 '체크박스식' 컴플라이언스를 원인으로 꼽았으며, 격차가 드러나는 상황은 비정상·예상 밖 상황 67%, 고압 작업 56%, 다른 선박으로 옮겨 일할 때 36%, 복잡한 디지털 시스템·ECDIS·보고 도구 31%였다. GNSS 교란 뒤 업무량이 중간 이상 늘었다는 선원은 75%였고, 보고서는 서로 연동되지 않는 시스템 때문에 선원이 상충 데이터를 손으로 맞추면서 경보 피로와 정보 과부하가 커진다고 지적했다. 응답자 수는 공개되지 않았다.","eSum":"Two reports commissioned by OneOcean and conducted by Thetius, 'Competent or Compliant?' and 'Decision-optimised or overloaded?', draw on surveys and interviews with masters, officers, engineers, superintendents, training, crewing and shore operations staff and find that 82% say current training does not adequately prepare seafarers for modern vessel operations, against 18% who say it does. 52% said qualified crew often or very often struggle in real operating conditions and 56% blamed tick-box compliance, with gaps most visible in abnormal or unexpected situations (67%), high-pressure operations (56%), moving between vessels (36%) and complex digital systems, ECDIS and reporting tools (31%). 75% of mariners reported a moderate to significant workload increase after GNSS interference, and the reports warn that poorly integrated systems force crews to reconcile conflicting data by hand, adding alert fatigue and information overload. The sample size was not disclosed.","kImp":"선상 훈련·평가를 이수 기록이 아니라 비정상 상황 대응 시나리오(GNSS 교란, 시스템 간 상충 경보 등) 위주로 짜고, 다른 선형으로 옮겨 타는 사관의 숙지 교육을 따로 점검해 볼 만하다.","eImp":"Build onboard drills and assessments around abnormal scenarios such as GNSS interference or conflicting system alerts rather than completion records, and check familiarisation separately for officers moving to a different ship type.","url":"https://www.maritimegateway.com/82-of-maritime-professionals-call-for-better-alignment-between-training-and-shipboard-operations/","prio":3,"mar":true,"tags":["TRN","CHG","WR"]},{"code":"CHANGE","date":"2026-10-22","src":"Cyprus Shipping News","title":"OrbitMI '단절된 시스템과 AI 과열이 디지털 피로 키워' — WMU 조사 인용 '선원 80% 이상 디지털 역량 교육 거의·전혀 못 받아, 육상 교육이 선상 시스템 반영 13%'","eTitle":"Disconnected Systems and AI Hype Are Driving Digital Fatigue in Shipping, Warns OrbitMI, Citing WMU Data on Missing Digital-Skills Training","kSum":"OrbitMI CEO Egil Husby는 기술이 약속한 단순화·생산성 향상을 내놓지 못할 때 쌓이는 회의감과 좌절을 '디지털 피로'라 부르며, 해운이 '기술을 연결하는 속도보다 더 빨리 쌓아 왔다'고 말했다. 수년간 플랫폼과 부가 앱을 더했지만 팀들은 여전히 데이터를 손으로 옮기고 여러 대시보드를 오가며 상충 정보를 맞추느라 시간을 쓰고, 근거를 보여 주지 않는 1세대 AI가 '또 하나의 경보 층'이 되거나 검증할 수 없는 결과를 믿으라고 하면 신뢰가 빠르게 무너진다는 것이다. 회사는 2026년 6월 WMU 연구(64개국 선원 532명 설문·이해관계자 110명 인터뷰)에서 선원 80% 이상이 디지털 역량 교육을 거의 또는 전혀 받지 못하고 육상 교육이 선상 시스템을 꾸준히 반영한다는 응답은 13%뿐이었다고 인용하며, 기존 시스템·데이터를 업무 흐름에 맞게 연결하고 무엇을 왜 봐야 하는지 설명하는 의사결정 지원과 사람의 최종 책임을 권했다(자사 신규 플랫폼 홍보 포함).","eSum":"OrbitMI CEO Egil Husby describes 'digital fatigue' as the scepticism and frustration that build when technology fails to deliver simpler work or measurable gains, saying shipping 'has accumulated technology faster than it has connected it'. Teams still move data by hand, switch between dashboards and reconcile conflicting information after years of added platforms and bolt-on apps, and first-wave AI that adds 'another layer of alerts' or asks people to trust unverifiable outputs quickly erodes confidence. Citing a June 2026 World Maritime University study of 532 seafarers in 64 countries and 110 stakeholder interviews, in which more than 80% of seafarers rarely or never receive digital-skills training and only 13% say shore-based training consistently reflects onboard systems, the company calls for connecting existing systems and data within workflows, decision support that explains what needs attention and why, and human responsibility for final decisions, while promoting its own forthcoming platform.","kImp":"새 시스템 도입을 검토할 때 기존 시스템·데이터와 연결되는지, 중복 입력이 생기지 않는지를 승인 조건으로 확인하고, 선상에서 쓰는 시스템 수를 정기적으로 점검해 통합하거나 없앨 수 있는 것을 찾아볼 만하다.","eImp":"When reviewing a new system, make integration with existing systems and data and the absence of duplicated data entry conditions for approval, and regularly review the number of systems used on board to find ones that can be merged or retired.","url":"https://cyprusshippingnews.com/2026/10/22/disconnected-systems-and-ai-hype-are-driving-digital-fatigue-in-shipping-warns-orbitmi/","prio":1,"mar":true,"tags":["CHG","AI","TRN"]},{"code":"CHANGE","date":"2026-10-13","src":"Hellenic Shipping News","title":"'기술이 병목이 아니다, 프로세스와 사람이 바뀌어야' — Inmarsat SMM 세미나서 Hapag-Lloyd·Anglo-Eastern·Fairplay '선원은 IT 전문가가 될 수 없다, 함께 일하는 구조를'","eTitle":"Connecting Maritime Digitalisation to Process: Panel Says Organisations and People, Not Technology, Are the Bottleneck","kSum":"Inmarsat Maritime이 SMM 함부르크 기간 연 'Connected to Perform' 세미나 패널에서 Audra Drablos 전략이사는 기술이 아니라 조직이 기술을 쓰는 방식이 병목이며 디지털화는 의사결정 과정 자체를 바꾸는 일이라고 말했고, Hapag-Lloyd의 Patrick Briest는 대시보드의 권고가 실행되려면 조직·프로세스·사람이 모두 바뀌어야 한다고 했다. Anglo-Eastern 독일 법인의 Mathias Becker는 데이터가 고립된 시스템에 흩어져 있다며 '선원이 IT 전문가가 되지는 않을 것'이므로 선원·해상 인력과 데이터·IT 팀이 함께 일해야 한다고 했고, Fairplay Towage의 Konstantin Pohsin 선대 선장은 연결된 선상 시스템에 대한 '지식 격차'가 있어 전 직원 교육 방법을 찾고 있다며 선원들에게 스스로 생각하기를 멈추지 말라고 당부했다. 패널은 AI를 데이터 분석·컴플라이언스 업무를 덜어 주는 보조로 보고 사람의 판단을 중심에 두라고 했으며, Drablos는 책임이 가장 큰 선원의 행복도가 가장 낮다는 선원 행복지수 결과를 인용했다.","eSum":"At Inmarsat Maritime's 'Connected to Perform' seminar during SMM Hamburg, Strategy Director Audra Drablos said the bottleneck is not technology but how organisations use it, since digitalisation means transforming decision processes, and Hapag-Lloyd's Patrick Briest said the whole organisation, its processes and its people must change for a dashboard's recommendations to happen. Mathias Becker of Anglo-Eastern Germany said data sits in isolated systems and that seafarers will not become IT experts, so crews, offshore staff and data and IT teams must work together, while Fairplay Towage Fleet Captain Konstantin Pohsin described a 'gap in knowledge' around connected onboard systems, said the company is working out how to train all employees and urged seafarers not to stop thinking for themselves. The panel framed AI as relief from data-analysis and compliance work with human judgement kept central, and Drablos cited a Seafarers Happiness Index finding that seafarers with the most responsibility report the lowest happiness.","kImp":"새 디지털 도구를 들이기 전에 '누가 이 정보를 보고 어떤 결정을 바꾸는가'를 먼저 정의하고, 선상 사용자와 육상 IT·데이터 담당이 함께 운영 점검을 하는 정기 회의를 두어 볼 만하다.","eImp":"Before introducing a new digital tool, define who will act on its information and which decisions it should change, and hold regular joint reviews between shipboard users and shore IT and data staff.","url":"https://www.hellenicshippingnews.com/connecting-maritime-digitalisation-to-process/","prio":1,"mar":true,"tags":["CHG","WR","TRN"]},{"code":"CHANGE","date":"2026-10-07","src":"Safety4Sea","title":"'설계가 곧 준비는 아니다' — 신연료 도입의 안전 작업, 메탄올·암모니아 경험은 서로 대체 불가… 선박별 숙지·역할 구분·반복 가능성이 관건","eTitle":"Analysis: The Safety Work Behind New-Fuel Adoption, as Experience With One Fuel Is No Operating Model for Another","kSum":"Safety4Sea 분석은 신연료용으로 지은 선박이라는 사실이 그 항로에서 안전하게 벙커링하고 선원이 다루며 일상적으로 쓸 수 있다는 증명은 아니라며, 벙커링은 선박·공급사·항만이 호환 장비, 합의된 절차, 책임에 대한 공동 이해를 갖춘 하나의 작업이어야 한다고 지적했다. 메탄올 벙커링 항만은 19곳에서 29곳으로 늘었지만(UCL 보고서) 항만 수로는 특정 항해에서 연료를 구할 수 있는지, 실제로 몇 번 해 봤는지 알 수 없고, 메탄올 경험이 암모니아에 그대로 통하지 않으며, 교육은 선두 기업에 몰려 업계 전반에 정착하지 못했다. 기사는 지침이 선박별 설비 이해를 대신할 수 없다며 정상 운용·이송 중 설비 거동과 '언제 멈출지'를 아는 선박 맞춤 숙지, 지정 안전 임무자와 연료 계통 직접 책임자의 구분, 누가 결정·운전·대응하는지의 명확화, 시운전 성공보다 여러 항해·선원·공급사·항만에서의 반복 가능성을 강조하고, 승인 설비·벙커링 예정지·공급사 조건·선원 숙지 입증·비정상 작업 대응을 잇는 준비도 검토를 제안했다.","eSum":"A Safety4Sea analysis argues that a ship designed for a new fuel does not prove the fuel can be bunkered safely on its route, handled by its crew or used routinely, and that bunkering must work as one operation of ship, supplier and port with compatible equipment, agreed procedures and shared understanding of responsibilities. Methanol bunkering ports have risen from 19 to 29, per a UCL report, but port counts do not show availability on a given voyage or how often operations have actually been done, methanol experience cannot be assumed to cover ammonia, and training remains concentrated among leading organisations. It stresses ship-specific familiarisation covering how the installation behaves in normal use and transfer and when to stop, a clear split between designated safety roles and those responsible for fuel systems, clarity on who decides, operates and responds, and repeatability across voyages, crews, suppliers and ports rather than one successful trial, proposing a readiness review linking approved arrangements, planned bunkering locations, supplier arrangements, demonstrated crew familiarity and response to abnormal operations.","kImp":"신연료 선박에 선원을 배치하기 전 일반 교육 이수와 별도로 그 선박의 설비 숙지와 '작업 중단 기준'을 직접 시연하게 하고, 한 선박의 벙커링 교훈을 다른 선박에 넘길 때는 설비 차이를 먼저 확인하는 절차를 둘 만하다.","eImp":"Before assigning crews to a new-fuel ship, have them demonstrate familiarity with that ship's installation and its stop-work criteria separately from generic course completion, and check equipment differences before passing one ship's bunkering lessons to another.","url":"https://safety4sea.com/cm-analysis-the-safety-work-behind-new-fuel-adoption/","prio":2,"mar":true,"tags":["CHG","TRN"]},{"code":"CHANGE","date":"2026-10-06","src":"The Maritime Executive","title":"Thetius·Marcura 'Earning Trust: AI in Maritime' — 63%가 매일 AI를 쓰지만 '성숙·통제된 조직'은 8%, 55%는 주 1시간 이상 AI 결과 검증","eTitle":"Thetius-Marcura Research: Maritime Uses AI Every Day, but Only 8% Call Their Organisation's AI Use Mature and Governed","kSum":"Thetius와 Marcura의 보고서 'Earning Trust: AI in Maritime'에 따르면 해사 종사자 63%가 매일 AI를 쓰지만 자기 조직의 AI 활용이 성숙하고 통제된다는 응답은 8%였고, 72%가 행동형(agentic) AI를 사용·시범·계획 중인 반면 거버넌스가 준비됐다는 곳은 15%였다. 55%는 AI 결과를 확인·수정하는 데 주 1시간 이상(약 5명 중 1명은 5시간 이상)을 써 보고서는 이를 '검증세(verification tax)'라 불렀지만 85%는 전체적으로 시간이 절약된다고 답했고, 57%는 AI 결과 신뢰도를 5점 척도의 중간에 뒀으며 10명 중 7명은 중요한 결정 전 AI 권고를 항상 확인하고 80%는 상업적 결정마다 책임자가 지정돼야 한다고 했다. 75%는 AI가 경험이 적은 동료의 숙련을 앞당긴다고 봤고, 보고서는 AI 결과만이 아니라 사람-AI 과정 전체를 측정하고, 꼭 필요한 검증과 불확실성에서 나온 확인을 구분하며, 사람의 수정을 성능 개선에 쓰고 소유·거버넌스를 명확히 하라고 권했다. 응답자 수는 공개되지 않았다.","eSum":"Thetius and Marcura's report 'Earning Trust: AI in Maritime' finds that 63% of maritime professionals use AI every day but only 8% describe their organisation's AI use as mature and governed, while 72% are using, piloting or planning agentic AI and just 15% say their governance is ready for it. 55% spend at least an hour a week checking or correcting AI output and almost one in five five hours or more, a 'verification tax', although 85% say AI saves time overall; 57% put their trust in AI outputs at the midpoint of a five-point scale, seven in ten always check an AI recommendation before an important decision and 80% say a named person should always be accountable for a commercial decision. 75% say AI helps less-experienced colleagues become effective faster, and the report recommends measuring the whole human-AI process rather than the output alone, separating necessary verification from uncertainty-driven checking, feeding human corrections back into performance and setting clear ownership and governance. The number of respondents was not disclosed.","kImp":"선상·육상에서 AI 도구를 쓸 때 업무별로 '누가 결과를 확인하고 최종 책임을 지는가'를 정해 두고, 검증에 드는 시간도 함께 기록해 실제 효과를 판단해 볼 만하다.","eImp":"When AI tools are used on board or ashore, define for each task who checks the output and who is accountable for the final decision, and log the time spent verifying so the real benefit can be judged.","url":"https://maritime-executive.com/corporate/maritime-is-using-ai-every-day-now-comes-the-harder-part-trusting-it-to-act","prio":2,"mar":true,"tags":["AI","CHG","WR"]},{"code":"CHANGE","date":"2026-10-05","src":"Riviera Maritime Media","title":"OSV 운영사 원탁회의 '항법 복원력은 기술보다 교육 문제' 만장일치 — 시스템마다 따로 교육 부담, AI엔 회의적, 승선 지도(sea-riding)로 보완","eTitle":"OSV Operators Put Training Before Technology for Safer Navigation at an Inmarsat-Riviera Roundtable","kSum":"Inmarsat Maritime이 Riviera Maritime Media와 9월 싱가포르 Offshore Support Journal Conference Asia에서 연 원탁회의(채텀하우스 규칙)에서 중동·동지중해·중국해·브라질·북해의 PSV·건설·중량물·인원수송선 운영사 참석자 전원이 항법 복원력은 기술 이전에 교육 문제라고 투표했다(반대 없음). 선원이 기만(spoofing)된 위치 정보를 알아챌 것이라는 신뢰는 대체로 '보통'이었고 '높음'은 적었으며 2명은 '낮음'이라고 답했고, 해기교육 커리큘럼이 30년간 거의 그대로라는 지적과 별개 시스템마다 따로 교육이 필요하다는 불만이 나왔다. 연결성은 이제 채용 조건이 됐고 육상과의 원격 지원·영상통화가 선원 참여를 높인다는 평가가 있었지만 집안 문제가 배로 들어오고 식당에 모이는 선원이 줄었다는 우려도 나왔으며, AI는 도구가 판단을 대신한다는 회의론이 컸다. 주된 대책으로는 갑판·기관 지도 인력이 승선해 사관이 시스템을 감시만 하지 않고 직접 선박을 다루도록 하는 sea-riding 프로그램이 꼽혔다.","eSum":"At a roundtable hosted by Inmarsat Maritime with Riviera Maritime Media during September's Offshore Support Journal Conference Asia in Singapore, under the Chatham House Rule, operators of platform supply, construction, heavy-lift and crew transfer vessels working in the Middle East, Eastern Mediterranean, China Seas, Brazil and the North Sea all voted that navigation resilience is a training problem before a technology problem, with no dissent. Confidence that crews would spot spoofed positioning data was mostly moderate, few rated it high and two rated it low, and participants said academy curricula have barely changed in 30 years and that too many separate systems each require their own training. Connectivity is now expected in recruitment and remote support and video calls with shore staff were said to improve engagement, though constant contact with home and fewer crews gathering in the mess were concerns, and AI drew scepticism about tools substituting for judgement. Sea-riding programmes, putting deck and engineering riders aboard so officers drive the vessel rather than just supervise systems, were the main control cited.","kImp":"새 시스템을 더하기 전에 선박별로 사관이 따로 익혀야 하는 시스템 수와 교육 부담을 목록으로 만들고, 경험 많은 감독·선장이 승선해 실제 조선을 함께하는 승선 지도를 늘려 볼 만하다.","eImp":"Before adding systems, list for each ship how many separate systems officers must learn and the training load involved, and expand sea-riding by experienced superintendents and masters who handle the ship alongside officers.","url":"https://www.rivieramm.com/news-content-hub/osv-operators-put-training-before-tech-for-safer-navigation-90184","prio":2,"mar":true,"tags":["TRN","CHG","AI"]},{"code":"CHANGE","date":"2026-09-30","src":"Ship Management International","title":"Eastern Pacific Shipping, 161척 전 선대에 마이크로러닝 30일 만에 도입 — 45일간 485명이 영상 2만6,722편·2,181시간 자율 학습","eTitle":"Microlearning Drives Self-Directed Crew Training Across Eastern Pacific Shipping's 161-Ship Fleet","kSum":"선박관리사 Eastern Pacific Shipping(EPS)은 MarinePALS의 마이크로러닝 플랫폼(짧은 주제별 영상·게임화·VR)을 161척 전 선대에 30일 만에 도입했고, 처음 45일 동안 활성 사용자 485명이 영상 26,722편, 2,181시간을 학습해 1인당 평균 55편 이상을 봤다(한 선박은 3,810편). 선원들은 배정된 과정에 그치지 않고 스스로 주제를 찾아 다시 접속했고, 개인 점수표와 선대 순위표로 진행을 보여 주며 회사는 이수 여부보다 시청 수·학습 시간을 본다. EPS 교육 매니저 Capt. Pradeep Singh는 '강한 학습 욕구'를 확인했다고 했고, MarinePALS CEO는 심화 주제와 공식 평가에는 긴 과정이 여전히 필요해 마이크로러닝은 의무 교육을 대체하지 않고 보완한다고 했다. 공급사 측 자료로 45일 단기 결과이며 역량·안전 성과는 보고되지 않았다.","eSum":"Ship manager Eastern Pacific Shipping rolled out MarinePALS's microlearning platform of short topic videos, gamification and VR across all 161 vessels within 30 days, and in the first 45 days 485 active users watched 26,722 videos and logged 2,181 training hours, averaging more than 55 videos each, with one ship watching 3,810. Crews explored subjects beyond assigned courses, individual scorecards and fleet leaderboards made progress visible, and the company tracks viewing and time spent rather than completion alone. EPS Training Manager Capt. Pradeep Singh reported a strong appetite for learning, while MarinePALS' CEO said longer courses remain necessary for depth and formal assessment, so microlearning complements rather than replaces mandatory training. The figures are vendor-supported, cover only 45 days and do not include competence or safety outcomes.","kImp":"새 교육 시스템을 들일 때 이수율 대신 자발적 재접속·학습 시간 같은 실제 사용 지표를 보고, 근무 사이에 볼 수 있는 짧은 사고 교훈·절차 변경 영상을 시험해 볼 만하다.","eImp":"When introducing a new training system, track real use such as voluntary return visits and time spent rather than completion rates, and trial short videos on incident lessons and procedure changes that fit between duties.","url":"https://www.shipmanagementinternational.com/news/8b2dh4cw8th922f-lfj5n-lcmpx-nxsw6-57rhl-cln6f-7n9b4","prio":2,"mar":true,"tags":["TRN","CHG","ENG"]},{"code":"CHANGE","date":"2026-09-15","src":"MarineLink","title":"Multraship '디지털 훈련이 미래의 선원을 끌어온다' — 예인선 전용 시뮬레이터에 노련한 선장 주도 디브리핑 결합, '실수에서 배울 안전한 공간'","eTitle":"How Digital Training Will Attract 'Crews of the Future': Multraship Pairs a Tug Simulator With Debriefs Led by Experienced Captains","kSum":"Multraship Tug & Salvage의 Bianca Pielaat 운영이사(승선 경력 25년 이상)는 MarineLink 기고에서 회사가 2026년 5월 Wärtsilä와 함께 테르뇌전 본사에 좁고 얕으며 유속이 빠른 수역과 변하는 기상에서의 예인선 조종을 훈련하는 디지털 시뮬레이터를 열었다고 소개했다. 시나리오마다 경험 많은 예인선 선장 출신 교관이 디브리핑을 이끌며 무엇이 잘못됐고 무엇을 바꿀지 토론하게 하고 이의 제기와 비판적 사고를 장려하는데, 그는 '이런 사람 간의 토론이 기술만큼 중요하다'고 말했다. 그는 시뮬레이터가 젊은 신입에게 '실수에서 배울 안전한 공간'을 주고 빠른 역량 향상을 느낀 선원이 추가 교육에 자원해 유지와 팀 결속에 도움이 되지만, 판단력과 리더십은 여전히 수년의 승선으로 길러지므로 디지털 훈련은 승선 경험을 보완할 뿐이라고 강조했으며, BIMCO·ICS 선원 인력 보고서 2026의 '2030년까지 최대 11만4,000명 사관 필요' 전망을 인용했다.","eSum":"In a MarineLink article, Bianca Pielaat, Operations Director of Multraship Tug & Salvage with more than 25 years at sea, describes the tug simulator suite the company opened at its Terneuzen headquarters with Wärtsilä in May 2026 to train manoeuvring in confined, shallow, fast-flowing waters and changing weather. After each scenario, trainers who are mostly experienced tug captains lead debriefs on what went wrong and what crews would change, encouraging challenge and critical thinking, and she says 'these human discussions are just as important as the technology itself'. Simulation gives younger recruits 'a safe and secure space to learn from mistakes' and crews who see faster progress may volunteer for more training, supporting retention and team cohesion, but judgement and leadership still take years at sea, so digital training complements rather than replaces sea time; she cites the BIMCO and ICS Seafarer Workforce Report 2026 estimate that up to 114,000 officers are needed by 2030.","kImp":"시뮬레이터·모의 훈련 뒤 경험 많은 선장이 이끄는 짧은 디브리핑에서 '무엇을 다르게 하겠는가'를 묻고 하급 사관의 이의 제기를 장려하는 방식을 선상 훈련에도 적용해 볼 만하다.","eImp":"After simulator sessions and drills, hold short debriefs led by an experienced master that ask what crews would do differently and encourage junior officers to challenge, and apply the same format to onboard drills.","url":"https://www.marinelink.com/news/digital-training-attract-crews-future-542970","prio":1,"mar":true,"tags":["TRN","RET","CHG"]},{"code":"CHANGE","date":"2026-08-21","src":"Digital Ship","title":"전직 선원 기고 '육상이 고른 신기술, 선원 영향은 모른 채' — 디지털 의존·연결성이 바꾼 선상 생활, 도입 결정에 선원을 참여시켜야","eTitle":"How Onboard Technology Affects Crew Welfare: A Former Seafarer Warns of Over-Reliance and Shore-Led Technology Choices","kSum":"전직 선원으로 Manta Marine에서 일하는 Robin Wulf는 Digital Ship 기고에서 ECDIS 자동 업데이트처럼 시간을 아껴 주는 기술도 있지만 '선상 디지털화의 가장 큰 문제는 우리가 너무 의존하게 된다는 것'이라며, AIS 정보를 검증 없이 믿는 사관후보생을 봤고 ECDIS가 고장 나면 신규 선원이 항해할 수 있을지 의문이라고 했다. 연결성 향상은 가족과의 연락을 돕지만 집안 문제를 알고도 도울 수 없어 향수와 괴로움이 커질 수 있고, 선원들이 인터넷을 쓰러 선실로 들어가면서 선상 동료애가 약해졌다고 지적했다. 그는 육상 인력이 선원에게 미칠 영향을 충분히 모른 채 신기술을 고르는 일이 잦다며, 선상 사용자가 고장을 점검할 수 있게 설계하고, 도입 결정에 선원을 참여시키며, 새 도구가 일을 줄이는지 확인하고, AI는 판단을 대신하지 않는 의사결정 보조로 쓰라고 권했다.","eSum":"In a Digital Ship feature, former seafarer Robin Wulf, who works for Manta Marine, says some technology such as automatic ECDIS updates saves real time, but 'the biggest factor with all this onboard digitalisation is that we are becoming too reliant on it', citing cadets trusting AIS data without checking it and asking whether new seafarers could navigate if ECDIS failed. Better connectivity helps family contact but can deepen homesickness when seafarers learn of problems at home they cannot help with, and crews retreating to cabins to use the internet have weakened onboard camaraderie. He argues that shore staff often choose new technology without fully understanding its effect on crews, and recommends systems that onboard users can fault-check, involving crews in technology decisions, making sure new tools remove tasks rather than add them, and using AI as a decision aid rather than a replacement for judgement.","kImp":"새 선상 시스템을 고를 때 시범 선박 사관·부원의 의견을 공식 평가 항목으로 넣고, 도입 뒤 '없어진 일과 늘어난 일'을 선원에게 직접 물어 확인해 볼 만하다.","eImp":"When selecting a new onboard system, make feedback from officers and ratings on a trial ship a formal evaluation criterion, and after roll-out ask crews directly which tasks disappeared and which were added.","url":"https://thedigitalship.com/big-reads/how-onboard-technology-affects-crew-welfare/","prio":1,"mar":true,"tags":["CHG","WELL","AI"]},{"code":"CHANGE","date":"2026-08-09","src":"한국해운신문","title":"KOMSA, 연안여객선 선원 안전교육을 생성형 AI 대화형 팟캐스트로 — 집합교육 어려운 선원 위해 도입, 상반기 1,804명 참여·만족도 88.6%","eTitle":"KOMSA Turns Coastal Ferry Crew Safety Training Into Generative-AI Conversational Podcasts, Reaching 1,804 Crew in the First Half With 88.6% Satisfaction","kSum":"한국해양교통안전공단은 해상 근무로 집합교육 참여가 어려운 연안여객선 선원·종사자를 위해 기존 안전교육 자료를 생성형 AI로 대화형 팟캐스트로 바꿔 지난해 시범 운영한 뒤 올해 본격 확대했으며, 교육 인원은 지난해 752명에서 올해 상반기 1,804명으로 늘었고 만족도는 88.6%였다. 주제는 기관손상사고 예방, 소화설비 운용, 안전운항 요령, 온열질환 예방으로, 조타실·선실 등 선박 어디서나 정박 중이나 휴식 시간에 반복해 들을 수 있고 공단 누리집에서 무료로 내려받을 수 있다. 공단은 활자 중심 교재와 집합교육에 부담을 느꼈던 선원들이 휴식 시간이나 출퇴근길에 들을 수 있어 실무에 도움이 된다는 반응을 보였다며, AI 기반 영상 교재와 외국인 선원용 교육 콘텐츠도 개발할 계획이라고 밝혔다.","eSum":"The Korea Maritime Transportation Safety Authority used generative AI to turn its safety training materials for coastal passenger ship crew and staff, who find classroom sessions hard to attend because of sea duty, into conversational podcasts, piloted last year and expanded this year; participation rose from 752 last year to 1,804 in the first half of this year, with satisfaction at 88.6%. Topics include preventing machinery damage, operating fire-fighting systems, safe navigation practice and heat illness prevention, and episodes can be replayed anywhere on board, from the wheelhouse to cabins, in port or during rest, with free downloads from the authority's website. The authority said crew who had struggled with text-heavy manuals and classroom training found they could listen during breaks or commutes, and it plans AI-based video materials and content for foreign seafarers.","kImp":"선상 안전 회람이나 사고 교훈을 짧은 대화형 오디오로 바꿔 당직 교대·휴식 시간에 들을 수 있게 하고, 다국적 선원을 위해 언어별 버전을 시험해 볼 만하다.","eImp":"Safety circulars and lessons learned could be turned into short conversational audio for crew to hear during watch handovers or rest periods, with language versions trialled for multinational crews.","url":"https://www.maritimepress.co.kr/news/articleView.html?idxno=332521","prio":2,"mar":true,"tags":["TRN","AI","WR"]},{"code":"CHANGE","date":"2026-06-25","src":"World Maritime University","title":"WMU 글로벌 연구 '해사 인력이 디지털 변화 속도를 못 따라간다' — 선원 80% 이상 디지털 역량 교육 거의·전혀 없어, 육상 교육이 선상 시스템과 일치한다는 응답 13%","eTitle":"WMU Global Study Warns the Maritime Workforce Is Not Keeping Pace With Digital Change","kSum":"세계해사대학(WMU)이 Lloyd's Register Foundation의 Global Maritime Trends 프로그램 지원으로 낸 'Digital skills in maritime education and training'은 64개국 선원 532명 설문과 이해관계자 110명 인터뷰를 바탕으로, 선원 80% 이상이 디지털 역량 교육을 거의 또는 전혀 받지 못하고 육상 교육이 선상에서 쓰는 시스템과 꾸준히 일치한다는 응답은 13%뿐이라고 밝혔다. 3분의 2는 역량을 높일 의향이 있었지만 선원들은 자동화·데이터 집약 도구보다 전통적 시스템을 더 신뢰했고, '디지털 역량'의 공통 정의가 없어 진전이 더디며, 교육기관은 자금 부족·디지털 역량을 갖춘 교관 부족·느린 규제에 막혀 있다고 연구는 지적했다. Global Maritime Trends 디지털 전환 지표의 '사람' 부문은 6포인트 올라 38%였지만 여전히 가장 약한 영역 중 하나였고, 연구는 국제 교육 기준의 빠른 갱신, 교육 투자 확대, 업계·규제기관·교육기관의 협력을 권고했으며, Lloyd's Register Foundation의 Jan Przydatek은 '기술과 함께 사람에 투자하지 않으면 새로운 안전 문제를 만들 수 있다'고 말했다.","eSum":"'Digital skills in maritime education and training', a World Maritime University study funded by Lloyd's Register Foundation through its Global Maritime Trends programme, draws on a survey of 532 seafarers in 64 countries and 110 stakeholder interviews and finds that more than 80% of seafarers rarely or never receive digital-skills training and only 13% say shore-based training consistently matches the systems they use on board. Two-thirds are willing to upskill, but seafarers trust traditional systems more than automation and data-intensive tools, the lack of a shared definition of digital skills slows progress, and training providers face limited funding, a shortage of digitally skilled instructors and slow regulation. The People pillar of the Global Maritime Trends Digital Transition Barometer rose six points to 38% but remains one of the weakest areas, and the study calls for faster updates to global training standards, more investment in education and closer collaboration between industry, regulators and training providers, with Lloyd's Register Foundation's Dr Jan Przydatek warning that 'if we don't invest in people alongside technology, we risk creating new safety challenges'.","kImp":"선상 시스템 교육을 육상 교육장 장비가 아니라 실제 승선할 선박의 화면·버전으로 하고 있는지 확인하고, 선원이 믿지 않는 자동화 기능이 무엇인지 승선 설문으로 파악해 교육 우선순위를 정해 볼 만하다.","eImp":"Check that training on onboard systems uses the screens and software versions of the ships crews will join rather than shore training equipment, and use onboard surveys to identify which automated functions crews distrust in order to set training priorities.","url":"https://www.wmu.se/news/global-study-warns-maritime-workforce-not-keeping-pace-digital-change","prio":3,"mar":true,"tags":["TRN","CHG"]},{"code":"CHANGE","date":"2026-10-27","src":"DBR","title":"DBR 스페셜 리포트 'AI 위임 시대, 성과 평가 어떻게 바꿀까' — 산출량만 보면 AI 결과를 검증한 직원이 손해, 도입 단계별 지표·사람과 AI 성과 분리·AI 없이 점검하는 역량 평가를","eTitle":"DBR Special Report: Rethinking Performance Reviews for AI Delegation - Output Counts Penalise Staff Who Check AI Work, So Use Stage-Based Measures, Separate Human and AI Results and Assess Checking Without AI","kSum":"동국대 이중학 교수는 DBR 11월 1호(10월 27일 발행) 스페셜 리포트에서 AI 도입은 늘었지만 성과의 증거는 드물다며, 문제는 기술이 아니라 AI 이전의 잣대로 AI 이후의 일을 평가하는 데 있다고 짚었다. 맥킨지 2025년 조사에서 AI를 한 개 이상 업무에 쓰는 기업은 열에 아홉이지만 이익에 의미 있게 기여했다는 곳은 6% 안팎이었고, 한국은행 2026년 6월 분석에서는 AI로 주당 약 1.5시간(4% 안팎)을 아꼈지만 업무 처리량 증가와의 상관은 0이었다. 그는 도입 초기에는 즉각적 재무 성과 대신 재작업률·업무 품질·재설계 실행률을 재고, AI 에이전트·개인·사람과 AI 결합 성과를 구분하되 에이전트 성과는 반드시 사람의 책임과 연결하며, 첫해에는 기록과 별도 포상으로 인정하고 AI 없이 점검·설명하는 역량을 평가에 넣으라고 제안했다(구독 기사, 공개된 앞부분 기준).","eSum":"In DBR's 1st November issue (published 27 October), Dongguk University professor Lee Jung-hak argues that AI adoption is spreading but evidence of results is scarce because work done with AI is still judged by pre-AI yardsticks. A 2025 McKinsey survey found about nine in ten firms use AI in at least one function but only around 6% report a meaningful profit contribution, and a June 2026 Bank of Korea analysis found AI saved about 1.5 hours a week (around 4%) with zero correlation to higher work throughput. He proposes measuring rework rates, work quality and redesign progress rather than immediate financial returns in the early stage; separating the performance of AI agents, individuals and human-AI combinations while always tying agent results to a person's accountability; recognising contributions through records and separate awards in the first year; and assessing people's ability to check and explain work without AI (subscriber article; summary based on the free opening section).","kImp":"보고서·점검표 작성에 AI를 쓰기 시작하는 선박·육상 조직이라면 산출 건수보다 오류를 잡아낸 검증 행동을 인정하고, 'AI가 만든 결과의 책임자'를 직책별로 정해 두는 것이 좋다.","eImp":"Ship and shore teams starting to use AI for reports or checklists could reward the verification work that catches errors rather than output volume, and name by role who is accountable for AI-generated results.","url":"https://dbr.donga.com/article/view/1101/article_no/12311","prio":2,"mar":false,"tags":["AI","WR","CHG"]},{"code":"CHANGE","date":"2026-10-27","src":"DBR","title":"DBR '직원이 AI를 더 신뢰하게 하려면 리더가 걱정을 겸손히 들어야' — 우려를 말할 기회와 리더의 겸손이 리더 신뢰를 거쳐 AI 신뢰로 옮겨간다(미국 직장인 487명 연구)","eTitle":"DBR: To Make Staff Trust AI, Leaders Must Listen Humbly to Their Concerns - Voice and Leader Humility Build Trust in the Leader That Transfers to AI (a Study of 487 US Employees)","kSum":"DBR 11월 1호(10월 27일 발행)는 McGuire·De Cremer·Narayanan의 2026년 『Journal of Business Research』(217권) 논문을 소개했다. 싱가포르경영대·킹파드석유광물대·스탠퍼드대 연구진은 일반 직원이 AI의 성능이나 판단 과정을 직접 평가하기 어렵다는 점에 주목해, 직원이 AI에 대한 우려를 말할 기회를 얻고 리더가 자기 판단이 틀릴 수 있음을 인정하며 겸손하게 들을 때 부정적 감정이 줄고 리더 신뢰가 높아지며 그 신뢰가 리더가 도입한 AI로 옮겨간다는 가설을 두 차례 연구로 검증했고, DBR은 이를 '리더가 직원의 걱정을 겸손히 들어야 AI 신뢰가 높아진다'로 정리했다. 첫 연구는 주 2회 이상 AI를 쓰는 미국 정규직 직장인을 1주 간격으로 네 차례 설문해 487명의 자료를 분석했고, 응답자의 73.3%는 추천 시스템형 AI를 쓰고 있었다(구독 기사, 공개된 앞부분 기준).","eSum":"DBR's 1st November issue (published 27 October) reviews a 2026 Journal of Business Research paper (vol. 217) by Jack McGuire, David De Cremer and Devesh Narayanan. Noting that ordinary employees struggle to judge an AI system's accuracy or reasoning, the researchers from Singapore Management University, King Fahd University of Petroleum and Minerals and Stanford tested in two studies whether giving staff a chance to voice concerns about AI, with leaders listening humbly and admitting they could be wrong, reduces negative feelings and raises trust in the leader that then transfers to the AI the leader introduced; DBR sums up the finding as leaders needing to hear staff worries humbly. The first study surveyed US full-time employees who use AI at least twice a week four times at one-week intervals and analysed 487 complete responses; 73.3% were using recommendation-type AI (subscriber article; summary based on the free opening section).","kImp":"선상에 새 디지털 시스템이나 AI 기반 도구를 들일 때 사용법 교육만 하지 말고 선원이 걱정과 불편을 말하는 시간을 따로 두고, 육상 담당자가 '우리 판단이 틀릴 수 있다'며 받은 의견을 실제로 반영하는 모습을 보여야 정착이 빨라진다.","eImp":"When introducing new digital or AI-based tools on board, shore teams could set aside time for crews to raise worries and frustrations, not just train them, and visibly act on that feedback while acknowledging that shore judgement can be wrong; adoption tends to stick faster that way.","url":"https://dbr.donga.com/article/view/1904/article_no/12308","prio":2,"mar":false,"tags":["AI","SPEAK","CHG"]},{"code":"CHANGE","date":"2026-10-23","src":"HR Insight","title":"AI가 만든 ‘워크슬롭’이 동료 시간을 빼앗는다 — “30분 만에 끝낸 일이 남의 한두 시간을 쓰면 업무 전가”, 완료 기준 4가지와 위험도별 차등 검토 제시","eTitle":"AI 'Workslop' Steals Colleagues' Time: Four Completion Criteria and Risk-Tiered Review for AI-Assisted Work","kSum":"송영선 건국대 교수는 생성형 AI 결과물을 충분히 검토하지 않고 넘겨 받는 사람이 사실 확인과 수정을 떠안는 '워크슬롭'이 개인 작업시간은 줄이지만 조직 전체 작업시간은 늘린다며, 30분 만에 끝낸 일이 동료의 한두 시간을 빼앗는다면 효율화가 아니라 업무 전가라고 지적했다. 완료 기준으로 핵심 사실·수치·인용을 사람이 확인했는지, 조직 상황에 맞게 고쳤는지, 받는 사람이 추가 작업 없이 쓸 수 있는지, 최종 검토자·책임자가 명확한지의 4가지를 제시했다. 내부 메모는 자기 검토로 충분하지만 경영진 보고·인사 결정·고객 자료는 엄격히 검증하는 위험도별 차등 검토를 권하고, 리더가 'AI를 얼마나 썼나' 대신 '바로 쓸 수 있나'를 물어야 하며 'AI 작성 참고용' 문구를 면책 수단으로 쓰지 말라고 강조했다.","eSum":"Konkuk University professor Song Young-sun warns that unchecked generative-AI output ('workslop') shifts fact-checking and rework onto recipients, cutting individual time while raising total organisational time; a task finished in 30 minutes that costs a colleague one or two hours is a transfer of work, not efficiency. He proposes four completion criteria: people have verified key facts, figures and citations, the output has been adapted to the organisation's context, the recipient can use it without extra work, and a final reviewer and owner are named. Review should be tiered by risk, light for internal memos but rigorous for executive reports, HR decisions and client material, leaders should ask whether work is usable rather than how much AI was used, and an 'AI-generated, for reference only' label should never excuse poor work.","kImp":"AI로 초안을 쓴 사고 보고서·점검 보고서·안전 회람에 '받는 사람이 추가 작업 없이 쓸 수 있는가'와 최종 검토 책임자를 명시하는 기준을 두고, 기국·선급·용선주에 나가는 문서는 사실·수치 검증을 필수로 해 볼 만하다.","eImp":"AI-drafted incident reports, inspection reports and safety circulars could carry a rule that the recipient can use them without rework and that a named reviewer signs off, with mandatory fact and figure checks for anything sent to flag states, class or charterers.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=112&bi_pidx=39672","prio":2,"mar":false,"tags":["AI","WR"]},{"code":"CHANGE","date":"2026-10-22","src":"HR Insight","title":"“조직의 기록이 AI의 신뢰를 결정한다” — 사내 문서 RAG의 환각은 맥락 빠진 기록 탓, 작성률 점검 대신 심리적 안전에 기반한 기록 문화 필요","eTitle":"Organisational Records Determine Whether AI Can Be Trusted: Hallucinations Trace Back to Context-Poor Records, and Record Quality Rests on Psychological Safety","kSum":"미디어젠 AI전략기획팀 안영규 매니저는 사내 원문을 상용 모델에 RAG로 연결한 HR AX 사례에서 환각이 적지 않았던 원인이 '적극 참여해 좋은 성과를 냄'처럼 구체 과업이 없는 피드백, 누가 왜 결정을 미뤘는지 빠진 회의록 같은 기록의 결함이라고 짚었다. 구글 리서치의 AI 실무자 53명 인터뷰에서 92%가 기록 단계의 작은 결함이 최종 단계의 큰 오류로 번지는 '데이터 캐스케이드'를 겪었다며, 무슨 일이 있었는지·무엇을 결정했는지·근거·남은 과제를 나누고 작성자 해석을 사실과 분리해 적자고 제안했다. 작성률 점검 같은 강제는 기록 피로와 의도적 누락을 부르고, 에이미 에드먼슨의 간호팀 연구에서 관계와 리더십이 좋은 팀일수록 투약 오류가 더 많이 보고된 것은 실수를 드러내도 괜찮다는 신뢰 때문이라고 설명했다(구독 기사로 후반부는 비공개).","eSum":"Ahn Young-kyu of Mediazen's AI strategy team traces frequent hallucinations in an HR AI project that linked internal documents to a commercial model via RAG to defective records, such as feedback with no concrete tasks and meeting minutes that omit who deferred a decision and why. Citing a Google Research study in which 92% of 53 AI practitioners had seen small recording flaws cascade into large downstream errors, he urges records that separate what happened, what was decided, the rationale, what remains open and the writer's own interpretation. He warns that policing completion rates breeds record fatigue and deliberate omissions, and cites Amy Edmondson's finding that nursing teams with better relationships and leadership reported more medication errors because people felt safe to disclose them (subscriber article; the later part is not public).","kImp":"근접사고 보고서와 회의록 양식에 '사실·결정·근거·미결 사항·작성자 해석'을 나누어 적게 하고, 제출 건수보다 내용의 구체성을 피드백하는 방식으로 바꿔 볼 만하다.","eImp":"Near-miss report and meeting-minute templates could ask writers to separate facts, decisions, rationale, open items and personal interpretation, with feedback focused on specificity rather than submission counts.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=114&bi_pidx=39677","prio":2,"mar":false,"tags":["AI","PS","SPEAK"]},{"code":"CHANGE","date":"2026-10-21","src":"Harvard Business Review","title":"HBR \"막기만 하는 보안 규정은 역효과\" — 6개 실험·2,800명 \"강요된 통제가 위험 인식을 낮춘다\"","eTitle":"When Restrictive Cybersecurity Policies Backfire","kSum":"듀크대 푸쿠아 경영대학원의 애런 케이 교수와 보안업체 Nudge Security 공동창업자 등은 2,800명 이상이 참여한 6개 실험에서, 강요된 사이버보안 통제가 반발심을 불러 직원들이 디지털 위협을 덜 심각하게 여기게 만든다는 결과를 얻었다. 제한을 풀면 원래 위험이 과장됐다는 신호로 읽히는 문제도 확인됐다. 필자들은 생성형 AI 같은 유용한 앱은 금지해도 사용이 멈추지 않고 눈에 덜 띄게 계속된다고 지적한다. 이들은 보안 요건 안에서 의미 있는 선택권을 남기고, 쓸 만한 승인 도구를 제공하며, 위험과 정책 변경 이유를 설명하고, 준수율과 함께 직원의 위험 인식도 측정하라고 권한다.","eSum":"In six experiments with more than 2,800 participants, Duke Fuqua professor Aaron Kay and co-authors including the co-founder of security firm Nudge Security found that imposed cybersecurity controls can provoke resistance that leads employees to downplay digital threats. Lifting restrictions can also signal that the original danger was exaggerated. The authors note that useful tools such as generative AI apps are not abandoned when banned; employees often keep using them less visibly. They recommend preserving meaningful choice within security requirements, providing useful approved tools, explaining risks and the reasons for policy changes, and measuring employees' beliefs alongside compliance.","kImp":"선상 USB·개인기기·AI 앱 사용을 일괄 금지만 하면 선원들이 위험을 가볍게 여기고 눈에 띄지 않게 우회할 수 있다. 사이버 보안 절차를 개정할 때 제한 이유와 승인된 대안 도구를 함께 안내하고, 선박 방문 때 준수 여부뿐 아니라 선원이 위험을 어떻게 인식하는지도 물어볼 만하다.","eImp":"Blanket bans on USB sticks, personal devices or AI apps on board can lead crews to downplay the risk and work around the rules out of sight. When revising shipboard cyber procedures, explain why each restriction exists and offer approved alternatives, and on ship visits ask how crews perceive the risk, not just whether they comply.","url":"https://hbr.org/2026/10/when-restrictive-cybersecurity-policies-backfire","prio":2,"mar":false,"tags":["CHG","WR"]},{"code":"CHANGE","date":"2026-10-15","src":"HR Dive","title":"리더 17%만 '변화 대응에 자신 있다' — DDI 글로벌 리더십 전망 2027(리더 1만1천여 명)","eTitle":"Leaders say they are worried about their ability to handle change","kSum":"컨설팅사 DDI가 리더 1만1,000명 이상과 HR 전문가 약 2,500명의 응답을 분석한 '글로벌 리더십 전망 2027'에서 변화를 예측하고 대응하는 데 자신 있다는 리더는 17%에 그쳤고, 자신감이 없는 리더는 차질 속에서 생산성을 유지할 가능성이 3분의 1 수준이었다. 불안한 리더는 확실한 이직 의향을 밝힐 가능성이 5.1배 높았고, 완전히 몰입한 리더는 9%뿐이었지만 이들은 팀의 최고 역량을 끌어낼 가능성이 8.8배 높았다. 리더 81%가 AI의 생산성 향상을 꼽으면서도 신기술 활용에 준비됐다는 응답은 14%였고, 고위 경영진을 신뢰하는 실무자는 21%에 그쳤다. DDI CEO 테이시 바이엄은 변화 속도를 늦출 수 없으니 변화를 이끄는 리더에게 성과를 내면서 역량을 쌓을 시간과 여력을 주라고 권했다.","eSum":"DDI's Global Leadership Forecast 2027, based on more than 11,000 leader responses and about 2,500 HR professionals, found only 17% of leaders feel confident anticipating and reacting to change, and those lacking that confidence were one-third as likely to stay productive during setbacks. Anxious leaders were 5.1 times more likely to report a definite intention to leave, and just 9% were fully engaged, although those who were proved 8.8 times more likely to regularly bring out the best in their teams. While 81% of leaders cited AI productivity gains, only 14% felt ready to use emerging technologies, and only 21% of individual contributors trust senior leadership. DDI CEO Tacy Byham urged organizations to give leaders driving change the time and capacity to build skills while still delivering results.","kImp":"새 규제·연료·디지털 시스템이 한꺼번에 들어오는 시기에 선장·기관장과 육상 감독이 변화 대응에 자신이 없으면 피로와 이직으로 이어질 수 있다. 사관 회의에서 다가올 변화의 일정과 필요한 역량을 미리 짚어 주고, 변화를 맡은 감독에게 교육 시간을 실제로 떼어 줄 만하다.","eImp":"With new regulations, fuels and digital systems arriving at once, masters, chief engineers and shore superintendents who feel unready for change are at risk of burnout and leaving. Use officers' meetings to preview upcoming changes and the skills they will demand, and give superintendents who lead change protected time for their own training.","url":"https://www.hrdive.com/news/leaders-say-they-are-worried-about-their-ability-to-handle-change/833077/","prio":3,"mar":false,"tags":["CHG","FL","AI"]},{"code":"CHANGE","date":"2026-10-15","src":"Harvard Business Review","title":"HBR \"동료 대신 AI에 물으면 팀 신뢰·조정력 약해진다\" — 'relationslipping' 연구","eTitle":"Team Dynamics Weaken When Employees Turn to AI Instead of Colleagues","kSum":"코칭 플랫폼 BetterUp 연구진과 제프리 핸콕 스탠퍼드대 교수는 AI 사용이 동료가 고유한 전문지식을 가졌다는 인식은 높였지만, AI를 '팀원'처럼 대하면 팀원 사이의 신뢰와 조정 능력이 떨어졌다고 보고했다. 연구진은 구성원이 서로 대신 AI를 쓰면서 업무 관계가 서서히 약해지는 현상을 'relationslipping'이라 불렀다. 원인은 두 가지로, 빠른 AI 답을 얻느라 대화를 건너뛰면 '누가 무엇을 아는지'에 대한 팀의 지도가 갱신되지 않고, 동료가 일을 AI에 넘기면 그 사람의 판단 과정이 보이지 않게 된다. HBR 편집자 뉴스레터(10월 20일)는 이 연구가 미국 근로자 1,000명 이상 설문에 기반한다고 소개했다.","eSum":"Researchers from coaching platform BetterUp and Stanford professor Jeffrey Hancock report that AI use raised teammates' sense that colleagues hold unique expertise, but treating AI as a teammate eroded trust and coordination among team members. They call this 'relationslipping', the gradual weakening of a team's working relationships as members substitute AI for each other. Two mechanisms drive it: skipping conversations for quick AI answers stops people updating their map of who knows what, and offloading work to AI makes colleagues' reasoning harder to see. An HBR editor's newsletter on October 20 said the work draws on a survey of more than 1,000 U.S. workers.","kImp":"선교·기관실에서 AI와 디지털 도구로 답을 찾는 일이 늘수록 당직 인계와 브리핑에서 '누가 무엇을 알고 왜 그렇게 판단했는지'를 말로 나누는 시간이 줄 수 있다. BRM·ERM 교육과 출항 전 브리핑에 도구가 낸 답의 근거를 소리 내어 설명하는 순서를 넣어 볼 만하다.","eImp":"As bridge and engine-room teams lean on AI and digital tools for answers, handovers and briefings may lose the spoken exchange of who knows what and why a call was made. Add a step to BRM/ERM training and pre-departure briefings where officers explain aloud the reasoning behind any tool-generated answer.","url":"https://hbr.org/2026/10/team-dynamics-weaken-when-employees-turn-to-ai-instead-of-colleagues","prio":2,"mar":false,"tags":["AI","BRM"]},{"code":"CHANGE","date":"2026-09-16","src":"SHRM","title":"SHRM \"변화 속에서 신뢰를 주는 리더 행동 9가지\" — 이유 설명, 답이 없어도 정기 공유, 같은 규칙 따르기","eTitle":"9 Leadership Behaviors That Inspire Confidence During Change","kSum":"SHRM 인도판은 성장과 디지털 전환기에 직원이 변화를 믿고 따르게 만드는 리더 행동 9가지를 제시했다. 직원 관점에서 변화 이유 설명, 모든 답이 없어도 정기적으로 업데이트, 우려를 듣고 솔직하게 답하기, 목표와 일정에 현실적 기대치 설정, 중간 관리자가 수시로 안내·지원하도록 준비시키기, 잘 적응한 직원 인정, 새 기술 학습 기회 제공, 일관된 결정과 근거 설명, 리더 스스로 같은 규칙 따르기다. 어려운 대화를 피하지 않고 과제를 인정하며 현실적인 계획을 내놓는 리더가 직원의 신뢰를 얻을 가능성이 높다고 강조했다.","eSum":"SHRM India lists nine leader behaviors that help employees feel confident during growth and digital transformation: explaining the reasons for change from employees' perspective, giving regular updates even without all the answers, listening to concerns and answering honestly, setting realistic expectations for goals and timelines, equipping managers to give frequent guidance, recognizing people who adapt, offering chances to learn new skills, making consistent decisions with explained reasoning, and following the same rules as everyone else. Leaders who name challenges and present realistic plans, rather than avoiding difficult conversations, are more likely to win employees' trust.","kImp":"새 절차나 시스템을 선대에 도입할 때 회람 한 장으로 끝내지 말고 '왜 바꾸는지'를 선원 입장에서 설명하고, 아직 정해지지 않은 부분도 정해진 주기로 알려 주는 것이 정착을 돕는다. 육상 담당자부터 새 절차를 똑같이 지키는지 점검하는 것도 신뢰를 얻는 조건이다.","eImp":"When rolling out a new procedure or system across the fleet, go beyond a single circular: explain from the crew's point of view why it is changing and give updates on a fixed rhythm, even on open questions. Checking that shore staff follow the new procedure themselves is part of earning trust.","url":"https://www.shrm.org/in/topics-tools/news/blogs/leadership-behaviors-inspiring-confidence-change","prio":1,"mar":false,"tags":["CHG","FL"]}]},{"code":"ENGAGE","kTitle":"직원 참여·웰빙·인재 유지","eTitle":"Engagement, wellbeing and retention","items":[{"code":"ENGAGE","date":"2026-10-27","src":"Splash247","title":"크루즈선사 한 사관 그룹 이직률 30%의 원인은 급여가 아닌 '보이지 않는 승진 경로' — 화물선 크루잉이 배울 점","eTitle":"A Cruise Operator Traced 30% Turnover in One Officer Group to Unclear Promotion Paths, Not Pay: Lessons for Cargo Crewing","kSum":"PitchFrame 창업자 Raal Harris가 마닐라 Crew Connect Global에서 쓴 Splash247 기고에 따르면, Holland America Line·Seabourn(직원 약 16,000명)은 한 사관 그룹의 이직률이 약 30%에 이르자 처음엔 급여를 의심했으나 인력 데이터를 보니 승진 경로가 보이지 않는 병목이 주원인이었고, 이를 손보자 이직이 줄었다. ATPI는 최근 중동 위기 때 크루즈 선원 수천 명을 며칠 만에 이동시켰지만 일부 화물선 선원 이동은 몇 주가 걸렸는데, 차이는 기술이 아니라 여행자·서류·경로·대안 정보를 함께 쓰는 연결된 프로세스였다. 기고는 채용·역량·교육·진급·배치·유지 데이터를 연결하고, 교육 이수가 아니라 진급 준비도를 추적하며, 매닝 에이전트를 선원 경력 개발 책임을 나누는 인재 파트너로 대하라고 권했다.","eSum":"In a Splash247 guest column from Crew Connect Global in Manila, PitchFrame founder Raal Harris reports that Holland America Line and Seabourn, with about 16,000 staff, saw turnover of about 30% in one officer group and first assumed pay was to blame, but workforce data showed a career-progression bottleneck, and fixing it reduced turnover. ATPI moved several thousand cruise crew out of the recent Middle East crisis within days while some cargo crew movements took weeks, a gap attributed to connected processes rather than technology. The column urges cargo operators to connect recruitment, competence, training, progression, deployment and retention data, track promotion readiness rather than training completion, and treat manning agents as talent partners.","kImp":"사관 퇴직 면담·하선 설문에 '다음 진급까지의 경로가 보이는가'를 묻는 문항을 넣고, 교육 이수율과 별도로 진급 준비도 현황을 관리해 볼 만하다.","eImp":"Add a question on whether officers can see their route to the next promotion to exit interviews and sign-off surveys, and track promotion readiness separately from training completion.","url":"https://splash247.com/what-cargo-shipping-can-learn-from-cruise-about-crewing-technology/","prio":2,"mar":true,"tags":["RET","TRN"]},{"code":"ENGAGE","date":"2026-10-26","src":"The Mission to Seafarers","title":"선원 행복지수 3분기 연속 하락해 6.81 — 상륙 5.46 최저·연결성 최대 낙폭, '선상 동료애가 육상 지원 공백을 가린다'","eTitle":"Seafarers Happiness Index Falls for a Third Straight Quarter to 6.81 as Crew Camaraderie Masks Failing Shore-Side Support","kSum":"The Mission to Seafarers가 Inmarsat·Idwal과 함께 낸 2026년 3분기 선원 행복지수(SHI)는 6.81/10으로 2분기 6.87, 2025년 말 7.26에서 3분기 연속 떨어졌다. 10개 항목 중 6개가 하락했는데 상륙(5.72→5.46)이 가장 낮고 연결성(7.46→6.89)이 가장 크게 떨어졌으며, 동료 선원과의 관계(7.70)가 최고점이었다. 짧아진 항만 체류·원격 터미널·보안 제한·최소 승무로 상륙이 줄고 기항이 항해 중 업무 강도가 가장 높은 구간이 됐으며, 4개 계약 연속 상륙을 못 했다는 응답도 있었다. 보고서는 선상의 끈끈한 관계가 육상 측 지원 실패를 가려 '괜찮은 상태'로 오인될 수 있다고 경고했다.","eSum":"The Mission to Seafarers' Q3 2026 Seafarers Happiness Index, produced with Inmarsat and Idwal, fell to 6.81/10 from 6.87 in Q2 and 7.26 at the end of 2025, a third consecutive quarterly decline. Six of ten measures fell: shore leave was lowest (5.72 to 5.46) and connectivity dropped most (7.46 to 6.89), while interaction with fellow crew scored highest at 7.70. Shorter port stays, remote terminals, security restrictions and minimum crewing are eroding shore leave, port calls have become the most intense part of the voyage, and one respondent had no shore leave across four consecutive contracts. The report warns that strong onboard cohesion is masking failures ashore and could be mistaken for acceptable conditions.","kImp":"선박 방문·사관 회의에서 '분위기가 좋다'는 답에 안주하지 말고 상륙 횟수, 기항 중 업무 부하, 가족 연락 비용 같은 육상 측 지원 지표를 따로 묻고 추적해 볼 만하다.","eImp":"On ship visits and at officers' conferences, do not read good crew camaraderie as a sign that all is well; ask about and track shore-side support indicators such as shore leave taken, workload during port calls and the cost of calling home.","url":"https://www.missiontoseafarers.org/news/seafarer-happiness-slips-as-crews-camaraderie-props-up-failing-shore-side-support","prio":3,"mar":true,"tags":["WELL","ENG"]},{"code":"ENGAGE","date":"2026-10-23","src":"Safety4Sea","title":"여성 선원 채용, '기회 균등'에서 '측정 가능한 행동'으로 — 선원 21만1,750명 중 여성 1%, V.Group 사관후보생 여성 6%→2030년 20% 목표","eTitle":"Recruiting Women at Sea Must Move From Equal Opportunity to Measurable Action, With Women Still About 1% of Seafarers","kSum":"Safety4Sea 분석에 따르면 IMO–WISTA 2024 조사에서 179개 기관 선원 211,750명 중 여성은 2,223명(약 1%)이었고, Maersk 2024년 해상 인력의 여성 비율은 약 6%였지만 고급사관 1%·초급사관 3%·사관후보생 21%·부원 4%로 직급이 오를수록 줄었다. V.Group은 V.Cadets 풀의 여성 비율이 6%로 2030년 20%가 목표이고, Anglo-Eastern의 여성 지원자는 348명(2022)→530명(2023)→811명(2024)으로 늘었다. 기사는 남성적 표현의 채용 공고와 비구조화 면접을 장벽으로 꼽고, 실습 선석(training berth) 없는 채용 캠페인은 관심을 경력으로 이어 주지 못한다며 지원·서류 통과·채용 비율, 실습 선석 배정과 사관 진급 추적, 직급·부서별 결과 공개, 역량 기반 구조화 면접을 권했다.","eSum":"A Safety4Sea analysis notes that the IMO-WISTA 2024 survey counted 2,223 women among 211,750 seafarers at 179 organisations, about 1%, and that women were about 6% of Maersk's 2024 seafaring workforce but only 1% of senior officers, 3% of junior officers, 21% of cadets and 4% of ratings. V.Group reports women at 6% of its V.Cadets pool against a 20% target for 2030, and Anglo-Eastern's applications from women rose from 348 in 2022 to 530 in 2023 and 811 in 2024. The article identifies masculine job adverts and unstructured interviews as barriers, warns that campaigns without training berths cannot turn interest into careers, and recommends tracking application, shortlisting and appointment rates, cadet berth allocation and progression to officer, reporting by rank and department, and structured competency-based interviews.","kImp":"여성 선원 현황을 전체 비율 하나가 아니라 직급·부서별로 나눠 보고, 사관후보생 실습 선석 배정부터 사관 진급까지 어디서 이탈이 생기는지 추적해 볼 만하다.","eImp":"Report female representation by rank and department rather than as one overall figure, and track where women drop out between cadet berth allocation and promotion to officer.","url":"https://safety4sea.com/cm-recruiting-women-at-sea-from-equal-opportunity-to-measurable-action/","prio":2,"mar":true,"tags":["DI","RET"]},{"code":"ENGAGE","date":"2026-10-21","src":"Ship Management International","title":"Columbia Group, 마닐라서 2회 She Beyond 개최 — '여성 선원은 채용만큼 유지·진급이 중요', 여성 사관후보생 멘토링 운영","eTitle":"Columbia Group Holds Its Second She Beyond Conference, Calling for Equal Focus on Retaining and Promoting Women at Sea","kSum":"Columbia Group은 Crew Connect Global 기간 마닐라에서 여성 선원을 위한 2회 She Beyond 콘퍼런스를 열었다. Claudia Paschkewitz 지속가능성·포용·다양성 이사는 IMO–WISTA 조사(2025년 5월)에서 여성이 선원의 1%라며 '얼마나 많은 여성이 들어오는지를 넘어' 지원·진급·고위직 도달 여부를 봐야 한다고 했고, Simoma Toma 해사 HR 책임자는 '여성 사관후보생이 첫 배에 오른다고 회사 책임이 끝나지 않는다'고 말했다. 회사는 경험 많은 멘토와 짝을 지어 주는 여성 사관후보생 멘토링 프로그램, 여성 선원용 iCare 팩, 진급 프로그램을 운영한다고 밝혔다.","eSum":"Columbia Group held its second She Beyond Conference for women seafarers in Manila during Crew Connect Global. Director of Sustainability, Inclusion and Diversity Claudia Paschkewitz, citing the IMO-WISTA survey finding that women are 1% of seafarers, said the industry must look beyond how many women join to whether they are supported, promoted and able to reach senior roles, and Chief of Maritime HR Simoma Toma said the company's responsibility does not end when a female cadet joins her first vessel. The company cited a Female Cadet Mentorship Programme pairing newcomers with experienced mentors, iCare Packs for women seafarers and career progression programmes.","kImp":"여성 사관후보생·초급사관에게 다른 선박의 경력 선원 멘토를 붙이고, 첫 승선 후 정기 면담으로 유지·진급의 장애 요인을 확인해 볼 만하다.","eImp":"Pair female cadets and junior officers with experienced mentors serving on other ships, and hold regular follow-up conversations after the first contract to identify barriers to retention and promotion.","url":"https://www.shipmanagementinternational.com/news/columbia-group-calls-for-greater-focus-on-retaining-women-at-sea-as-second-she-beyond-conference-takes-place","prio":1,"mar":true,"tags":["DI","RET"]},{"code":"ENGAGE","date":"2026-10-20","src":"Safety4Sea","title":"WISTA Germany·Frauen zur See, 여성 선원 채용·승선 통합 모범 가이드 — '한 배에 가능하면 2명 이상', 무관용 정책, 몸에 맞는 PPE·구명설비","eTitle":"WISTA Germany and Frauen zur See Publish a Best Practice Guide for Recruiting and Integrating Women on Board","kSum":"WISTA Germany와 Frauen zur See가 선주·선박관리사·크루잉 부서·해사 교육기관용 'Best Practice Guide for the Recruitment and Integration of Women on Board'를 냈다. 가이드는 승선 전 브리핑과 선상·육상 지정 연락 담당자, 가능하면 한 번에 여성 2명 이상 승선, 무관용 정책과 육상·익명 경로를 포함한 비밀 신고 채널, 독립 조사와 보복 방지, 상급 사관·육상 관리자의 책임을 권고했다. 또 승선 전 보호복·장갑·안전화 치수 확인과 구명조끼·이머전 수트·소방장비 적합성 검토, 투명한 진급 기준·구조화된 멘토링·육아휴직·경력 단절 후 복귀 지원, 선종·직급별 여성 비율·유지·진급 모니터링과 익명 설문·퇴직 면담을 제시했다.","eSum":"WISTA Germany and Frauen zur See have published a Best Practice Guide for the Recruitment and Integration of Women on Board for shipowners, ship managers, crewing departments and maritime education institutions. It recommends pre-embarkation briefings with designated contacts on board and ashore, at least two women serving at the same time where possible, zero-tolerance policies, confidential reporting channels including shore-based and anonymous options, independent investigations with safeguards against retaliation, and accountability for senior officers and shore management. It also calls for correctly sized PPE and a review of the fit of lifejackets, immersion suits and firefighting equipment, transparent promotion criteria, structured mentoring, parental leave and return-to-sea support, and monitoring of female representation, retention and promotion through anonymous surveys and exit interviews.","kImp":"여성 선원 배치 전에 보호구·이머전 수트 치수와 선상·육상 연락 담당자를 점검표로 확인하고, 괴롭힘 신고 경로에 선상 지휘계통을 거치지 않는 육상 직통 채널이 있는지 점검해 볼 만하다.","eImp":"Before assigning women seafarers, confirm PPE and immersion suit sizes and designated onboard and shore contacts with a checklist, and check that harassment reporting includes a direct shore channel that bypasses the onboard chain of command.","url":"https://safety4sea.com/wista-germany-issues-new-guidance-to-improve-integration-of-women-at-sea/","prio":3,"mar":true,"tags":["DI","RET"]},{"code":"ENGAGE","date":"2026-10-19","src":"Ship Management International","title":"Danica Crewing '유지만이 아니라 교대 자체를 관리하라' — 절차 연 1회 정리, 직무 중심 숙지 교육, 장비 표준화","eTitle":"Danica Urges Owners to Manage Crew Turnover, Not Just Retention, by Pruning Procedures and Focusing Familiarisation","kSum":"Danica Crewing Specialists의 Henrik Jensen은 선박·장비·동료를 잘 아는 숙련 선원이 실수를 덜 한다며, 피할 수 없는 이직을 막는 데만 매달리지 말고 선원 교대 자체를 관리해야 한다고 말했다. 그는 급여·보너스·연금·진급 같은 전통적 유지 수단은 안정을 중시하던 세대에 맞춰진 것이고 젊은 선원은 만족해도 옮길 의향이 크다고 지적했다. 사고가 날 때마다 절차·체크리스트가 쌓여 신규 승선자가 소화할 양이 지나치게 많아졌다며, 안전·품질 관리 절차를 최소 연 1회 검토해 낡거나 불필요한 요구를 걷어내고 숙지 교육은 각자 직무에 맞는 실무 지침에 집중하며, 제조사마다 다른 ECDIS 같은 장비 차이를 줄이는 표준화를 권했다.","eSum":"Henrik Jensen of Danica Crewing Specialists argues that crew turnover deserves as much attention as retention, because experienced crews who know the ship, its equipment and each other are less likely to make mistakes and some turnover is unavoidable. He says traditional retention tools such as pay, bonuses, pensions and promotion were designed for generations who valued stability, while younger seafarers move more readily even when satisfied. Because procedures and checklists pile up after incidents and overwhelm new joiners, he recommends reviewing safety and quality procedures at least annually to remove outdated requirements, focusing familiarisation on the instructions relevant to each role, and more standardisation of equipment such as ECDIS.","kImp":"사고 후 덧붙은 절차·체크리스트를 연 1회 '빼기' 관점으로 검토하고, 신규 승선자 숙지 교육을 직무별 핵심 지침 중심으로 줄여 보는 것을 검토할 만하다.","eImp":"Review procedures and checklists added after incidents once a year with a view to removing what is no longer needed, and trim new-joiner familiarisation to the key instructions for each role.","url":"https://www.shipmanagementinternational.com/news/yt746p3s4dt6p9w-gmheg-8s45g-7asjj-y7fx3-5pe7d-8ym47-j64jf-pwhbj","prio":2,"mar":true,"tags":["RET","WR"]},{"code":"ENGAGE","date":"2026-10-13","src":"Safety4Sea","title":"'제공된 복지가 곧 쓸 수 있는 복지는 아니다' — 호주 항만 선원 설문서 응답자 27% 상륙 못 해, 복지를 '제공·접근·이용·경험·결과'로 평가","eTitle":"Available Does Not Mean Accessible: An AMSA-Released Survey Finds About 27% of Respondents Could Not Go Ashore in Australian Ports","kSum":"AMSA가 공개한 ASWC의 선원 항만복지 설문(호주 항만 방문 선원 436명)에서 해당 문항 응답자 202명 중 55명(약 27%)이 상륙하지 못했고, 이유는 빠른 하역·짧은 체류·검사·선상 업무였으며 교통 부족, 터미널과 항만 출입문 사이 먼 거리, 비용도 장벽이었다(표본이 작아 대표성은 제한적). SEAFiT 2025 선원 설문의 상륙 만족도도 50%에 못 미쳤다. 기사는 복지를 무엇을 제공했는지가 아니라 실제로 쓸 수 있는지로 봐야 한다며 제공·접근·이용·경험·결과의 5단계 평가 틀을 제안하고, 회사에는 상륙 기회를 만들도록 당직·운항 일정을 검토하고 익명 피드백으로 지원이 이해·신뢰되는지 확인하라고 권했다. 2025년 MLC 개정(2027년 12월 발효 예정)은 상륙 조항을 더 강화한다.","eSum":"A Seafarer Port Welfare Survey by ASWC, released by AMSA, of 436 seafarers visiting Australian ports found that 55 of the 202 who answered the question, about 27%, could not go ashore, citing fast cargo operations, short stays, inspections and onboard duties, along with limited transport, long distances to port gates and cost; the article notes the sample is small and not representative. The SEAFiT 2025 crew survey also put shore-leave satisfaction below 50%. The article argues welfare should be judged by whether seafarers can use it, proposes assessing it across provision, access, use, experience and outcome, and urges companies to review watch arrangements and schedules to create shore-leave opportunities and to use anonymous feedback to check whether support is understood and trusted. The 2025 MLC amendments, expected to enter into force in December 2027, further strengthen shore-leave provisions.","kImp":"복지 점검 문항을 '있다/없다'에서 '이번 계약 중 실제로 썼는가'로 바꿔 상륙·인터넷·상담 이용 실적을 묻고, 기항지별로 상륙을 막는 당직·일정 요인을 확인해 볼 만하다.","eImp":"Change welfare checks from 'is it provided' to 'was it actually used this contract', asking about shore leave, internet and counselling use, and identify the watch and schedule factors that block shore leave at each port.","url":"https://safety4sea.com/cm-available-does-not-mean-accessible-the-hidden-gap-in-seafarer-welfare/","prio":2,"mar":true,"tags":["WELL","POL"]},{"code":"ENGAGE","date":"2026-10-09","src":"ITF","title":"ITF, 선원 정신건강·자살 예방 캠페인 'Mind At Sea' 전 세계로 확대 — 검사관이 선박 방문 때 10~15분 웰빙 대화","eTitle":"ITF Takes Its 'Mind At Sea' Seafarer Mental Health and Suicide Prevention Campaign Global, With Inspectors Holding Wellbeing Talks on Ship Visits","kSum":"ITF는 세계 정신건강의 날(10월 10일) 시드니에서 'It's ok not to be ok'를 내건 선원 정신건강·자살 예방 캠페인 Mind At Sea를 전 세계로 넓혀 대륙별 2개국에서 12월 초까지 진행하고 매년 운영한다고 밝혔다. 참여 선박 방문에서 ITF 검사관은 스트레스·피로·수면·고립·도움받을 곳을 주제로 10~15분 비공식 대화를 하고 ITF Seafarers' App·상담전화·복지 서비스를 안내하며, 장기적으로는 모든 검사관의 정례 방문에 정신건강을 넣는 것이 목표다. ITF는 2019년 Yale 대학 연구(선원 1,572명)에서 25%가 우울, 17%가 불안, 20%가 최근 2주 자살 사고 기준에 해당했다며(선별 지표이며 임상 진단은 아님), 선주·정부에 정신건강을 산업안전보건 문제로 다루고 적정 휴식·괴롭힘 방지·전문 지원을 보장하며 모든 단체협약에 자살 사망 보상을 넣으라고 요구했다.","eSum":"The ITF has taken its 'Mind At Sea' mental health and suicide prevention campaign global from World Mental Health Day on 10 October, starting in Sydney under the message 'It's ok not to be ok', covering two countries per continent until early December and planned as an annual campaign. On participating ship visits, ITF inspectors hold informal 10-15 minute conversations on stress, fatigue, sleep, isolation and where to get help, and promote the ITF Seafarers' App, helplines and welfare services, with the longer-term aim of building mental health into all routine inspector visits. Citing a 2019 Yale study of 1,572 seafarers in which 25% screened for depression, 17% for anxiety and 20% for recent suicidal ideation, the ITF urges owners and governments to treat mental health as an occupational safety issue and to include death compensation for suicide in all collective agreements.","kImp":"선박 방문 점검표에 10~15분 웰빙 대화(피로·수면·고립·도움받을 곳)를 넣고, 선원들이 회사 밖 상담 경로를 실제로 알고 있는지 확인해 볼 만하다.","eImp":"Add a 10-15 minute wellbeing conversation on fatigue, sleep, isolation and sources of help to the ship visit checklist, and check that crews actually know the external support channels available to them.","url":"https://www.itfglobal.org/en/news/mind-sea-itf-campaign-protect-seafarers-mental-health-goes-global","prio":2,"mar":true,"tags":["WELL"]},{"code":"ENGAGE","date":"2026-10-08","src":"MarineLink","title":"미 해군 해상수송사령부, 민간 선원 5,500명→6,200명 이상·이직률 15%→7% — 급여 상한 폐지, 부원→항해사 경로, 고참 선원 리더십 교육","eTitle":"US Military Sealift Command Rebuilds Its Civil Service Mariner Workforce to Over 6,200 and Halves Attrition From 15% to 7%","kSum":"MarineLink 인터뷰에서 미 해군 해상수송사령부(MSC) 사령관 Benjamin Nicholson 소장은 민간 선원(CIVMAR)을 약 5,500명에서 6,200명 이상으로 늘리고 이직률을 약 15%에서 7%로 낮췄으며, 일정대로 교대·휴가·교육이 가능하도록 약 9,300명이 목표라고 밝혔다. 초과근무 상한을 포함한 급여 상한을 없애 1년차 평균 3등항해사 연봉이 18만8,000달러 이상(계약 보너스 약 5만8,000달러), 3등기관사가 약 20만9,000달러가 됐고, 필수 교육을 휴가에서 차감하지 않으며 AB가 3등항해사 면허를 따는 경로와 기관부 경로(준비 중), 학자금 상환을 운영한다. 인력을 운항선에 집중하려 17척을 일시 운항 중단했고 고참 선원 대상 1주짜리 사람 관리 과정과 정부 소유선 26척 선원 무선 인터넷을 도입했으며, 그는 '사람들이 함께 일하고 싶어 하는 선장·기관장'을 원한다고 말했다.","eSum":"In a MarineLink interview, Rear Admiral Benjamin Nicholson, Commander of the US Navy's Military Sealift Command, said its civil service mariner workforce has grown from about 5,500 to more than 6,200 and attrition has fallen from about 15% to 7%, with a target of about 9,300 so that mariners can rotate, take leave and train on schedule. Removing pay caps, including the aggregate overtime cap, means first-year third mates average over USD 188,000 plus a signing bonus near USD 58,000 and third engineers almost USD 209,000, while required training no longer counts against leave and an AB-to-mate pathway, a planned engineering pathway and student loan repayment support careers. MSC temporarily took 17 ships offline to concentrate crews, runs week-long people-management programmes for senior mariners and installed crew wireless internet on 26 ships, and Nicholson said he wants 'masters and chief engineers that our people want to work for'.","kImp":"이직 대책을 급여만으로 보지 말고 필수 교육이 휴가를 잠식하지 않는지, 부원에서 사관으로 가는 경로가 있는지, 선장·기관장이 사람 관리 교육을 받는지를 함께 점검해 볼 만하다.","eImp":"Look beyond pay in retention plans and check whether mandatory training eats into leave, whether ratings have a route to officer and whether masters and chief engineers receive people-management training.","url":"https://www.marinelink.com/news/mscs-mariner-math-rebuilding-workforce-543580","prio":2,"mar":true,"tags":["RET","FL"]},{"code":"ENGAGE","date":"2026-10-05","src":"Ship Management International","title":"WellAtSea '웰빙은 인식 캠페인이 아니라 행동 변화로' — 동료 앰배서더 활용, 한 고객사 참여율 약 80%","eTitle":"WellAtSea Says Maritime Must Move Beyond Wellbeing Awareness to Behaviour Change, Using Peer Ambassadors","kSum":"OneCare Group 계열 WellAtSea는 업계가 웰빙 활동을 실제 진전으로 착각할 수 있다며, 선원들은 흡연·수면 부족·운동 부족의 위험을 이미 알고 있으므로 어려운 것은 건강한 습관을 지속시키는 동기·지원·선상 환경이라고 지적했다. 효과적인 프로그램은 개인의 동기, 동료의 영향, 달성 가능한 목표, 충분히 긴 참여 기간을 바탕으로 설계해야 하며, WellAtSea는 웰빙 앰배서더가 동료 참여를 이끌어 건강 행동이 육상이 내려보낸 캠페인이 아니라 선원들 안에서 자라나게 한다고 설명했다. 한 고객사 프로그램은 참여율 약 80%를 기록했고, 한 운영사의 금연 캠페인은 즉시 금연만이 아니라 과정의 진전을 인정했으며, Gisa Paredes 대표는 '정보 제공이 곧 행동 변화라는 가정을 멈춰야 한다', '캠페인을 몇 번 했는지 세는 것으로는 부족하다'고 말했다.","eSum":"WellAtSea, part of OneCare Group, warns that the industry may confuse wellbeing activity with progress, since seafarers already know the risks of smoking, poor sleep and inactivity and the harder task is building the motivation, support and onboard environment to sustain healthier habits. Effective programmes are designed around individual motivation, peer influence, achievable goals and engagement long enough for change to stick, and WellAtSea uses wellbeing ambassadors so that healthy behaviour grows from within the crew rather than appearing as an initiative imposed from shore. One client programme reached around 80% participation and an operator's anti-smoking campaign recognised progress along the way, with Managing Director Gisa Paredes saying 'we need to stop assuming that providing information automatically changes behaviour' and that counting campaigns delivered is no longer enough.","kImp":"웰빙·안전 캠페인 성과를 실시 횟수가 아니라 참여 지속률과 행동 변화로 보고, 선박마다 자원한 선원 앰배서더를 두어 육상 주도 캠페인을 선상 주도로 바꿔 볼 만하다.","eImp":"Measure wellbeing and safety campaigns by sustained participation and behaviour change rather than the number delivered, and appoint volunteer crew ambassadors on each ship so campaigns are led on board rather than from shore.","url":"https://www.shipmanagementinternational.com/news/8b2dh4cw8th922f-lfj5n-lcmpx-nxsw6-57rhl-cln6f-7n9b4-x396p-ztbs9-tpnm8-x6ypj-a5x2l-f34wy-c2kd2-7tpp2-3swad-yzw9t-s2all-k2jnc-nx8h9-j7hsa-78ddw","prio":1,"mar":true,"tags":["WELL","ENG","CHG"]},{"code":"ENGAGE","date":"2026-09-29","src":"Safety4Sea","title":"체계적 문헌고찰 '해상의 심리적 트라우마는 간과된 안전 위험' — 28개 연구 분석, 침입 기억·과각성이 당직·의사결정과 팀 소통을 해친다","eTitle":"Systematic Review Finds Psychological Trauma at Sea Remains an Overlooked Safety Risk","kSum":"Maria Carrera-Arce·Raphael Baumler·Charles Watkins가 International Journal of Environmental Research and Public Health(9월 24일)에 낸 체계적 문헌고찰은 28개 연구를 분석해 해적, 중대 사고, 폭력·성희롱, 선상 자살·사망, 악천후, 장기 고립과 불확실성, 과로·피로·가족과의 분리, 선원 유기를 트라우마 원인으로 정리했다. 트라우마는 PTSD·우울·불안·수면장애로 이어지고 침입 기억·집중력 저하·과각성은 당직과 압박 속 의사결정을, 짜증·위축·갈등은 위급할 때 팀 소통을 해치며, 고통은 도움 요청보다 반복 실수나 평소와 다른 침묵 같은 행동 변화로 먼저 드러날 수 있다. 기사가 인용한 Alandia·Seaways Psychology Services 조사에선 선원 50%가 해상에서 충격적 사건을 겪었고 그중 82%가 업무 수행에 악영향을 받았다고 답했으며, 연구진은 트라우마를 산업안전보건 문제로 다루고 중대 사건 후 대응 절차와 전문 지원·추적 관리를 갖추라고 권고했다.","eSum":"A systematic review of 28 studies by Maria Carrera-Arce, Raphael Baumler and Charles Watkins in the International Journal of Environmental Research and Public Health, published on 24 September, identifies piracy, serious incidents, violence and sexual harassment, suicides and deaths on board, extreme weather, prolonged confinement, chronic overwork, family separation and abandonment as sources of trauma at sea. Trauma is linked to PTSD, depression, anxiety and sleep problems, while intrusive memories, poor concentration and hypervigilance can impair watchkeeping and decisions under pressure and irritability, withdrawal or conflict can undermine crew communication, with distress often appearing first as repeated mistakes or unusual silence. A cited Alandia and Seaways Psychology Services survey found 50% of seafarers had experienced a distressing event at sea and 82% of them said it hurt their job performance, and the authors urge treating trauma as an occupational health and safety issue with post-incident procedures, professional support and follow-up.","kImp":"중대 사고·인명 사고 후 비상대응 절차에 관련 선원의 심리 지원과 몇 주 뒤 추적 면담을 넣고, 사고 조사 인터뷰 때 면담 대상자의 상태부터 살피는 원칙을 정해 둘 만하다.","eImp":"Add psychological support and a follow-up conversation a few weeks later for the crew involved to post-incident emergency response procedures, and make checking an interviewee's welfare the first step in accident investigation interviews.","url":"https://safety4sea.com/psychological-trauma-at-sea-remains-an-overlooked-safety-risk/","prio":2,"mar":true,"tags":["WELL","BRM"]},{"code":"ENGAGE","date":"2026-09-24","src":"Safety4Sea","title":"IUMI, 선체보험 위험평가에 '선원 웰빙 체크리스트' 도입 — 브로커·육상 보험 담당이 작성, 연례 갱신 때 추세 추적","eTitle":"IUMI Puts a Crew Wellbeing Checklist at the Heart of Hull Risk Assessment","kSum":"국제해상보험연맹(IUMI)은 선체·기관(H&M) 보험사가 인적 요소를 위험평가에 반영하도록 전직 선원을 포함한 회원사들이 만든 '선원 웰빙 체크리스트'를 발표했다. 체크리스트는 선원이 아니라 브로커나 피보험자의 육상 보험 담당자가 작성하고 모든 선종·국적·수역에 적용할 수 있으며, 질문의 우선순위·해석·비교는 각 보험사가 정하고, 연례 갱신 협의 때 정기적으로 써서 웰빙 관행의 변화와 추세를 추적해 언더라이팅·위험 모델링·클레임 처리에 활용하도록 했다. IUMI 해양선체위원회 의장 Ilias Tsakiris(American Club 유럽 CEO)는 '선원 웰빙은 선체 위험평가에서 더 큰 자리를 차지해야 한다'면서도 보험사를 복지 검사관으로 만들려는 것은 아니라고 했고, 피로·스트레스·과중 업무·휴식 부족·열악한 생활 여건이 의사결정과 상황 인식을 해친다는 점을 근거로 들었다.","eSum":"The International Union of Marine Insurance has published a Crew Wellbeing Checklist for hull and machinery insurers, developed by members including former seafarers, to bring the human element into risk assessment. It is completed by the broker or the assured's insurance manager ashore rather than by crew, applies to all vessel types, nationalities and waters, leaves insurers to decide how to prioritise and interpret questions, and is meant for use at annual renewals to track changes and trends in wellbeing practices for underwriting, risk modelling and claims handling. Ilias Tsakiris, CEO of the American Club (Europe) and Chair of IUMI's Ocean Hull Committee, said crew wellbeing 'deserves a more prominent place in hull risk assessment' without turning insurers into welfare inspectors, citing the effect of fatigue, stress, excessive workload, inadequate rest and poor living conditions on decision-making and situational awareness.","kImp":"보험 갱신 때 선원 웰빙 관행을 질문받을 것에 대비해 휴식·승무·정신건강 지원·통신 같은 항목의 현황 자료를 육상에서 한 번에 낼 수 있게 정리해 둘 만하다.","eImp":"Prepare shore-side evidence on rest, crewing, mental health support and connectivity that can be provided as one package, in anticipation of insurers asking about crew wellbeing practices at renewal.","url":"https://safety4sea.com/iumi-puts-crew-wellbeing-at-the-heart-of-hull-risk-assessment/","prio":2,"mar":true,"tags":["WELL","POL"]},{"code":"ENGAGE","date":"2026-09-22","src":"HR Insight","title":"HD현대마린솔루션, 협업 점수 낮게 나오자 연 1회 진단 대신 격월 ‘펄스 서베이’ — 결과는 전사 공개, 체인지 리더가 현장 면담으로 원인 확인","eTitle":"HD Hyundai Marine Solution Swaps Annual Culture Surveys for Bimonthly Pulse Surveys, Shares Results Company-Wide and Sends Change Leaders to Ask Why","kSum":"선박 인도 후 기술보증·부품·개조와 친환경·디지털 솔루션을 제공하는 HD현대마린솔루션(국내외 약 1,000명, MZ세대 85% 이상)은 지난해 자체 조직문화 서베이에서 협업 항목 점수가 상대적으로 낮고 부서 간 사일로를 줄여야 한다는 의견이 나오자, 지난해 11월 부임한 대표이사가 '원팀'을 핵심 운영 방향으로 제시했다. 연 단위 진단으로는 인식 변화를 제때 알 수 없어 올해부터 10분 안에 답하는 격월 펄스 서베이(회사생활 자부심, 몰입 방해 요소, 개선 방안을 묻는 주관식 포함)를 운영하며, 결과는 익명 처리해 사내 게시판으로 전사에 공유하고 부문별 결과는 부문장과 체인지 리더(CL)에게 전달해 이전 조사와 비교한다. 점수가 낮아도 숫자만으로 해법을 정하지 않고 CL이 현업 구성원을 직접 만나 이유와 맥락을 확인하며, 3차 조사를 마친 뒤 4차부터는 해외법인 구성원까지 참여를 넓힐 계획이다(구독 기사로 후반부 비공개).","eSum":"HD Hyundai Marine Solution, which provides post-delivery warranty, parts, retrofit, green and digital services and has about 1,000 staff at home and abroad, more than 85% of them millennials or Gen Z, made 'one team' a core operating priority under a chief executive appointed last November after its own culture survey showed relatively low collaboration scores and calls to break down silos. Because annual diagnostics could not track shifts in sentiment in time, it now runs a ten-minute pulse survey every two months, including open questions on pride, obstacles to engagement and improvements, posts anonymised results company-wide and gives divisional results to division heads and change leaders for comparison with earlier rounds. Low scores are not acted on from numbers alone: change leaders meet staff to learn the reasons and context, and after three rounds the survey is being extended to overseas subsidiaries from the fourth (subscriber article; later part not public).","kImp":"연 1회 선상 문화 조사 대신 짧은 격월 펄스 설문을 돌리고, 점수가 낮은 선박은 선박 방문 때 담당자가 선원과 직접 이야기해 이유를 확인한 뒤 결과를 선단 전체에 공유하는 방식을 시험해 볼 만하다.","eImp":"A short bimonthly pulse survey could replace a once-a-year onboard culture survey, with shore staff asking crews directly about low-scoring items during ship visits and sharing the findings fleet-wide.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=114&bi_pidx=39588","prio":1,"mar":true,"tags":["ENG","WR"]},{"code":"ENGAGE","date":"2026-09-18","src":"Safety4Sea","title":"해사 육상직 성별 임금격차 평균 37.9% — 영국 전 산업(13.4%)의 약 3배, 여성은 하위직 60%·본부장·이사급 16%","eTitle":"Equal Pay Day: Maritime's 37.9% Gender Pay Gap Reflects Career Progression, Not Just Wages","kSum":"Safety4Sea는 국제 동일임금의 날(9월 18일)을 맞아 Spinnaker가 Maritime HR Association 임금 조사(2025년, 영국 해사 육상직 2,000여 개)를 분석한 결과 성별 임금격차가 평균 37.91%, 중위 36.46%로 영국 전 산업(평균 13.40%, 중위 12.80%)보다 훨씬 컸다고 전했다. 영국에서 여성은 가장 낮은 직급의 60%를 차지하지만 본부장·이사급은 16%였고, 유럽에서도 하위·수습직 62% 대 최고위직 15%였으며, 전 세계 해사 여성 임원 비율은 11%(2020)에서 17%(2025)로 늘었다. 기사는 보수가 높은 기술·해상·운항·신조 직무로 이어지는 승선 경력에 대한 접근 제한, 긴 승선 기간과 유연성 부족, 출산·가족 문제에 따른 해상-육상 경력 단절을 원인으로 꼽고, 임금 투명성과 함께 승선 진입·운항 경험·해상-육상 이동·리더십 진급의 기회 균등을 주문했다.","eSum":"Marking International Equal Pay Day on 18 September, Safety4Sea reports a Spinnaker analysis of Maritime HR Association salary data for more than 2,000 shore-based UK maritime positions in 2025, showing a mean gender pay gap of 37.91% and a median of 36.46%, against UK all-industry figures of 13.40% and 12.80%. In the UK women hold 60% of the most junior maritime roles but 16% of head or director positions, in Europe 62% of junior or trainee roles but 15% of the most senior, and globally female executive leaders in maritime rose from 11% in 2020 to 17% in 2025. The article attributes the gap to limited access to the seagoing experience that leads to better-paid technical, marine, operational and newbuilding roles, long periods at sea, limited flexibility and broken sea-to-shore careers around family, and calls for pay transparency and equal chances to go to sea, gain operational experience, move ashore and reach leadership.","kImp":"육상 조직의 직급별 성별 구성과 승선 경력 보유 비율을 함께 보고, 육상 여성 직원에게 선박 방문·승선 실습 기회를 주는 경력 경로를 검토해 볼 만하다.","eImp":"Review the gender mix of shore staff by grade alongside the share with seagoing experience, and consider career paths that give women ashore ship visits and sea-time opportunities.","url":"https://safety4sea.com/cm-international-equal-pay-day-what-maritimes-gender-pay-gap-reveals-about-career-progression/","prio":1,"mar":true,"tags":["DI","RET"]},{"code":"ENGAGE","date":"2026-09-15","src":"Safety4Sea","title":"All Aboard Alliance 보고서, 13개사 지속가능 승무 지침 이행 점검 — 전원 익명 제3자 신고창구·11곳 하루 1GB 무료 데이터, 유급 육아휴직은 4곳","eTitle":"All Aboard Alliance Report Shows How 13 Companies Apply the Sustainable Crewing Guidelines, From Anonymous Helplines to Psychological Safety Interventions","kSum":"Global Maritime Forum의 All Aboard Alliance는 2025년 3월 발표한 지속가능 승무 지침(Sustainable Crewing Guidelines)을 이행하는 13개사를 다룬 보고서 'Raising the standard at sea'를 냈다. 13개사 모두 포용 실무 교육, 괴롭힘·따돌림·권한 남용·비위를 신고하는 비밀·익명 제3자 상담창구, 선상 친목 활동 예산을 운영했고 11곳이 선원에게 하루 1GB 이상 무료 데이터를 줬지만, 지침이 권하는 유급 육아휴직은 4곳뿐이었고 유급 배우자 출산휴가는 한 곳도 없었다. 사례로 Höegh Autoliners는 사관·고참 선원에게 고통 징후 인지·대화 시작·도움 연결을 교육하고, Synergy는 자체 플랫폼 Ahoy로 주간 웰빙 체크인을 하며, MISC는 정기 웰빙 모니터링과 심리 상담 연계를 결합하고, Shell은 기존 물리적 안전 개입 정책을 심리적 안전으로 넓혀 부적절한 행동을 보면 개입하도록 시나리오 훈련을 한다.","eSum":"The Global Maritime Forum's All Aboard Alliance report 'Raising the standard at sea' examines 13 companies implementing the Sustainable Crewing Guidelines launched in March 2025. All 13 provide ongoing training on inclusive practices, confidential anonymous third-party helplines for reporting harassment, bullying, abuse of power or misconduct, and budgets for onboard social activities, and 11 give seafarers at least 1 GB of free data a day, but only four offer the recommended paid parental leave and none offer paid paternity leave. Examples include Höegh Autoliners training officers and senior crew to recognise distress, start supportive conversations and direct colleagues to help, Synergy's weekly wellbeing check-ins on its Ahoy platform, MISC combining wellbeing monitoring with access to psychologists, and Shell extending its physical safety intervention policy to psychological safety with scenario-based exercises.","kImp":"작업 중지 권한처럼 '부적절한 언행을 보면 개입한다'는 원칙을 안전 정책에 명시하고, 고참 선원이 고통 징후를 알아보고 대화를 여는 짧은 실습을 사관 회의에 넣어 볼 만하다.","eImp":"State in the safety policy that crew should intervene when they see inappropriate behaviour, in the same way as stop-work authority, and add a short practice session on recognising distress and opening a conversation for senior crew at officers' conferences.","url":"https://safety4sea.com/seafarer-mental-health-companies-focus-on-prevention-and-early-intervention/","prio":3,"mar":true,"tags":["WELL","PS","DI"]},{"code":"ENGAGE","date":"2026-09-15","src":"Safety4Sea","title":"MHSS '선장·1항사·기관장·1기사에 정신건강·자살 예방 교육 의무화를' — 2024년 해상 사망 11%가 자살로 분류","eTitle":"MHSS Calls for Mandatory Mental Health and Suicide Prevention Training for the Four Most Senior Officers Onboard","kSum":"OneCare Group 계열 MHSS는 세계 자살 예방의 날(9월 10일)을 맞아 선장·1등항해사·기관장·1등기관사와 인사 책임이 있는 선원에게 정신건강·자살 예방 교육을 의무화하라고 선사들에 촉구했다. 교육 목표는 고통 징후 인지, 정신건강 대화를 여는 자신감, 전문 지원이 필요한 시점 판단이며, 위기 대응보다 조기 개입, 열린 대화, 선원 중 정신건강 응급처치자 양성을 권했다. 근거로 2024년 해상 사망의 11%가 자살로 분류됐다는 2025 SAFETY4SEA Athens Forum 발표(실종 처리된 사망이 많아 실제는 불확실), 선원 25~30%의 우울·불안 증상 경험, Gard 2026 선원 클레임 보고서의 확인된 선원 자살 8건(2024)→10건(2025)을 들었다. MHSS의 Stella Kiss는 사관이 '심리학자가 될 필요는 없다'며 도움 요청을 진지하게 받고 생명 위험이 있으면 선상 절차대로 선장에게 알리라고 했다.","eSum":"Mental Health Support Solutions (MHSS), part of OneCare Group, used World Suicide Prevention Day on 10 September to urge companies to make mental health and suicide prevention training mandatory for the master, chief officer, chief engineer and second engineer and others responsible for crew. Training should help them recognise signs of distress, feel confident starting conversations and know when to seek professional support, alongside early intervention, open conversation and crew mental health first aiders. MHSS cites a 2025 SAFETY4SEA Athens Forum presentation attributing 11% of deaths at sea in 2024 to suicide, with many other deaths recorded as lost at sea, 25-30% of seafarers reporting depression and anxiety symptoms, and Gard's 2026 Crew Claims Report showing confirmed crew suicides rising from 8 in 2024 to 10 in 2025. Head of Clinical Operations Stella Kiss said officers 'do not need to become psychologists' but must take requests for help seriously and inform the master where life is at risk.","kImp":"상급 사관 4명에게 고통 징후 인지와 대화 시작을 다루는 짧은 실습형 교육을 먼저 제공하고, 선상에서 위험 신호를 들었을 때의 보고·연결 절차를 한 장으로 정리해 둘 만하다.","eImp":"Give the four senior officers priority access to short, practical training on recognising distress and starting conversations, and summarise on one page the onboard steps for reporting and referral when someone discloses risk.","url":"https://safety4sea.com/mhss-suicide-prevention-training-should-be-mandatory/","prio":2,"mar":true,"tags":["WELL","FL","TRN"]},{"code":"ENGAGE","date":"2026-09-03","src":"국제신문","title":"부산중구정신건강복지센터·한국선원복지고용센터, 선원 정신건강·위기개입 협약 — 재난 시 긴급 심리상담, 고위험군 선원 조기 발굴·전문기관 연계","eTitle":"Busan Mental Health Centre and Korea Seafarers' Welfare and Employment Center Sign Pact on Crisis Intervention and Early Identification of At-Risk Seafarers","kSum":"동명대학교가 위탁 운영하는 부산중구정신건강복지센터와 한국선원복지고용센터는 9월 1일 선원 정신건강 증진 지원 체계를 넓히는 업무협약을 맺고 재난 발생 시 선원 대상 심리상담과 위기개입, 고위험군 선원 발굴과 전문기관 연계, 재난 심리지원 프로그램 공동 운영, 심리회복 지원과 정신건강 예방교육, 실무자 협력체계 구축과 정보 교류에 협력하기로 했다. 지이코노미 보도에 따르면 두 기관은 장기간 가족과 떨어져 고립된 생활을 하는 선원들이 높은 직무 스트레스와 우울감을 호소하고 해상 사고를 겪으면 즉각적인 심리 지원이 필요하다는 점을 배경으로 들었으며, 최성진 센터장은 '심리적 적신호가 켜져도 적기 치료를 받기 어려운 구조적 한계가 있었다'고 말했다. 협약을 현장에 바로 쓸 수 있는 긴급 심리 매뉴얼과 예방 프로그램으로 정착시키는 것이 과제로 제시됐고, 기사에 대상 인원이나 상담 건수 같은 수치는 없다.","eSum":"The Busan Jung-gu Mental Health Welfare Centre, run by Tongmyong University, and the Korea Seafarers' Welfare and Employment Center signed an agreement on 1 September to widen mental health support for seafarers, covering counselling and crisis intervention for seafarers after disasters, identifying high-risk seafarers and referring them to specialist services, jointly running disaster psychological support programmes, recovery support and prevention education, and cooperation and information exchange between staff. According to G-Economy, the partners cited seafarers' long separation from family, isolation, high job stress and depressive symptoms and the need for immediate support after accidents at sea, with centre director Choi Seong-jin saying seafarers had faced structural barriers to timely treatment even when warning signs appeared. Turning the pact into ready-to-use emergency psychological manuals and prevention programmes was set as the next step; the reports give no participant or caseload figures.","kImp":"중대 사고나 사망 사고 뒤 선원에게 연결할 외부 심리 지원 기관과 연락 경로를 비상대응 계획에 미리 넣어 두고, 고위험 징후가 보일 때 선장이 쓸 수 있는 연계 절차를 확인해 볼 만하다.","eImp":"Emergency response plans could list external psychological support providers and contact routes for crew after serious or fatal incidents, along with a referral procedure masters can use when warning signs appear.","url":"https://www.kookje.co.kr/news2011/asp/newsbody.asp?key=20260903.99099001053","prio":1,"mar":true,"tags":["WELL"]},{"code":"ENGAGE","date":"2026-08-12","src":"Safety4Sea","title":"영국, 성폭력 피해 선원 지원 전국 교육 프로그램 — 항만복지위원회 15곳·지브롤터서 복지 대응 인력 200~300명 교육, '겪거나 목격' 80% 중 털어놓은 사람은 35%","eTitle":"National UK Programme Supporting Seafarers Affected by Sexual Violence Set to Roll Out Through Port Welfare Committees","kSum":"영국 상선복지위원회(MNWB)는 TK Foundation의 지원을 받아 Safer Waves에 보조금을 주고, 선박 방문자·복지 직원·자원봉사자를 대상으로 트라우마 기반 대응, 보호(safeguarding), 피해 고백 대응, 전문 지원 연계를 가르치는 전국 교육 프로그램을 펼친다. 교육은 우선 MNWB의 영국 내 항만복지위원회 15곳과 지브롤터 국가선원복지위원회를 통해 진행해 복지 대응 인력 200~300명을 교육할 예정이며, 보조금은 Safer Waves의 익명 이메일 상담도 지원한다. Safer Waves의 2025년 보고서 'Sexual Offences at Sea'에서 자발적 응답자의 80%가 해상 성폭력을 겪거나 목격했다고 답했지만 누군가에게 말한 사람은 35%뿐이었고, 공식 신고하거나 처리에 만족한 사람은 더 적었다.","eSum":"The Merchant Navy Welfare Board, with support from The TK Foundation, has awarded Safer Waves a grant to roll out a national programme training ship visitors, welfare staff and volunteers in trauma-informed responses, safeguarding, handling disclosures and signposting seafarers to specialist support. It will be delivered first through the MNWB's 15 Port Welfare Committees across the UK and the National Seafarers' Welfare Board in Gibraltar, with 200 to 300 welfare responders expected to be trained, and the grant also supports Safer Waves' anonymous email service. In Safer Waves' 2025 report 'Sexual Offences at Sea', 80% of self-selected respondents said they had experienced or witnessed sexual violence at sea, but only 35% had spoken to anyone about it, and fewer still had made a formal complaint or felt it was handled satisfactorily.","kImp":"성폭력·괴롭힘 피해를 처음 듣게 될 수 있는 선장·사관·육상 담당자에게 '고백을 받았을 때 하지 말아야 할 말과 연결할 곳'을 다루는 짧은 대응 교육을 마련해 볼 만하다.","eImp":"Give masters, officers and shore staff who may be the first to hear about sexual violence or harassment short training on how to respond to a disclosure, what not to say and where to refer the person.","url":"https://safety4sea.com/national-uk-programme-supporting-seafarers-affected-by-sexual-violence-set-to-roll-out/","prio":1,"mar":true,"tags":["WELL","SPEAK","DI"]},{"code":"ENGAGE","date":"2026-08-03","src":"The Mission to Seafarers","title":"선원 행복지수 2분기 6.87로 하락 — '급성 충격이 만성 긴장으로', 상륙 5.72·업무량 6.20, 여성 6.06 대 남성 7.13","eTitle":"Seafarers Happiness Index Drops to 6.87 in Q2 2026 as 'Acute Shock' Hardens Into 'Chronic Strain'","kSum":"2026년 2분기 선원 행복지수는 6.87/10으로 1분기 7.18에서 떨어졌다. 상륙(5.72)이 가장 낮았고 업무량 관리는 6.20이었으며 동료 관계(7.49)와 연결성(7.46)이 강점으로 남았고, 여성 응답자 평균은 6.06으로 남성(7.13)보다 낮았으며 35~55세의 사기가 가장 낮았다. 6시간 교대 당직·빠른 기항·서류와 점검 부담 속에 휴식시간이 '당국 제출용으로만' 기록된다는 응답이 나왔고, 젊은 선원은 급여를 육상 직장의 전체 조건과 비교하고 있었다. 보고서는 우수 운영사가 하선일을 지키고 교대를 제때 하며 능력 기반 승진을 제공한다고 짚었다.","eSum":"The Q2 2026 Seafarers Happiness Index fell to 6.87/10 from 7.18 in Q1 as the shock of the Persian Gulf conflict settled into everyday strain. Shore leave was lowest at 5.72 and workload management scored 6.20, while crew interaction (7.49) and connectivity (7.46) remained strengths; women averaged 6.06 against 7.13 for men, and those aged 35 to 55 reported the lowest morale. Respondents described six-on, six-off watches, rapid turnarounds and heavy paperwork, with rest hours recorded 'just for authorities and filing', and young crew judging pay against the full package ashore. The report says the best operators respect sign-off dates, ensure timely reliefs and offer merit-based promotion.","kImp":"휴식시간 기록이 실제 휴식과 맞는지 선상 인터뷰로 확인하고, 하선일 준수율과 교대 지연 건수를 인력 유지 지표로 함께 보는 것을 검토할 만하다.","eImp":"Check through onboard interviews whether recorded rest hours match actual rest, and consider tracking on-time sign-offs and delayed reliefs as retention indicators.","url":"https://www.missiontoseafarers.org/news/seafarer-happiness-falls-as-acute-shock-hardens-into-chronic-strain","prio":2,"mar":true,"tags":["WELL","RET"]},{"code":"ENGAGE","date":"2026-07-08","src":"Marine Insight","title":"ISWAN SeafarerHelp 2025 연차 보고 — 정신건강 상담 35.9% 늘어 역대 최고, 계약 위반·임금 체불이 1위(25.4%), 유기 관련 상담 41.2% 증가","eTitle":"ISWAN's SeafarerHelp 2025 Annual Review: Mental Health Contacts Hit a Record, Up 35.9%, as Contract Breaches and Wage Theft Top Seafarers' Concerns","kSum":"NorthStandard 후원으로 나온 ISWAN의 24시간 다국어 선원 상담전화 SeafarerHelp 2025년 연차 보고에 따르면 정신건강 관련 상담은 전년보다 35.9% 늘어(Marine Insight 7/15 보도 기준 382건) 코로나19 선원 교대 위기 정점보다 많은 역대 최고를 기록했다. 계약 위반·임금 체불이 전체 사건의 25.4%로 1위였고 재정·보상 문제(12.5%)를 합치면 약 5분의 2가 경제적 착취 관련이었으며, 유기 관련 상담은 2025년 41.2%, 2022년 이후 158.9% 늘었고, 여성은 남성보다 학대·따돌림·괴롭힘·차별·폭력을 제기할 가능성이 4배 이상 높았다. 신규 상담은 줄었지만 후속 상담이 늘어 문제가 더 복잡하게 얽혀 있었고, 선상 연결성이 좋아지면서 기본 정보는 온라인에서 찾고 상담전화에는 공감·판단·전문 지원을 구하러 연락하는 경향이 나타났다.","eSum":"ISWAN's SeafarerHelp 2025 Annual Review, sponsored by NorthStandard, reports that mental health contacts to its 24-hour multilingual helpline rose 35.9% (382 cases, per a later Marine Insight report), the highest level it has recorded and above the peak of the COVID-19 crew change crisis. Contractual breaches and wage theft were the top concern at 25.4% of cases and, with financial and compensation issues at 12.5%, nearly two-fifths of cases involved economic exploitation, while abandonment-related contacts rose 41.2% in 2025 and 158.9% since 2022, and women were more than four times as likely as men to raise abuse, bullying, harassment, discrimination or violence. New contacts fell but follow-up contacts rose as problems became more complex and interconnected, and better onboard connectivity means many seafarers now find basic information online and call for empathy, judgement or specialist support.","kImp":"선원 고충을 회사 밖 상담전화가 먼저 듣는 경우가 많다는 점을 감안해, 임금 지급·계약 조건 문의를 선원이 불이익 걱정 없이 육상 담당자에게 직접 할 수 있는 경로가 있는지 점검해 볼 만하다.","eImp":"Since external helplines often hear seafarers' grievances first, check that crews have a channel to raise wage and contract questions directly with shore staff without fear of consequences.","url":"https://www.marineinsight.com/4992-seafarers-and-family-members-sought-help-as-life-at-sea-became-more-complex-in-2025/","prio":2,"mar":true,"tags":["WELL","POL"]},{"code":"ENGAGE","date":"2026-10-27","src":"DBR","title":"DBR '韓 기업 권한부여 지수 24점 낙제' — ICSB 사람 중심 기업가정신 지수에서 한국은 기업가정신 2위·인간 번영 26위, 직원 헌신을 끌어내려면 믿고 맡겨야","eTitle":"DBR: Korean Firms Score a Failing 24 on Empowerment - Korea Ranks 2nd for Entrepreneurship but 26th for Human Flourishing in the ICSB Index, and Commitment Requires Trust and Delegation","kSum":"세계중소기업학회(ICSB)가 2026년 발표한 사람 중심 기업가정신 지수(HCE Index)는 GEM 기업가정신 자료와 갤럽 월드폴의 인간 번영 자료를 묶어 43개 경제권을 비교했는데, 한국은 기업가정신 80점(2위)에 비해 인간 번영은 44점(26위, 표본 평균 49.3점)에 그쳤다. 김기찬 ICSB 의장은 DBR 기고에서 격차가 생기는 곳이 권한 부여라며, 일자리와 일할 조건을 갖춰 주는 역량 활성화는 64.1점으로 평균을 웃돌지만 직원을 믿고 판단·선택 권한을 넘기는 권한 부여는 24.1점으로 평균과 격차가 가장 크다고 지적했다. 직원을 관리 비용이나 보상·처벌에만 반응하는 존재로 보는 통제 중심 경영이 원인이라며, 해법은 새 제도가 아니라 사람을 이해하고(Understanding)·투자하고(Investing)·신뢰해 권한을 넘기는(Trusting) 경영자의 'UIT' 행동이라고 제시했다(구독 기사, 공개된 앞부분 기준).","eSum":"The 2026 Human-Centred Entrepreneurship (HCE) Index from the International Council for Small Business (ICSB) combines GEM entrepreneurship data with Gallup World Poll human-flourishing data for 43 economies; Korea scores 80 on entrepreneurship (2nd) but only 44 on human flourishing (26th, below the 49.3 sample average). Writing in DBR, ICSB chair Kim Ki-chan says the gap lies in empowerment: Korea scores an above-average 64.1 on capability enablement, such as creating jobs and working conditions, but only 24.1 on trusting employees with judgement and choices, the widest gap from the average. He blames control-centred management that treats staff as a cost or as responding only to reward and punishment, and calls for leaders to practise 'UIT' - understanding, investing in and trusting people - rather than new schemes (subscriber article; summary based on the free opening section).","kImp":"육상 조직이 선박의 일상 판단을 세세한 승인 절차로 묶어 두고 있지 않은지 점검하고, 선장·기관장에게 맡길 수 있는 결정 범위를 명확히 문서화해 넘기는 것이 선상 책임감과 몰입을 높이는 출발점이 될 수 있다.","eImp":"Shore organisations could check whether routine shipboard decisions are tied up in detailed approval steps, and clearly document the decisions that masters and chief engineers own; delegating that scope is a starting point for stronger ownership and engagement on board.","url":"https://dbr.donga.com/article/view/1203/article_no/12318","prio":2,"mar":false,"tags":["ENG","FL"]},{"code":"ENGAGE","date":"2026-10-27","src":"DBR","title":"DBR '데이터로 팀을 읽는 리더의 기술' — 소진은 협업망을 타고 번진다(직원 1,541명 연구), 리더는 업무가 누구에게 몰리고 어디서 병목이 생기는지 봐야","eTitle":"DBR: Reading Teams Through Data - Burnout Spreads Through Collaboration Networks (a 1,541-Employee Study), So Leaders Should Track Where Work Concentrates and Where Bottlenecks Form","kSum":"피플즈 대표 김문경은 DBR 칼럼에서 목표를 초과 달성한 팀이라도 일부 구성원에게 업무가 몰리거나 과부하로 소진되고 있을 수 있다며, 성과를 받치는 여건이 어디서 흔들리는지 감이 아니라 체계적 진단으로 파악하라고 했다. 근거로 든 네덜란드 흐로닝언대 연구(『Work & Stress』 2026)는 한 조직 직원 1,541명을 두 차례 조사해, 소진된 동료와 함께 일하는 직원일수록 역할이 불분명해지고 업무 갈등이 늘었다고 인식했고 이것이 본인의 소진으로 이어졌으며, 이런 관계는 개별 팀보다 여러 팀이 프로젝트로 연결된 협업망 전체에서 더 뚜렷했다고 밝혔다. 그는 평균 업무시간이 줄어도 여러 부서의 문의를 혼자 처리하는 직원의 부담은 커질 수 있다며, 누가 바쁜지가 아니라 업무가 누구에게 집중되고 어느 단계에서 병목이 생기는지를 데이터로 봐야 한다고 강조했다(구독 기사, 공개된 앞부분 기준).","eSum":"In a DBR column, Peoplez CEO Kim Moon-kyung warns that even a team that beats its targets may have work piled on a few people who are burning out, and urges leaders to find where the conditions behind performance are weakening through systematic diagnosis rather than instinct. He cites a University of Groningen study in Work & Stress (2026) that surveyed 1,541 employees in one organisation twice: staff who worked with burnt-out colleagues reported more role ambiguity and work conflict, which was linked to their own burnout, and the effect was clearer across the whole network of teams linked by projects than within single teams. Average working hours can fall while one person fielding queries from several departments carries more load, he notes, so leaders should look at where work concentrates and where bottlenecks form, not just at who is busy (subscriber article; summary based on the free opening section).","kImp":"선박별 평균 근무시간만 보지 말고 일등항해사·일등기관사처럼 검사 대응·문서·육상 문의가 몰리는 직책의 업무량과 휴식시간을 따로 살펴, 한 사람의 과부하가 다른 사관의 업무 지연과 피로로 번지기 전에 일을 나눌 만하다.","eImp":"Beyond average hours per ship, managers could track workload and rest hours for roles where inspections, paperwork and shore queries pile up, such as the chief officer and the second engineer, and rebalance tasks before one person's overload spreads into delays and fatigue for other officers.","url":"https://dbr.donga.com/article/view/1801/article_no/12307","prio":2,"mar":false,"tags":["WELL","FL","WR"]},{"code":"ENGAGE","date":"2026-10-22","src":"HR Insight","title":"Korea Workplace Index ③ — 10년 조직진단 데이터: 리더십 긍정률 42.6%에 정체, 애착은 66.1%→44.6% 하락…“리더는 만족까지만 데려다준다”","eTitle":"Korea Workplace Index (3): Ten Years of Diagnostic Data Show Leadership Stuck at 42.6% Positive While Attachment Fell From 66.1% to 44.6%","kSum":"HR Insight와 조직건강검진센터·HCM컨설팅&리서치(H2C)가 10년간 축적한 조직건강 진단 데이터를 분석한 연재 3편으로, 긍정 리더십 6요인(진정성·결집·방향제시·공정성·배려와 육성·개방)의 긍정률이 41.2~44.9%(종합 42.6%)에 몰려 뚜렷한 강점이 없고, 10년간 리더십 평가는 제자리인 반면 회사 애착 긍정률은 66.1%에서 44.6%로 떨어졌다. 리더십은 조직만족 개인차의 31.5%를 설명하지만 애착은 14.6%, 탈진은 12.9%만 설명하고, 애착·열의·이직의도·탈진에 대한 영향의 62~85%가 만족을 거쳐 전달돼 '평범한 리더십은 구성원을 만족까지만 데려다준다'고 결론냈다. 애착에는 '배려와 육성'(긍정률 41.2%로 최저)이, 탈진·이직의도에는 기분에 따른 지시·결정 번복 같은 '방향 부재·변덕'이 크게 작용했으며, 파괴적 리더 행동을 자주 목격했다는 응답은 13.5%로 드물지만 그 영향력은 38~59%에 달했다.","eSum":"The third instalment of HR Insight and H2C's Korea Workplace Index, drawing on ten years of organisational health diagnostic data, finds positive ratings for six leadership factors bunched at 41.2-44.9% (42.6% overall) with no clear strength, flat for a decade while positive attachment to the company fell from 66.1% to 44.6%. Leadership explains 31.5% of individual differences in satisfaction but only 14.6% for attachment and 12.9% for burnout, and 62-85% of its effect on attachment, engagement, turnover intention and burnout runs through satisfaction, leading the authors to conclude that ordinary leadership only takes people as far as satisfaction. Care and development, the lowest-rated factor at 41.2%, matters most for attachment, while erratic, mood-driven direction drives burnout and turnover intention; destructive leader behaviour is reported by only 13.5% but carries 38-59% influence.","kImp":"사관 리더십 교육에서 좋은 행동을 더하는 것만큼 드물지만 영향이 큰 부정 행동(결정 번복, 갈등 방치, 독단)을 줄이는 데 초점을 두고, 선상 만족도 조사에 성장 지원과 지시의 예측 가능성을 따로 묻는 문항을 넣어 볼 만하다.","eImp":"Officer leadership training could put as much weight on removing rare but high-impact negative behaviours (reversing decisions, leaving conflict unresolved, coercion) as on adding good ones, and onboard climate surveys could ask separately about growth support and the predictability of instructions.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=114&bi_pidx=39678","prio":3,"mar":false,"tags":["FL","ENG","RET"]},{"code":"ENGAGE","date":"2026-10-19","src":"HR Dive","title":"감시·통제의 '무거운 리더십' 대신 '가벼운 리더십' — Z세대 몰입의 열쇠는 관계와 설명","eTitle":"Leading 'light' may be the key to engaging Gen Z — and everyone else","kSum":"HR Dive의 에밀리 셤웨이 선임기자가 인터뷰한 리더십 개발 전문가 댄 러스트(Infopro Learning 부사장)는 감시와 통제에 기대는 '무거운' 리더십 대신, 깊은 개인적 관계를 맺고 무관심해 보이는 행동을 처벌할 반항이 아니라 이해해야 할 신호로 보는 '가벼운' 리더십을 제안했다. 그는 Z세대의 직설과 무관심은 리더가 만든 문화를 반영하는 것일 수 있으며 '그들은 그저 숨기는 데 서툴 뿐'이라고 말한다. 그는 설명 없는 문화와 전략에 쉽게 동의하지 않는 Z세대의 목적에 대한 질문을 판단 없이 받아 관행을 다시 생각하거나 더 잘 설명하고, 개인 관심사까지 다루는 1:1 대화와 상시 피드백으로 직원 각자의 사연과 동기를 파악하라고 권했다. 직원을 '가족'이라 부르는 것은 경고 신호라고 덧붙였다.","eSum":"In an interview with HR Dive senior editor Emilie Shumway, Dan Rust, vice president of global leadership development at Infopro Learning, contrasts 'heavy' leadership built on surveillance and tight control with 'light' leadership that builds deeper personal connections and treats disengaged behavior as information to understand rather than defiance to punish. He suggests Gen Z's bluntness and disengagement may reflect the culture leaders create: 'I think they're just worse at hiding it.' Because Gen Z resists culture or strategy that is not explained, he advises taking their questions about purpose without judgment and then rethinking or better explaining the practice, holding one-on-ones that cover personal interests, giving continuous feedback and learning each employee's story; calling employees 'family' is a red flag.","kImp":"젊은 선원이 '왜 이렇게 해야 하느냐'고 물을 때 위계로 누르기보다 절차의 이유를 설명하는 것이 이탈을 막는 첫걸음이다. 선장·기관장이 계약 초기에 젊은 선원과 짧은 1:1 대화를 갖고, 되풀이되는 질문은 절차 개선 제안으로 육상에 올려 보낼 만하다.","eImp":"When young seafarers ask 'why do we do it this way?', explaining the reason behind the procedure rather than pulling rank is a first step in keeping them. Have masters and chief engineers hold short one-on-ones with young crew early in each contract, and pass recurring questions ashore as procedure-improvement suggestions.","url":"https://www.hrdive.com/news/leading-light-may-be-the-key-to-engaging-gen-z-and-everyone-else/833373/","prio":1,"mar":false,"tags":["ENG","FL"]},{"code":"ENGAGE","date":"2026-10-06","src":"Harvard Business Review","title":"HBR \"수면 부족은 개인 습관 아닌 리더십 문제\" — 미국 관리자·임원 1,009명 조사","eTitle":"Research: Sleep Deprivation Is a Leadership Problem","kSum":"수면 신경과학자 엘스 반데르헬름(IE 대학 겸임교수)이 미국 관리자·임원 1,009명을 조사한 결과, 리더의 수면 부족은 널리 퍼져 있고 많은 리더가 피로가 자기 성과에 미치는 영향을 과소평가했다. 필자는 문제의 핵심이 개인 습관보다 조직 문화, 즉 리더가 무엇을 용인하고 칭찬하는지에 있으며 이것이 수면을 지키게도 하고 피로를 숨기게도 만든다고 본다. 미 육군과 한 포춘 500 기업 연구에서는 수면을 직접 다루지 않고 리더의 기대와 근무 조건을 바꿔 직원 수면이 개선됐다고 소개하며, 리더 자신의 습관·팀의 피로 징후·조직의 지원 여부를 점검하는 '회복 점검(recovery check)'을 제안한다.","eSum":"Sleep neuroscientist Els van der Helm, an adjunct professor at IE University, surveyed 1,009 U.S. managers and executives and found sleep deprivation widespread, with many leaders underestimating how much fatigue affects their performance. She argues the problem is less about individual habits than workplace culture: what leaders tolerate and praise either protects sleep or teaches people to hide tiredness. Citing work with the U.S. Army and a Fortune 500 company, where changing leadership expectations and working conditions improved sleep without targeting it directly, she proposes a 'recovery check' covering leaders' own habits, fatigue signs in their teams and whether the organization supports rest.","kImp":"밤샘 입출항·하역 뒤에도 '괜찮다'며 버티는 선장·기관장을 칭찬하는 문화는 선상 피로 은폐로 이어진다. 사관 회의에 휴식시간 기록과 실제 피로감을 함께 묻는 '회복 점검' 질문을 넣고, 육상 지원 조직도 항차 계획과 점검 일정이 휴식을 깎고 있지 않은지 함께 살펴볼 만하다.","eImp":"A culture that praises masters and chief engineers for pushing through back-to-back port calls and cargo work teaches crews to hide fatigue. Add recovery-check questions to officers' meetings that compare hours-of-rest records with how tired people actually feel, and have shore teams review whether voyage plans and inspection schedules are eating into rest.","url":"https://hbr.org/2026/10/research-sleep-deprivation-is-a-leadership-problem","prio":2,"mar":false,"tags":["WELL","FL"]},{"code":"ENGAGE","date":"2026-09-22","src":"HR Insight","title":"Korea Workplace Index ② — 몰입층 53.4%→38.5% 급감, 떠나지 않고 ‘침전’한 직원 32.6%… 주니어는 가라앉고 부장급은 떠난다","eTitle":"Korea Workplace Index (2): The Engaged Share Fell From 53.4% to 38.5% as Juniors Withdrew in Place and Senior Managers Moved Toward the Exit","kSum":"H2C 추한규 연구소장이 10년 조직건강 진단 데이터를 시기별로 나눠 보니 몰입권은 2019년까지와 팬데믹기(2020~2021년) 모두 53.4%였다가 2022년 이후 38.5%로 14.9%p 줄었고, 남아 있지만 에너지를 거둔 침전권은 22.3%에서 32.6%로, 떠날 준비를 하는 이탈권은 24.2%에서 28.9%로 늘어 '억눌린 것은 이탈이었지 침전이 아니었다'고 분석했다. 직급별로 대리 이하는 침전권이 12.5%p 늘었고 부장 이상은 이탈권이 7.4%p로 가장 많이 늘었으며, 세 직급 모두 '몰입 소진형'이 10~15%p 줄었다. 저자는 이를 투입(시간·노력·책임)과 보상(인정·성장·다음 자리)의 균형이 깨진 심리적 계약 문제로 보고, '가족 같은 회사'·'주인의식' 같은 호소 대신 주니어에게는 무엇이 몰입하게 하는지 묻고, 중간관리자에게는 성장 경로와 인정을, 시니어에게는 경력 후반 역할을 설계해 주라고 권했다.","eSum":"Splitting ten years of H2C organisational health data by period, research director Choo Han-kyu finds the engaged zone held at 53.4% up to 2019 and through the 2020-2021 pandemic but fell 14.9 points to 38.5% from 2022, while the 'sinking' zone of people who stay but withdraw effort rose from 22.3% to 32.6% and the exit-ready zone from 24.2% to 28.9%. Staff at assistant-manager level and below saw sinking rise by 12.5 points, senior managers saw the largest rise in exit readiness at 7.4 points, and the 'engaged but exhausted' group shrank by 10-15 points at every level. He frames this as a broken psychological contract between input and reward and urges organisations to drop appeals to 'family' and 'ownership' in favour of asking juniors what keeps them engaged, giving mid-level staff clear growth paths and recognition, and designing late-career roles for seniors.","kImp":"해기사 유지 지표를 이직률만으로 보지 말고 초급 사관과 고급 사관을 나눠 몰입 상태를 살피고, 초급 사관에게는 승진 경로와 인정을, 고참 선장·기관장에게는 육상 직무 같은 다음 단계를 보여 주는 경력 면담을 해 볼 만하다.","eImp":"Officer retention could be tracked separately for junior and senior ranks rather than through turnover alone, with career conversations that show junior officers a promotion path and recognition and give senior masters and chief engineers a visible next step such as shore roles.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=114&bi_pidx=39592","prio":2,"mar":false,"tags":["ENG","RET"]},{"code":"ENGAGE","date":"2026-08-25","src":"HR Dive","title":"'일에 필요한 사람에게 닿는다' 21%뿐 — 단절의 시대, 멘토링을 복지 아닌 업무 기능으로","eTitle":"What mentorship looks like in the disconnected era","kSum":"HR Dive가 인용한 어치버스 워크포스 인스티튜트의 '2026 몰입·유지 보고서'에 따르면 일하는 데 필요한 사람에게 접근할 수 있다는 직원은 21%, 회사 소통이 정보를 주고 연결해 준다는 직원은 20%에 그쳤다. 동료와 강하게 연결된 직원은 몰입할 가능성이 4.7배, 일에서 의미를 찾을 가능성이 3.3배 높았고, 성장 기회가 없다고 느끼는 직원의 77%는 다음 자리를 찾고 있었다. 건설 사업관리 회사 그룹 PMX는 체크리스트식 공식 프로그램을 접고 멘토 1명에 멘티 2~3명을 붙여 월 1회 만남만 정해 둔 유연한 방식으로 바꿨다. 기사는 멘토링을 복지가 아닌 업무 기능으로 운영하고, 관리자가 당연히 멘토가 될 것이라고 가정하지 말라고 조언한다.","eSum":"Achievers Workforce Institute's 2026 Engagement and Retention Report, cited by HR Dive, found only 21% of employees can access the people they need to be productive and 20% feel company communications keep them informed and connected. Employees with strong peer connections were 4.7 times more likely to be engaged and 3.3 times more likely to find work meaningful, while 77% of those who see no room for growth are looking for what is next. Construction project manager Group PMX dropped a box-checking formal program in favor of pairing one mentor with two or three mentees and requiring just one meeting a month. The piece advises running mentoring as a business function and not assuming managers will be default mentors.","kImp":"실습 사관과 신임 사관에게 직속 상급자가 아닌 다른 선박이나 육상의 선배 멘토를 이어 주면 승선 중 고립감을 덜고 이른 경력 이탈을 줄이는 데 도움이 될 수 있다. 형식적 체크리스트 대신 월 1회 짧은 원격 대화 같은 가벼운 방식부터 시작해 볼 만하다.","eImp":"Pairing cadets and new officers with a mentor outside their direct chain of command, on another ship or ashore, can ease isolation at sea and reduce early career drop-out. Start light, for example with one short remote conversation a month, rather than a box-ticking checklist.","url":"https://www.hrdive.com/news/what-mentorship-looks-like-in-the-disconnected-era/828651/","prio":2,"mar":false,"tags":["ENG","TRN","RET"]},{"code":"ENGAGE","date":"2026-08-24","src":"HR Insight","title":"Korea Workplace Index ① — 1만 1,869명 10년 데이터: 정서적 몰입 66.1%→44.6%, 이직률·번아웃 지표에 안 잡히는 ‘조용한 침전형’ 28.0%","eTitle":"Korea Workplace Index (1): Ten Years of Data on 11,869 Employees Show Emotional Commitment Falling From 66.1% to 44.6% and a 28% 'Quiet Sinking' Group Invisible to Turnover Metrics","kSum":"HR Insight와 H2C가 2016년부터 10년간 국내 기업 임직원 1만 1,869명의 조직건강 진단(140여 문항)을 분석한 결과 조직만족 긍정률은 2016년 39.6%에서 2025년 38.6%로 제자리였지만 정서적 몰입은 66.1%에서 44.6%로 21.5%p 떨어져 다섯 지표 중 가장 크게 하락했고, '회사의 성공이 곧 나의 성공' 문항은 85.6%에서 48.6%로 낮아졌다. 군집분석으로 나눈 다섯 유형 가운데 만족·몰입·열의는 평균보다 낮지만 탈진과 이직 의도는 강하지 않은 '조용한 침전형'이 28.0%로 이직률이나 번아웃 지표에 잡히지 않는 사각지대로 제시됐고, '완전 이탈형'(7.8%)은 89.3%가 떠나고 싶다고 답했다. 같은 '지친' 집단이라도 몰입 소진형의 이직 의도는 16.1%, 소진된 이탈 대기형은 70.7%로 갈렸는데, 둘을 가른 것은 탈진 정도가 아니라 조직에 대한 만족과 연결감이었다.","eSum":"HR Insight and H2C analysed organisational health diagnostics of 11,869 Korean company employees answering some 140 items since 2016: satisfaction was flat at 39.6% in 2016 and 38.6% in 2025, but emotional commitment fell 21.5 points from 66.1% to 44.6%, the steepest drop of five indicators, and agreement that 'the company's success is my success' fell from 85.6% to 48.6%. Cluster analysis identified a 'quiet sinking' type of 28.0% with below-average satisfaction, commitment and engagement but no strong burnout or intention to quit, a blind spot for turnover and burnout metrics, while 89.3% of the fully disengaged type (7.8%) wanted to leave. Among exhausted employees, turnover intention was 16.1% for the engaged-but-exhausted and 70.7% for the exhausted exit-ready, separated not by the level of burnout but by satisfaction with and connection to the organisation.","kImp":"선원 유지 관리를 재고용률·이직률만으로 보지 말고, 하선 면담에 몰입과 회사와의 연결감을 묻는 짧은 문항을 넣어 '조용히 가라앉은' 인원을 찾아볼 만하다.","eImp":"Seafarer retention could be tracked beyond rehire and turnover rates by adding short questions on commitment and connection to the company to sign-off debriefs, to find crew who are quietly disengaging.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=114&bi_pidx=39498","prio":2,"mar":false,"tags":["ENG","RET","WELL"]}]},{"code":"HRPOL","kTitle":"HR 제도·동향 (선원 노동·교육 규제 포함)","eTitle":"HR policy and trends (incl. seafarer labour and training rules)","items":[{"code":"HRPOL","date":"2026-10-27","src":"Ship Management International","title":"Thetius·Maritime Passport 보고서 '디지털 선원 증서, 신뢰가 관건' — 선원 1명 증서 검증에 1~2시간, 기항 서류 준비 평균 191분, 64%는 여전히 종이","eTitle":"Thetius and Maritime Passport Report Highlights the Need for Trusted Digital Seafarer Credentials","kSum":"Thetius가 Maritime Passport와 낸 보고서 'Securing Trust: The Transition to Digital Seafarer Credentials'에 따르면 약 257만 명의 선원이 85,000척 이상의 상선에서 일하는데, 채용 담당자가 선원 한 명의 증서를 검증하는 데 1~2시간이 걸리고 기항 서류 준비에 평균 191분이 들며 기항의 64%가 아직 종이 또는 종이·디지털 혼합 제출에 의존한다. 최대 4kg에 이르는 종이 증서는 분실·훼손 시 재발급까지 승선을 막아 선원 교대와 일정을 흔들고, 형식이 제각각이라 육안 검사로는 위조를 가리기 어려우며, 스캔본과 PDF를 이메일로 주고받아 무기한 보관하는 관행은 개인정보·GDPR 위험을 키운다고 보고서는 지적했다. 보고서는 2025년 1월 발효된 STCW 개정이 '원본'에 전자 형식을 포함하도록 정의했고 FAL 50에서 승인된 IMO 해사 디지털화 전략도 표준화·상호운용 데이터 교환을 요구한다며, 유효성·검증·개인정보·분쟁 처리의 공통 기준, 종이·디지털 사본·디지털 원본을 함께 지원하는 단계적 전환, 개방형 표준과 공급사 종속 방지, 저자원 국가에 대한 배려를 권고했다.","eSum":"The Thetius report 'Securing Trust: The Transition to Digital Seafarer Credentials', produced with Maritime Passport, notes that about 2.57 million seafarers serve on more than 85,000 merchant ships, that verifying one seafarer's credentials can take recruiting teams one to two hours, that port call document preparation averages 191 minutes and that 64% of port calls still rely on paper or mixed submissions. Lost or damaged paper certificates, which can weigh up to 4 kg, stop seafarers working until replaced and disrupt crew changes, visual checks are unreliable across many formats, and emailing and indefinitely storing scanned passports and qualifications raises privacy and GDPR risks. Citing STCW amendments effective January 2025 that define 'original form' to include electronic formats and the IMO Strategy on Maritime Digitalisation approved at FAL 50, it calls for common rules on validity, verification, data protection and disputes, a phased transition supporting paper, digital copies and native digital credentials, open standards that avoid vendor lock-in, and solutions that work for lower-resource administrations.","kImp":"크루잉·인사 담당이 선원 여권·증서 스캔본을 이메일로 주고받고 보관하는 방식과 기간을 점검해 개인정보 위험을 줄이고, 기국이 디지털 증서를 도입할 때를 대비한 검증 절차를 미리 정리해 볼 만하다.","eImp":"Review how crewing and HR staff exchange and store scanned passports and certificates by email, and for how long, to reduce privacy risk, and prepare verification procedures for when flag States introduce digital credentials.","url":"https://www.shipmanagementinternational.com/news/ndcraxfa56mjyph-f23x3-4w938-fmdk8-9w4jd-ltmlb-d8ac2-5ajxc-29e5a-czdwp-a65gt-rdzba-d95lx-czp3d","prio":2,"mar":true,"tags":["POL","CHG"]},{"code":"HRPOL","date":"2026-10-27","src":"한국해운신문","title":"여수광양항만공사, 드러나지 않는 협조·헌신을 연중 기록하는 ‘공적 마일리지 제도’ 시행 — 평정·MBO·승진심사 참고자료로 활용","eTitle":"Yeosu Gwangyang Port Authority Launches a Year-Round 'Merit Mileage' Record of Unseen Cooperation and Dedication for Appraisals and Promotion","kSum":"여수광양항만공사는 근무성적평정과 개인 성과평가가 평가 시점의 평가자 주관이나 부서·개인 고유 업무 성과 위주로 이뤄져 업무 협조나 헌신 같은 활동이 반영되기 어렵다는 한계를 보완하려고, 직원의 공적을 연중 상시로 발굴·축적하는 '공적 마일리지 제도'를 시행했다. 공적이 생기면 공적확인자의 지시로 직원이 정해진 양식에 등록하고 확인을 거쳐 마일리지를 받는 구조이며, 대상은 조직 헌신, 조직 기여, 적극행정 노력, 핵심고객 만족, 기타 우수 공적의 다섯 가지다. 축적된 결과는 근무성적평정, 개인 MBO 평가, 승진심사, 인사위원회 심의의 참고자료로 쓰이며, 공사는 '평가에 드러나지 않던 직원들의 헌신과 협업, 적극행정 노력이 제때 기록되고 인정받도록 하는 제도'라고 설명했다.","eSum":"Yeosu Gwangyang Port Authority has introduced a 'merit mileage' system that captures staff contributions year-round, because its performance ratings and individual appraisals depended on evaluators' judgement at appraisal time or on each unit's core outputs and missed cooperation and dedication. When a contribution occurs, the employee registers it on a set form at the instruction of a designated verifier and receives mileage once it is confirmed, across five categories: dedication to the organisation, contribution to the organisation, proactive administration, key customer satisfaction and other outstanding merit. Accumulated results serve as reference for performance ratings, individual MBO appraisals, promotion reviews and personnel committee deliberations, which the authority says ensures that unseen dedication, collaboration and proactive effort are recorded and recognised in time.","kImp":"선원 근무평가도 계약 말에 한꺼번에 쓰기보다 근접사고 보고, 다른 부서 지원, 신규 승선자 지도 같은 기여를 그때그때 짧게 기록해 두면 평가자의 최근 기억 편향을 줄일 수 있다.","eImp":"Crew appraisals could log contributions such as near-miss reports, help to other departments or coaching of new joiners as they happen rather than writing everything at the end of a contract, reducing recency bias.","url":"https://www.maritimepress.co.kr/news/articleView.html?idxno=333657","prio":1,"mar":true,"tags":["ENG","POL"]},{"code":"HRPOL","date":"2026-10-22","src":"해양한국","title":"해양수산연수원, 케냐 정부·국내 선사 18곳과 ‘해기인력 공급 다변화’ 원탁회의 — 6월 해기면허 상호인정협정 후속, 탄자니아 등으로 확대 계획","eTitle":"Korea's Maritime Training Institute Holds Roundtable With Kenya and 18 Korean Shipping Companies on Diversifying Officer Supply After Licence Recognition Deal","kSum":"한국해양수산연수원은 지난 6월 체결된 한·케냐 해기면허 상호인정협정의 후속 조치로 10월 1~2일 케냐 해기인력의 국내 선사 취업을 모색하는 원탁회의를 열었고, 케냐광물경제해양부·케냐 해사청 관계자와 주한케냐대사, 케냐 해기교육기관 5곳, 국내 해운선사·선박관리사 18곳이 참석했다. 케냐 측은 블루이코노미 정책에 따른 해양인력 양성 정책과 해기인력 수급 계획을, 교육기관들은 교육과정과 양성 현황을 소개했고, 업계는 국내 선사 해기사 부족을 풀 공급처 다변화의 전환점으로 평가했다. 윤현수 원장은 동남아 외국인 선원이 유럽 등 서방 선진국에 공급 우선순위가 밀리는 상황에서 ODA 사업으로 케냐라는 새 공급처를 찾았다며 탄자니아 등으로 계속 넓히겠다고 밝혔다(케냐 인원·일정 수치는 기사에 없음).","eSum":"Following a June agreement on mutual recognition of seafarer certificates between Korea and Kenya, the Korea Institute of Maritime and Fisheries Technology held a roundtable on 1-2 October on employing Kenyan officers with Korean companies, attended by officials of Kenya's mining, blue economy and maritime affairs ministry and maritime authority, the Kenyan ambassador, five Kenyan maritime training institutions and 18 Korean shipping and ship management companies. Kenya outlined workforce plans under its Blue Economy policy and the schools presented their curricula, while industry called it a turning point for diversifying supply to ease officer shortages. Institute president Yoon Hyun-soo said Korea had found a new source as Southeast Asian seafarers increasingly go first to European and other Western fleets, and plans to extend the approach to Tanzania and other countries (the report gives no numbers or timetable for Kenyan placements).","kImp":"새 국적 선원을 처음 받을 때는 출신 교육기관의 커리큘럼을 미리 확인하고, 기존 선원과 섞이는 첫 승선에서 멘토 역할을 맡을 사관을 지정해 두는 준비를 해 볼 만하다.","eImp":"Before taking crew of a new nationality for the first time, companies could review the source schools' curricula and assign an experienced officer as mentor for the first mixed-crew contract.","url":"https://www.monthlymaritimekorea.com/news/articleView.html?idxno=57972","prio":1,"mar":true,"tags":["RET","XC"]},{"code":"HRPOL","date":"2026-10-21","src":"Safety4Sea","title":"Fleet Management '선박보다 앞서는 STCW를' — 교육의 양 대신 역량·준비도·유지로, 신연료 교육 1,750명·선원 유지율 95% 이상","eTitle":"Fleet Management Calls for Future-Ready Seafarer Skills Amid the STCW Review, Shifting From Training Volume to Competence and Retention","kSum":"Fleet Management의 Capt. Somasundar Nair 이사는 Crew Connect Global 2026을 계기로 STCW 전면 개정이 대체연료·디지털 시스템에 대비해 '선박보다 앞서' 기준을 세울 기회라며 STCW는 '최소 기준'이라고 말했다. 그는 기술 교육·자격 외에 리더십·판단력·적응력·실무 의사결정을 강조하며 '교육의 양에서 역량·준비도·유지로' 초점이 옮겨가고 있다고 했다. 회사는 이중연료선 30척 이상 관리, LNG·메탄올·암모니아·디지털 시스템 교육 이수 1,750명 이상, 연간 교육 약 17,000석·시뮬레이터 약 15,500시간, 선원 유지율 95% 이상을 제시했다. 기사는 IMO HTW 12가 2026년 2월 STCW 전면 검토를 개정안 작업 단계로 넘겼고, IMO/ICS 선원 인력 보고서 2026이 STCW 사관 39,100명 부족을 추정했다고 덧붙였다.","eSum":"Capt. Somasundar Nair, Executive Director of Fleet Management, said around Crew Connect Global 2026 that the STCW review is a chance to set standards ahead of the ships rather than behind them, calling STCW 'the minimum'. Beyond technical training and certification he stressed leadership, judgement, adaptability and practical decision-making, saying the focus is shifting from training volume to competence, readiness and retention. The company cited more than 30 dual-fuel vessels managed, over 1,750 seafarers and technical staff trained on LNG, methanol, ammonia and digital systems, about 17,000 training places and 15,500 simulator hours a year, and seafarer retention of at least 95%. The article notes that IMO's HTW 12 moved the comprehensive STCW review into an amendment phase in February 2026 and that the IMO/ICS Seafarer Workforce Report 2026 estimates a shortage of 39,100 STCW officers.","kImp":"신연료·신시스템 선박의 교육 계획을 인도 시점이 아니라 수개월 앞서 세우고, 교육 성과를 이수 시간이 아니라 역량 평가 결과와 승선 유지율로 보고해 볼 만하다.","eImp":"Plan training for new-fuel and new-system ships months before delivery rather than at handover, and report training results as assessed competence and retention rather than hours completed.","url":"https://safety4sea.com/fleet-management-calls-for-future-ready-seafarer-skills-amid-stcw-review/","prio":2,"mar":true,"tags":["TRN","POL","RET"]},{"code":"HRPOL","date":"2026-10-15","src":"남도일보","title":"국감: 미래 해양산업 교육생 5년 새 4.7배(768명→3,625명) 늘었지만 내항상선 1,564명 부족 — 60세 이상 59.4%, 연수원은 교육 뒤 취업·승선 여부 추적 안 해","eTitle":"Parliamentary Audit: Future-Skills Trainees Rose 4.7-Fold to 3,625 in Five Years, Yet Korea's Coastal Fleet Is 1,564 Crew Short and No One Tracks Whether Trainees Go to Sea","kSum":"문금주 의원이 한국해양수산연수원과 한국해운조합의 국정감사 자료를 분석한 결과 북극항로·친환경·자율운항 등 미래 해양산업 교육 인원은 2021년 768명에서 지난해 3,625명으로 4.7배 늘었지만, 내항상선이 2016년 2,285척에서 지난해 2,332척으로 늘어나는 동안 국적선원은 7,854명에서 7,534명으로 줄었다. 지난해 내항선원 가운데 60세 이상은 4,478명(59.4%), 25세 미만은 175명(2.3%)이었고 해기사 중 60세 이상 비중은 2016년 50.2%에서 58.2%로 높아졌으며, 2024년 말 내항상선 부족 인력은 해기사 428명과 부원 1,136명 등 1,564명으로 해운조합은 향후 10년간 5·6급 해기사 중심의 부족을 전망했다. 연수원이 교육생의 자격 취득·취업·실제 승선 여부를 따로 관리하지 않는 데 대해 문 의원은 '교육→자격취득→취업→승선으로 이어지는 결과를 반드시 추적해야 한다'고 지적했다.","eSum":"Audit data from the Korea Institute of Maritime and Fisheries Technology and the Korea Shipping Association released by lawmaker Moon Geum-ju show trainees in future-industry courses such as Arctic routes, green shipping and autonomous navigation rose 4.7-fold from 768 in 2021 to 3,625 last year, yet while coastal merchant ships increased from 2,285 in 2016 to 2,332, Korean seafarers on them fell from 7,854 to 7,534. Last year 4,478 coastal seafarers (59.4%) were 60 or older and only 175 (2.3%) were under 25, the over-60 share among officers rose from 50.2% to 58.2%, and at the end of 2024 the coastal fleet was short of 1,564 crew (428 officers and 1,136 ratings), with shortages of fifth- and sixth-grade officers expected to persist for a decade. Because the institute does not track whether trainees obtain certificates, find jobs or actually go to sea, Moon said outcomes must be tracked from training to certification, employment and boarding.","kImp":"회사가 지원하는 교육도 수료 인원이 아니라 교육 뒤 실제 승선·직무 적용·근속으로 이어졌는지를 추적하는 지표를 두어 볼 만하다.","eImp":"Company-funded training could be measured not by completions but by whether it led to actual sea service, use on the job and retention.","url":"https://www.namdonews.com/news/articleView.html?idxno=926209","prio":1,"mar":true,"tags":["RET","TRN"]},{"code":"HRPOL","date":"2026-10-14","src":"Safety4Sea","title":"몰타, 선원수첩(Seaman's Record Book) 디지털 전용 발급으로 전환 — 전자지갑·블록체인 서명, PSC는 QR로 확인, 수수료 85유로","eTitle":"Malta Moves the Seaman's Record Book to Digital-Only Issue, Verifiable by PSC Officers via QR Code","kSum":"몰타 상선국은 몰타 등록 상선에 고용됐거나 고용 예정인 선원, 몰타 국민, 몰타 해기면허 소지자에게 발급하는 선원수첩(Seaman's Record Book)을 즉시 디지털 전용으로 바꿨다. 신청은 Seafarer Portal에서 선원 본인이나 대리인·고용주가 하고, 수첩은 선원의 전자지갑으로만 발급되며 발급기관이 암호 서명해 Concordium 블록체인에 기록하고, 고용주·PSC 검사관·관계 당국은 QR 코드로 검증할 수 있으며 해상에서도 오프라인으로 열람된다. 승선 경력 기재는 선장이 지정한 이메일이나 권한 있는 관리를 통해 인증받으며, 수수료는 신청 60유로와 디지털 서비스·지갑 유지 25유로를 합쳐 85유로이고, 서류가 빠진 신청은 90일 안에 보완하지 않으면 환불 없이 반려된다.","eSum":"Malta's Merchant Shipping Directorate has made the Seaman's Record Book digital-only with immediate effect for seafarers employed or due to be employed on Malta-registered commercial vessels, Maltese nationals and holders of Maltese certificates of competency. Applications are made through the Seafarer Portal by the seafarer, a representative or the employer, and the book is issued only to the seafarer's electronic wallet, cryptographically signed by the issuing authority and anchored on the Concordium blockchain, verifiable by employers, PSC officers and authorities via QR code and accessible offline at sea. Sea service entries are authenticated through the master's designated email address or authorised officials, fees total EUR 85 (a EUR 60 application fee plus EUR 25 for the digital service and wallet), and incomplete applications not completed within 90 days are rejected without refund.","kImp":"몰타기 선박에 승선할 선원은 승선 일정에 맞춰 디지털 선원수첩 신청을 미리 챙기고, 선장이 승선 경력 인증 요청을 처리하는 방법을 선상 업무 안내에 반영해 둘 만하다.","eImp":"For seafarers joining Malta-flagged ships, plan digital record book applications ahead of joining dates, and include in shipboard guidance how the master handles sea service authentication requests.","url":"https://safety4sea.com/malta-moves-seamans-record-book-to-digital-only-format/","prio":1,"mar":true,"tags":["POL","CHG"]},{"code":"HRPOL","date":"2026-10-13","src":"Safety4Sea","title":"MLC 채택 20년, 유럽 노조 '기국·항만국 집행 강화를' — ETF·ITF 의뢰 WMU 연구 '선원 주당 평균 약 75시간 근무, 규정상 91시간까지 허용'","eTitle":"Unions Mark 20 Years of the MLC by Demanding Stronger Enforcement, as an ETF and ITF-Commissioned WMU Study Finds Seafarers Work Almost 75 Hours a Week","kSum":"9월 18일 아테네에서 그리스 선원노조 PNO와 OMEPEGE/FTPAW-SEK가 연 MLC 20주년 심포지엄에서 ETF는 기국·항만국의 일관성 없는 이행·집행이 선원 보호와 공정 경쟁을 해친다며 EMSA의 역할 강화, PSC 검사관의 표준화된 교육, MLC 다음 단계에서 과도한 근로시간 문제를 다룰 것을 요구했다. ETF·ITF가 의뢰한 WMU 연구는 선원이 주당 평균 약 75시간 일하는 반면 국제 규정은 7일간 최대 91시간까지 허용한다고 밝혔고, PNO 사무총장 Capt. Emmanuel Tsikalakis는 근로시간·피로·정신건강을 젊은 인력 유치·유지의 어려움과 연결했다. ETF는 기국 변경이 선원 보호를 낮춰서는 안 된다며, EU 시장 접근·공공 지원을 받는 회사에 사회적 기준을 요구하는 '사회적으로 지속가능한 해운을 위한 유럽 해사 공간'을 제안했다.","eSum":"At a symposium in Athens on 18 September marking 20 years of the MLC, co-organised by the Greek seafarers' federation PNO and OMEPEGE/FTPAW-SEK, the ETF said inconsistent flag and port State implementation undermines protection and fair competition, urging a stronger EMSA role, more standardised training for PSC inspectors and action on excessive working hours in the next phase of the MLC. A World Maritime University study commissioned by the ETF and ITF found seafarers work almost 75 hours a week on average while international rules can permit up to 91 hours over seven days, and PNO Secretary General Capt. Emmanuel Tsikalakis linked working time, fatigue and mental health to difficulties attracting and retaining young people. The ETF also called for a European Maritime Space for Socially Sustainable Shipping in which companies benefiting from EU market access and public support meet social standards, and said flag changes must not lower crew protection.","kImp":"휴식시간 '위반 0건'만 보지 말고 선박별 주당 실제 근무시간 분포를 따로 집계해, 기항이 몰리는 구간의 업무량을 줄일 방법을 찾아볼 만하다.","eImp":"Rather than relying on zero rest-hour violations, compile the distribution of actual weekly working hours by ship and look for ways to reduce workload in port-intensive periods.","url":"https://safety4sea.com/unions-call-for-stronger-seafarer-protections-20-years-after-mlc-adoption/","prio":2,"mar":true,"tags":["POL","WELL"]},{"code":"HRPOL","date":"2026-10-11","src":"The Manila Times","title":"필리핀, 유엔 인권이사회서 선원 보호 강화 주도 — 무력분쟁 위협 대응 조정 메커니즘, '부당한 범죄화·자의적 구금' 유엔 태스크포스 제안","eTitle":"The Philippines Leads a UN Push in Geneva to Protect Seafarers in Armed Conflicts, Proposing a Task Force on Unfair Criminalization and Arbitrary Detention","kSum":"필리핀은 10월 5일 제63차 유엔 인권이사회 기간에 유엔 인권사무소·ILO·IMO가 공동 주최하고 필리핀·방글라데시가 후원한 부대행사에서 무력분쟁·위기 상황에서 고립·유기·구금된 선원을 위한 국제 보호 장치 강화를 촉구했다. 제안에는 미사일·드론·기뢰 위협을 받는 선원을 돕는 조정 메커니즘과 선원의 부당한 범죄화·자의적 구금을 다루는 유엔 전담 태스크포스 신설이 포함됐고, 참석자들은 선원을 핵심 노동자(key worker)로 인정하고 인권 기준과 해상의 적정 근로·생활 여건을 지키라고 요구했다. 행사를 이끈 Carlos Sorreta 주제네바 필리핀 대사는 선원 권리·복지 보호가 '필리핀 외교 정책의 핵심 축'이라고 했고, ILO MLC 특별삼자위원회 선원 측 부의장 Mark Dickinson은 ITF 집계 2025년 유기 선원 6,223명(선박 410척, 미지급 임금 2,580만 달러 중 1,650만 달러 회수)을 인용했다.","eSum":"At a side event on 5 October during the 63rd session of the UN Human Rights Council, co-organised by the UN human rights office, the ILO and IMO and co-sponsored by the Philippines and Bangladesh, the Philippines called for stronger international safeguards for seafarers stranded, abandoned or detained in armed conflicts and other crises. Proposals included a coordination mechanism to assist crews threatened by missiles, drones and sea mines and a dedicated UN task force on the unfair criminalization and arbitrary detention of seafarers, and participants urged recognition of seafarers as key workers and respect for human rights and decent conditions at sea. Philippine Permanent Representative Carlos Sorreta called seafarers' rights and welfare 'a key pillar of Philippine foreign policy', and Mark Dickinson, seafarer vice chair of the ILO's MLC Special Tripartite Committee, cited ITF figures of 6,223 seafarers abandoned on 410 vessels in 2025, with USD 25.8m unpaid and USD 16.5m recovered.","kImp":"분쟁 해역 운항이나 선원 구금에 대비해 선원·가족에게 정보를 전하는 방식과 영사·법률 지원 연결 절차를 비상대응 계획에 미리 정리해 둘 만하다.","eImp":"Set out in emergency response plans, in advance, how crews and families will be kept informed and how consular and legal support will be arranged if ships operate in conflict areas or crew are detained.","url":"https://www.manilatimes.net/2026/10/11/news/national/ph-leads-un-push-to-protect-seafarers/2443150","prio":1,"mar":true,"tags":["POL","WELL"]},{"code":"HRPOL","date":"2026-10-06","src":"한국해운신문","title":"국감: 한국인 취업선원 8년 새 22% 감소(3만 5,096명→2만 7,372명), 면허는 19.9% 늘어 취업 비율 16.6%… 60세 이상 비중 43.8%","eTitle":"Parliamentary Audit: Employed Korean Seafarers Fell 22% in Eight Years to 27,372 as Licences Rose 19.9%, and Over-60s Now Make Up 43.8%","kSum":"문금주 의원이 해양수산부 자료를 분석한 결과 한국인 취업선원은 2017년 3만 5,096명에서 2025년 2만 7,372명으로 7,724명(22%) 줄었지만 유효면허는 13만 7,290개에서 16만 4,548개로 19.9% 늘어, 면허 대비 실제 취업선원 비율이 25.6%에서 16.6%로 떨어졌다. 60세 이상 선원은 1만 2,797명에서 1만 2,002명으로 소폭 줄었으나 비중은 36.5%에서 43.8%로 높아져 2022년부터 43%를 넘었고, 고령 선원 퇴직이 본격화되면 인력 공백이 커질 수 있다는 우려가 나왔다. 문 의원은 처우 개선, 적정 휴식 보장, 휴가·교육 때의 대체인력 확보와 함께 정부 지원 교육생의 취업 여부·승선 후 근속기간·조기 이탈 원인을 파악하고, 정책 성과를 수료자 수가 아니라 실제 취업과 장기 근속으로 관리해야 한다고 제안했다.","eSum":"Ministry of Oceans and Fisheries data released by lawmaker Moon Geum-ju show employed Korean seafarers fell by 7,724 (22%) from 35,096 in 2017 to 27,372 in 2025, while valid licences rose 19.9% from 137,290 to 164,548, cutting the share of licence holders actually employed at sea from 25.6% to 16.6%. Seafarers aged 60 or over edged down from 12,797 to 12,002 but their share rose from 36.5% to 43.8%, above 43% since 2022, raising concern that retirements will widen the gap. Moon called for better pay and conditions, adequate rest and relief crews during leave and training, tracking whether state-funded trainees find jobs, how long they stay and why they leave early, and judging policy by actual employment and long service rather than course completions.","kImp":"사관 유지 지표로 신규 승선자의 첫 계약 완수율·재승선률·조기 하선 사유를 따로 기록해 두면 어느 단계에서 이탈이 생기는지 짚을 수 있다.","eImp":"Tracking first-contract completion, rehire rates and reasons for early sign-off among newly joined officers would show at which stage retention breaks down.","url":"https://www.maritimepress.co.kr/news/articleView.html?idxno=333313","prio":2,"mar":true,"tags":["RET","POL"]},{"code":"HRPOL","date":"2026-10-05","src":"Safety4Sea","title":"'STCW 전면 개정은 더하기만큼 빼기도' — 400여 개 격차 식별, 정신건강·심리적 안전·괴롭힘·다양성도 검토, 2029~2030년 MSC 상정 전망","eTitle":"Opinion: The IMO's Comprehensive STCW Review Must Be About Subtraction as Well as Addition, With a Regulatory Balance Sheet for Over 400 Identified Gaps","kSum":"SAFETY4SEA 창업자 Apo Belokas는 2022년 MSC가 시작한 STCW 전면 검토가 1단계에서 400개가 넘는 격차·검토 영역을 찾았고, 2026년 2월 HTW 12에 160건 이상의 문서가 제출됐으며, IMO 로드맵상 개정 협약은 2029~2030년쯤 MSC에 올라갈 전망(채택일 미정)이라고 정리했다. 검토 대상에는 대체연료·디지털화·사이버·자동화와 함께 정신건강과 심리적 안전, 폭력·괴롭힘, 성별·문화 다양성, 첨단 교육기술이 들어 있다. 그는 400개 격차가 400개 새 요건을 뜻하지 않는다며, 새 요건마다 다루는 위험·기존 규정의 부족·역량 입증 방법을 설명하고 무엇을 삭제·통합·단순화했는지도 보고하는 '규제 대차대조표', 출석보다 역량(시뮬레이션·선상 평가·블렌디드 교육) 중심의 평가, 교육 시간을 한정 자원으로 다루는 접근을 제안했다.","eSum":"SAFETY4SEA founder Apo Belokas notes that the comprehensive STCW review started by MSC in 2022 identified more than 400 gaps and areas for consideration in its first phase, that more than 160 documents went to HTW 12 in February 2026, and that IMO's roadmap envisages the revised treaty reaching MSC around 2029 or 2030, with no adoption date fixed. Items under consideration include alternative fuels, digitalisation, cyber security and automation as well as mental health and psychological safety, violence and harassment, gender and cultural diversity and advanced training technologies. Arguing that 400 gaps do not mean 400 new requirements, he proposes a 'regulatory balance sheet' explaining for each new requirement the risk addressed, why existing rules fall short and how competence will be shown, with reporting of what was removed, consolidated or simplified, a shift from attendance to competence through simulation, onboard assessment and blended training, and treating training time as a finite resource.","kImp":"사내 교육 과정에도 '어떤 위험을 다루는가, 이미 다른 과정에 있는가, 역량을 어떻게 확인하는가'를 물어 중복을 정리하고, 아낀 시간을 리더십·소통·정신건강 같은 인적 요소 교육에 돌려 볼 만하다.","eImp":"Apply the same test to in-house courses, asking what risk each addresses, whether another course already covers it and how competence is verified, and redirect the time saved to human element training such as leadership, communication and mental health.","url":"https://safety4sea.com/cm-the-stcw-review-must-be-about-subtraction-as-well-as-addition/","prio":2,"mar":true,"tags":["POL","TRN"]},{"code":"HRPOL","date":"2026-10-01","src":"Safety4Sea","title":"미 해안경비대, 국내 STCW 교육요건 6개 삭제 제안 — 500GT 미만 연안선 선장 리더십·당직사관 BRM·팀워크 교육 포함","eTitle":"US Coast Guard Proposes Removing Six STCW Training Requirements, Including Leadership, BRM and Teamworking for Small Near-Coastal Vessels","kSum":"미국 해안경비대(USCG)는 국제 STCW 협약·코드 역량 기준을 넘어서는 국내 교육요건 6개를 없애는 규칙 개정을 제안했다. 대상은 500GT 미만 연안선 선장의 리더십·관리 기술(LMS), 같은 선박 당직항해사의 BRM 교육과 리더십·팀워크(LTW) 역량 입증, 750kW 이상 선박 기관사·DDE의 기관 용어·선상 운용(ETSO), 전기기술 부원(ETR)의 컴퓨터 시스템(CSM)·고전압(HVPS) 교육이다. USCG는 소형 연안선은 한 명이 당직·조타·견시를 겸해 대형 선교팀용 교육이 불필요하고 ETR은 고전압·컴퓨터 작업을 사관의 직접 감독 아래서만 한다고 설명하면서, 500GT 이상이나 대양 항해 선박 사관에게는 이 기술이 여전히 중요하다고 밝혔다. Safety4Sea 기고(10/5)에 따르면 이 요건들은 2013년 국내 규정에 추가됐고 삭제 시 연간 약 825명이 혜택을 보며 10년간 약 4,280만 달러가 절감될 것으로 추산되고, 의견 제출 기한은 연방관보 게재 후 90일이다.","eSum":"The US Coast Guard has proposed removing six domestic training requirements that in some cases go beyond STCW Convention and Code competence standards: leadership and managerial skills for masters of near-coastal vessels under 500 GT, BRM training and leadership and teamworking competence for OICNWs on those vessels, engineering terminology and shipboard operations for engineering officers and DDEs on ships of 750 kW or more, and computer systems and high-voltage training for electro-technical ratings. The USCG argues that on small near-coastal vessels one mariner often stands watch and acts as helmsman and lookout, so training designed for larger bridge teams is unnecessary, and that ETRs do computer and high-voltage work only under an officer's direct supervision, while stressing these skills remain relevant for officers on ships of 500 GT or more or on ocean voyages. A Safety4Sea opinion piece notes the requirements were added in 2013, that about 825 mariners a year could benefit and that savings are estimated at about USD 42.8m over ten years; comments are due 90 days after Federal Register publication.","kImp":"규제 최소치가 줄더라도 리더십·BRM 교육의 필요는 선교팀 규모와 운항 형태로 판단한다는 원칙을 사관 교육 계획 검토 기준으로 삼아, 사내 교육을 실제 팀 구성의 위험에 맞춰 유지할 만하다.","eImp":"Even where regulatory minimums are reduced, base the review of officer training on bridge team size and operating pattern, keeping in-house leadership and BRM training aligned with real team risks rather than with what the rules require.","url":"https://safety4sea.com/us-coast-guard-proposes-removing-six-stcw-training-requirements/","prio":2,"mar":true,"tags":["POL","BRM","TRN"]},{"code":"HRPOL","date":"2026-10-01","src":"Hellenic Shipping News","title":"ICS, 무료 실무 자료 확대 — 선교·기관실 체크리스트, 갑판 자가평가 도구, 폭력·괴롭힘 예방 지침, MLC 적용 지침, 기국 성과표 공개","eTitle":"ICS Expands Its Collection of Free Practical Resources for Seafarers and Shipping Companies, Including Harassment Prevention and MLC Guidance","kSum":"국제해운회의소(ICS)는 선주·선박관리사·선원이 무료로 쓸 수 있는 실무 자료를 넓혀, Bridge Procedures Guide와 연계한 선교·도선·조종·비상 체크리스트, Engine Room Procedures Guide와 연계한 기관실 작업허가·체크리스트, Deck Procedures Guide와 연계한 갑판 자가평가 도구를 공개했다. 함께 공개된 자료에는 해사 분야 폭력·괴롭힘 예방 지침, ILO 해사노동협약(MLC) 적용 지침, 기국 성과표(Flag State Performance Table), 차기 Bridge Procedures Guide에 실릴 '위성 신호를 믿기 어려운 해역 항해' 지침, ICS Maritime Barometer 2025-2026 보고서, IMO·UNHCR과 만든 'Rescue at Sea' 등이 포함됐다. Thomas A. Kazakos 사무총장은 '업계 전반에 지식을 나누고 모범 관행을 알리는 것이 ICS 사명의 중심'이라고 말했다.","eSum":"The International Chamber of Shipping has expanded the free practical resources available to shipowners, managers and seafarers, adding bridge, pilotage, manoeuvring and emergency checklists linked to the Bridge Procedures Guide, engine room permits and checklists linked to the Engine Room Procedures Guide, and a deck self-assessment tool linked to the Deck Procedures Guide. Also released are guidance on preventing violence and harassment in the maritime sector, guidance on applying the ILO Maritime Labour Convention, the Flag State Performance Table, guidance on navigating in areas of unreliable satellite signals for the next Bridge Procedures Guide, the ICS Maritime Barometer Report 2025-2026 and 'Rescue at Sea', produced with IMO and UNHCR. Secretary General Thomas A. Kazakos said sharing knowledge and promoting best practice 'is central to ICS's mission'.","kImp":"공개된 폭력·괴롭힘 예방 지침과 MLC 적용 지침을 사내 절차와 대조해 빠진 항목을 찾고, 갑판 자가평가 도구를 선박 방문 전 사전 점검표로 시험해 볼 만하다.","eImp":"Compare the published violence and harassment prevention guidance and MLC guidance with company procedures to find gaps, and trial the deck self-assessment tool as a pre-visit checklist for ship visits.","url":"https://www.hellenicshippingnews.com/international-chamber-of-shipping-expands-collection-of-free-practical-resources-for-seafarers-and-shipping-companies-worldwide/","prio":1,"mar":true,"tags":["POL","TRN"]},{"code":"HRPOL","date":"2026-09-22","src":"쉬핑뉴스넷","title":"[칼럼] “승선율 하락은 실패가 아니라 인재 순환” — 초임 3항사 자리 부족의 원인은 처우 개선이 아니라 외국인 주니어 사관 대체라는 주장","eTitle":"[Opinion] 'Falling Sea-Time Retention Is Talent Circulation, Not Failure': Column Argues Junior Berths Are Lost to Foreign Officers, Not to Better Conditions","kSum":"쉬핑뉴스넷 오피니언(낙수)은 장기승선율 저하, 신규 3항기사 승선 기회 감소, 외국인 주니어 사관 대체, 승선근무예비역 감축, 무인선 확산이 얽힌 해기사 논쟁이 단기 지표와 행정 편의 논리로 다뤄지고 있다고 비판했다. 필자는 직급별 장기승선율(3항사 80%, 2항사 70%, 1항사 50%, 선기장 약 20%, 출처 미표기)을 들어 승선율 하락은 해기사가 선박관리·선급·해사법률·항만물류 등 육상으로 진출하는 건강한 순환이라고 보고, '대우가 좋아져 초임 3항사를 태울 배가 없다'는 주장은 상위 직급이 자리를 비우지 않으면 아래가 설 수 없는 진급 구조상 맞지 않으며 진짜 원인은 일부 국적선사의 한국인 3항사 자리 외국인 대체라고 주장했다. 또 승선근무예비역 정원의 기계적 감축(1,000명→800명→600명 논의)에 반대하고, 원격·무인선 시대일수록 사이버·전시 리스크에 대응할 '전략 해기사'를 세제 혜택과 채용 인센티브로 길러야 한다고 제언했다.","eSum":"An opinion column in Shippingnewsnet criticises Korea's officer-supply debate, which tangles falling long-term sea service, fewer berths for new third officers, replacement by foreign junior officers, cuts to the alternative military service quota for seafarers and the rise of uncrewed ships, as driven by short-term indicators and administrative convenience. Citing unsourced long-term sea-service rates of 80% for third officers, 70% for second officers, 50% for chief officers and about 20% for masters and chief engineers, it calls declining sea service a healthy flow of officers into shore careers such as ship management, class, maritime law and ports, and argues that the claim that better conditions leave no berths for new third officers ignores the promotion pyramid; the real cause, it says, is some Korean-flag owners replacing Korean third officers with foreign ones. It opposes mechanical cuts to the alternative-service quota (from 1,000 to 800 and possibly 600) and urges tax benefits and hiring incentives to train 'strategic officers' able to handle cyber and wartime risks to remote and uncrewed ships.","kImp":"사관의 육상 전환을 '이탈'이 아니라 경력 경로로 설계해 승선 경력자를 감독·안전관리 직무로 데려오는 흐름을 만들고, 초급 사관 자리의 국적 구성 변화가 세대 간 기술 전수에 주는 영향을 점검해 볼 만하다.","eImp":"Officers' moves ashore could be designed as a career path rather than treated as attrition, bringing sea-experienced staff into superintendent and safety roles, while checking how a changing nationality mix in junior berths affects skill transfer between generations.","url":"https://www.shippingnewsnet.com/news/articleView.html?idxno=72189","prio":1,"mar":true,"tags":["RET","POL"]},{"code":"HRPOL","date":"2026-09-17","src":"The Maritime Executive","title":"'출구 없는 갈등' — 선원 16% 2년 내 괴롭힘 경험, ISWAN 신고 급증… 폭력·괴롭힘 대응을 강화한 MLC 2025년 개정 2027년 12월 발효 예정","eTitle":"Conflict Without Exit: Harassment Data Puts the Spotlight on Life Aboard as MLC Amendments Head for Force in December 2027","kSum":"JAMS 소속 조정인 Giuseppe De Palo는 Maritime Executive 기고에서 2024년 선원 설문(36,400명) 응답자의 16%가 지난 2년간 따돌림·괴롭힘을 겪었고 25~30%는 실수 뒤 말하기가 안전하다고 느끼지 않았다고 전했다. ISWAN 상담전화의 학대·괴롭힘·차별·폭력 신고는 2022년 4분기→2023년 1분기 45%, 2023년 3분기에 다시 56% 늘었고(언어폭력·따돌림 약 70%, 성폭행·성희롱 16%, 신체 폭행 12%), 여성은 전체 상담자의 12%였지만 부당 대우 신고자의 38%였다. 그는 ILO가 2025년 채택한 MLC 개정이 선상 폭력·괴롭힘 보호와 신고 체계를 명시적으로 강화하며 2027년 12월 발효 예정이고(ILO도 '2027년 12월까지 발효' 전망), IMO의 폭력·괴롭힘 예방·대응 교육 요건은 2026년 1월 1일부터 적용 중이라고 짚었다. 그러면서 갈등을 초기에 비공식적으로 다루고, 성과·계약을 결정하는 관리자와 분리된 비밀 복지·옴부즈 기능과 '비밀 디지털 창구'를 시험해 보라고 권했다.","eSum":"In a Maritime Executive op-ed, JAMS mediator Giuseppe De Palo notes that 16% of 36,400 respondents to a 2024 seafarer survey reported bullying or harassment in the previous two years and 25-30% did not feel safe speaking up after a mistake. ISWAN helpline reports of abuse, bullying, harassment, discrimination or violence rose 45% from Q4 2022 to Q1 2023 and another 56% in Q3 2023, with about 70% involving verbal abuse or bullying, 16% sexual assault or harassment and 12% physical assault, and women were 12% of all callers but 38% of those reporting mistreatment. He notes that MLC amendments adopted by the ILO in 2025 explicitly strengthen protection and reporting around shipboard violence and harassment and are scheduled to enter into force in December 2027, as the ILO also expects, while IMO training on preventing and responding to violence and harassment has applied since 1 January 2026. He urges early, informal handling of grievances and testing confidential welfare or ombuds-style functions, separate from the managers who decide performance and contracts, and a 'confidential digital front door'.","kImp":"2027년 12월 MLC 개정 발효에 앞서 괴롭힘 신고 경로가 선장·인사평가 라인과 분리돼 있는지 점검하고, 갈등을 초기에 비공식적으로 다루는 선상 절차를 마련해 둘 만하다.","eImp":"Ahead of the MLC amendments entering into force in December 2027, check that harassment reporting is separate from the master and the appraisal line, and set up an onboard process for handling conflicts early and informally.","url":"https://maritime-executive.com/editorials/conflict-without-exit-when-work-is-home-for-thousands","prio":2,"mar":true,"tags":["POL","SPEAK","DI"]},{"code":"HRPOL","date":"2026-09-04","src":"한국해운신문","title":"근로환경 개선이 낳은 역설 — 경력단절 해기사 복귀·이직 감소로 청년 해기사 일자리 줄자 해수부 장관이 해양대·선사·선박관리협회·노조와 대책 회의","eTitle":"A Paradox of Better Conditions: As Returning Officers and Lower Turnover Squeeze Jobs for Young Officers, Korea's Oceans Minister Convenes Schools, Owners, Managers and Unions","kSum":"황종우 해양수산부 장관은 9월 4일 한국해양대·목포해양대·한국해양수산연수원·한국해운협회·한국선박관리산업협회·전국해상선원노동조합연맹·한국해기사협회가 참석한 청년 해기사 취업률 제고 회의를 주재했다. 해수부와 노사가 2023년 '선원 일자리 혁신방안'으로 외항 선원의 근로환경을 개선한 뒤 경력단절 해기사의 현장 복귀와 기존 선원의 잔류가 늘면서 신규 채용 수요가 줄어 청년 해기사 일자리가 감소하는 문제가 생겼다. 참석 기관들은 교육기관의 맞춤형 인재 양성, 업계의 채용 확대, 관계기관의 취업 지원 강화를 과제로 점검했으며, 기사에 구체적인 취업률이나 목표 수치는 나오지 않았다.","eSum":"Oceans Minister Hwang Jong-woo chaired a meeting on 4 September on raising employment of young officers, attended by Korea Maritime and Ocean University, Mokpo National Maritime University, the Korea Institute of Maritime and Fisheries Technology, the Korea Shipowners' Association, the Korea Ship Managers' Association, the Federation of Korean Seafarers' Unions and the Korea Merchant Marine Officers' Association. After the ministry, owners and unions improved working conditions for ocean-going seafarers under a 2023 seafarer jobs plan, more officers who had left the sea returned and fewer quit, reducing new hiring and leaving fewer openings for young officers. Participants reviewed tailored training by schools, wider hiring by industry and stronger job support by agencies, though the report gave no employment rates or targets.","kImp":"이직이 줄어든 지금 초급 사관 채용과 실습생 승선을 계획적으로 늘려 세대 간 기술 전수 구조를 유지해야 하는지, 선단의 연령·직급 분포를 놓고 점검해 볼 만하다.","eImp":"With turnover now lower, it is worth checking the fleet's age and rank profile to see whether planned growth in junior officer and cadet berths is needed to keep skills passing between generations.","url":"https://www.maritimepress.co.kr/news/articleView.html?idxno=332913","prio":1,"mar":true,"tags":["RET","POL"]},{"code":"HRPOL","date":"2026-08-31","src":"한국해운신문","title":"“내항선원 공동예비원 도입 어렵다” — 주 72.6시간 근무·평균 7.3개월 연속승선·유급휴가 금전대체 59.4%, 휴가권 보장 위한 예비인력 풀 놓고 고용주체·비용 공방","eTitle":"'A Shared Relief Pool for Coastal Seafarers Is Hard to Introduce': With 72.6-Hour Weeks, 7.3-Month Tours and 59.4% of Leave Paid Out in Cash, Debate Turns on Employer Status and Cost","kSum":"선원관계연구소 김영모 소장은 8월 25일 국회 내항해운 정책 토론회에서 내항선원이 휴가나 결원 때 바로 투입될 예비 인력을 해운조합이 공동 관리하는 '공동예비원제도'를 제안하며, 내항유조선 299척에 약 13명(연간 약 3억 100만 원, 해운조합·선원노련 기금)을 두고 상병·출산·경조사 등 5가지 비상상황에 한정해 시범 운영하자고 했다. 근거로 제시된 근로실태조사에 따르면 내항선원의 주간 근무시간은 평균 72.6시간으로 법정근로시간(당직자 72시간, 비당직자 60시간)을 웃돌고, 평균 계속승선기간은 7.3개월, 유급휴가 31일 가운데 금전 대체율은 59.4%이며, 60세 이상 비율이 60%로 내항선 해양사고 재해의 69%가 60대 이상에게서 발생했고 내외항 임금 격차는 월 421만 원까지 벌어졌다. 선원노련은 대기 중 고용주체·4대 보험·알선 주체가 불명확한 사실상 파견제라고 반박했고, 선사 측은 외항선원 월 500만 원 대비 20만 원에 그치는 내항선원 비과세 한도 확대가 더 시급하다고 했으며, 해수부 선원정책과장은 실효적 논의를 시작해야 한다고 밝혔다.","eSum":"At a National Assembly forum on 25 August, Kim Young-mo of the Seafarers Relations Institute proposed a shared relief pool, managed by the Korea Shipping Association, to cover coastal seafarers' leave and vacancies, starting with about 13 relief crew for 299 coastal tankers at around KRW 301 million a year funded by the association and the seafarers' union and used only in five emergencies such as illness, childbirth and family events. Survey data cited show coastal seafarers work an average 72.6 hours a week, above the legal limits of 72 hours for watchkeepers and 60 for day workers, serve 7.3 months continuously on average and take 59.4% of their 31 days' paid leave as cash, while 60% are aged 60 or over and account for 69% of casualties in coastal ship accidents, and the coastal-deep-sea pay gap reached KRW 4.21 million a month in 2025. The union called it de facto agency work with unclear employer, social insurance and placement responsibilities, an owner argued that raising coastal seafarers' tax-free allowance from KRW 200,000 a month, against KRW 5 million for deep-sea crew, was more urgent, and the ministry's seafarer policy director said practical discussion should begin.","kImp":"선박별로 휴가 사용률, 휴가 금전 대체 비율, 실제 근무시간을 함께 보면 피로 위험이 큰 곳이 드러나므로, 그 선박부터 교대 인력 계획을 세워 볼 만하다.","eImp":"Looking at leave uptake, the share of leave paid out in cash and actual working hours ship by ship would show where fatigue risk is highest and where relief planning should start.","url":"https://www.maritimepress.co.kr/news/articleView.html?idxno=332822","prio":2,"mar":true,"tags":["WELL","RET","POL"]},{"code":"HRPOL","date":"2026-08-26","src":"Safety4Sea","title":"미 해안경비대, 미국 선박 괴롭힘 신고 의무 범위 확대 — NDAA 2026로 정의 넓혀 차별금지법상 행위까지, MSIB 03-26 발행","eTitle":"US Coast Guard Updates Harassment Reporting Requirements for US Vessels After the FY2026 NDAA Broadens the Definition","kSum":"미국 해안경비대(USCG)는 2026 회계연도 국방수권법(NDAA) 7315조가 46 U.S.C. §10104의 괴롭힘 정의를 넓힘에 따라 2023년 2월 지침을 대체하는 해사안전정보공보(MSIB) 03-26을 냈다. 새 정의는 민권법 제7편·연령차별금지법·장애인법·유전정보차별금지법이 금지하는 행위를 포함하며, 미국 등록 상선의 선주·선장·운항관리자나 선원의 고용주인 '책임 주체'는 성희롱, 회사 방침이나 법을 어긴 성폭행, 확대된 정의의 괴롭힘을 알게 되면 CGIS 이메일·국가지휘센터 전화·CGIS 제보 앱으로 신고해야 한다. USCG는 보호 대상과 무관한 심각하거나 반복적인 따돌림·신고식(hazing)·위협 행위도 자발적으로 신고하라고 강력히 권했고, 사실로 확인된 비위는 형사 기소나 해기면허 조치로 이어질 수 있으며 CGIS는 전 세계 어디서든 미국 선박 내 범죄를 수사할 수 있다고 밝혔다.","eSum":"The US Coast Guard has issued Marine Safety Information Bulletin 03-26, superseding its February 2023 guidance, after Section 7315 of the FY2026 National Defense Authorization Act amended 46 U.S.C. 10104 to broaden the definition of harassment to include conduct prohibited under Title VII of the Civil Rights Act, the Age Discrimination in Employment Act, the Americans with Disabilities Act and the Genetic Information Nondiscrimination Act. The 'responsible entity', meaning the owner, master or managing operator of a documented commercial vessel or the seafarer's employer, must report sexual harassment, sexual assault violating company policy or law, and harassment under the amended definition once aware of it, via CGIS email, the National Command Center or the CGIS Tips App. The USCG also strongly encourages voluntary reporting of severe or pervasive bullying, hazing or other intimidating behaviour not tied to a protected class, and says established misconduct may lead to prosecution or action against mariner credentials, with CGIS able to investigate crimes on US-flagged vessels worldwide.","kImp":"선상 괴롭힘 신고 절차에 기국·항만국별 외부 신고 의무(누가·언제·어디로)를 표로 정리해 두고, 선장이 법적 신고 의무자가 될 수 있다는 점을 사관 교육에 넣어 볼 만하다.","eImp":"Tabulate flag and port State external reporting duties for harassment (who, when and to whom) in onboard reporting procedures, and include in officer training the point that the master may be a legally responsible reporter.","url":"https://safety4sea.com/uscg-updates-reporting-requirements-for-harassment-on-us-vessels/","prio":1,"mar":true,"tags":["POL","SPEAK"]},{"code":"HRPOL","date":"2026-06-26","src":"MarineLink","title":"BIMCO·ICS 선원 인력 보고서 2026 — STCW 사관 3만9,100명 부족·부원 5만6,890명 과잉, 2030년까지 사관 11만3,735명 추가 필요","eTitle":"BIMCO and ICS Seafarer Workforce Report 2026 Warns of a 39,100 Officer Shortage and a Need for 113,735 More Officers by 2030","kSum":"BIMCO와 ICS가 6월 25일 낸 '선원 인력 보고서 2026'에 따르면 상선 85,148척에서 약 257만 명의 선원이 일하며, 2026년 현재 STCW 자격 사관은 39,100명 부족하고 부원은 56,890명 남는다. 2030년까지 사관 113,735명이 추가로 필요해 연평균 22,747명(연 2.0%)씩, 부원은 연 8,475명(연 0.5%)씩 늘어야 하고, 2021년 이후 수요는 전체 35%, 사관 23.1%, 부원 46.3% 증가했다. 보고서는 해사 교육·훈련과 해상 경력(육상 직무 전환 포함) 홍보, 해사 당국의 채용·유지 정기 모니터링, 채용과 교육에 대한 동시 투자와 기존 인력의 유지·개발, 신연료·신기술 대비를 권고했으며, Hellenic Shipping News에 실린 WISTA International 회장 기고에 따르면 이 보고서에서 필리핀은 STCW 선원 약 46만 명(460,147명)으로 최대 공급국이다. BIMCO의 David Loosley 사무총장은 '선원 인력의 채용·교육·유지가 업계의 미래 대비에 결정적'이라고 말했다.","eSum":"The BIMCO and ICS Seafarer Workforce Report 2026, launched on 25 June, finds about 2.57 million seafarers serving 85,148 merchant ships, with a 2026 shortage of 39,100 STCW-certified officers and a surplus of 56,890 ratings. The industry will need 113,735 additional officers by 2030, an average of 22,747 a year (2.0% annual growth), and 8,475 more ratings a year (0.5%), while demand since 2021 has grown 35% overall, 23.1% for officers and 46.3% for ratings. The report recommends promoting maritime education, training and careers at sea including transitions ashore, regular monitoring of recruitment and retention by maritime administrations, investment in both recruitment and training while retaining and developing the existing workforce, and preparing seafarers for new fuels and technologies; a WISTA International op-ed in Hellenic Shipping News notes the report identifies the Philippines as the largest supplier with about 460,147 STCW seafarers. BIMCO Secretary General David Loosley said 'the recruitment, training and retention of the seafarer workforce will be crucial to ensuring that our industry is prepared for the future'.","kImp":"사관 부족이 구조적인 만큼 부원→사관 진급 경로와 사관후보생 실습 선석을 인력 계획의 핵심 지표로 삼고, 신규 채용과 함께 기존 사관의 유지율을 경영 보고에 넣어 볼 만하다.","eImp":"Given a structural officer shortage, treat rating-to-officer progression and cadet training berths as core workforce planning indicators, and report retention of existing officers alongside new recruitment in management reviews.","url":"https://www.marinelink.com/news/bimco-ics-report-warns-possible-shortage-540700","prio":3,"mar":true,"tags":["RET","TRN","POL"]},{"code":"HRPOL","date":"2026-10-23","src":"HR Insight","title":"직원 극단적 선택, 회사 책임은 ‘일이 힘들었나’가 아니라 ‘위험을 알 수 있었나’로 갈린다 — 산재 인정 기준과 판례 3건","eTitle":"Employee Suicide and Employer Liability: Courts Ask Whether the Company Knew or Could Have Known, Not Whether the Work Was Hard","kSum":"김경락 대상노무법인 대표 공인노무사는 산재보험법상 자해 사망은 원칙적으로 업무상 재해가 아니지만 업무상 정신질환 치료 중이거나 업무상 사유로 인한 정신적 이상 상태와 상당인과관계가 인정되면 치료 이력이 없어도 인정되며, 근로복지공단은 증상이 처음 나타난 시점의 약 6개월 전부터 인사·근태·괴롭힘 신고·징계 기록을 조사한다고 설명했다. 민사상 안전배려의무 위반은 회사가 위험을 알았거나 알 수 있었는데도 조치하지 않았는지로 판단되는데, 회사가 우울감 호소를 알지 못한 사건과 우울증을 안 뒤 유급병가·무급휴직·복직을 거듭 허용한 사건은 회사 과실이 부정됐다. 반면 직원 손등의 자해 흔적이 목격돼 상급자에게 보고됐는데도 별도 조치가 없었던 사건은 과도한 업무 강도와 ADHD 진단 고지까지 더해 예측 가능성이 인정돼 위자료 배상 책임이 인정됐고, 사건 뒤 임의로 고치거나 추측으로 쓴 기록은 회사에 유리하게 쓰이기 어렵다고 지적했다(구독 기사로 후반부 비공개).","eSum":"Labour attorney Kim Kyung-rak explains that under Korea's industrial accident insurance law a self-inflicted death is not normally an occupational injury, but it is recognised where the worker was being treated for a work-related mental illness or where a work-related mental disorder is causally linked, even without prior treatment, and the state compensation agency examines personnel, attendance, harassment-complaint and disciplinary records from about six months before symptoms first appeared. Civil liability for breach of the duty of care turns on whether the employer knew or could have known of the risk and failed to act: claims failed where the company was unaware of the employee's low mood and where it repeatedly granted paid sick leave, unpaid leave and reinstatement after learning of depression. Damages were awarded where self-harm marks on an employee's hand were seen and reported to a senior manager but nothing was done, given heavy workload and a disclosed ADHD diagnosis, and records altered or written from guesswork after the event carry little weight (subscriber article; later part not public).","kImp":"선원이 우울감이나 자해 흔적 같은 위험 신호를 보일 때 선장에서 육상 담당자로 이어지는 보고와 조치(상담 연결, 업무 조정, 하선 결정)를 그때그때 기록하는 흐름이 실제로 작동하는지 점검해 볼 만하다.","eImp":"It is worth checking that warning signs in seafarers, such as low mood or self-harm marks, are reported from the master to the shore team and that each response, such as counselling referral, work adjustment or a sign-off decision, is recorded at the time.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=112&bi_pidx=39657","prio":2,"mar":false,"tags":["WELL","POL"]},{"code":"HRPOL","date":"2026-10-22","src":"HR Insight","title":"“데이터는 AI에게, 코칭은 리더에게” — AI 성과 대시보드 숫자 너머 평가자가 읽어야 할 난이도·기여도·통제 불가 변수","eTitle":"'Data to AI, Coaching to Leaders': The Difficulty, Contribution and Uncontrollable Factors Evaluators Must Read Beyond AI Performance Dashboards","kSum":"이재형 농협대 교수(《성과관리 3.0》 저자)는 AI가 KPI 후보 제안과 피드백·평가 근거·면담 시나리오 초안을 맡으면서 평가자의 역할이 데이터 취합에서 코칭과 맥락 해석으로 바뀌고 있다며, VAR이 화면을 줘도 판정은 주심이 하듯 AI 데이터는 판단의 근거일 뿐 판단 자체가 아니라고 강조했다. 호황 시장에서 120점을 받은 직원과 기울던 프로젝트에서 -30%가 될 실적을 -10%로 막은 90점 직원을 예로 들어, 숫자와 실제 성과의 간극은 과업 난이도, 동료를 도운 기여도, 환율 급등 같은 통제 불가 변수에서 생긴다고 정리했다. 지표는 활동이 아닌 결과 중심으로 설계하고 AI가 제안한 지표는 사람이 검증·수정해야 하며, 평가 수용성은 사전에 합의한 기준에 따른 일관된 판단에서 나온다고 했다(구독 기사로 후반부 비공개).","eSum":"Lee Jae-hyung, a professor at Nonghyup University and author of 'Performance Management 3.0', says that as AI suggests KPIs and drafts feedback, rating rationales and appraisal-interview scripts, evaluators are shifting from collating data to coaching and interpreting context; like VAR in football, AI data supports a judgement but is not the judgement. Using the example of an employee who scored 120 in a booming market and one who scored 90 after limiting a looming 30% loss to 10% on a failing project, he identifies three gaps between numbers and real performance: task difficulty, contribution such as helping colleagues, and uncontrollable variables such as exchange-rate spikes. Metrics should measure outcomes rather than activity, AI-suggested indicators should be checked and revised by people, and acceptance of ratings depends on consistent judgements against criteria agreed in advance (subscriber article; later part not public).","kImp":"선원 근무평가에 점검 결과나 KPI 숫자만 적지 말고 항로·기상·항만 여건 같은 통제 불가 변수와 다른 부서를 도운 기여를 함께 적게 하고, 평가 기준을 승선 초기에 미리 공유해 볼 만하다.","eImp":"Crew appraisals could record uncontrollable factors such as routing, weather and port conditions, and contributions such as helping other departments, alongside inspection results or KPIs, with the criteria shared early in the contract.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=109&bi_pidx=39663","prio":1,"mar":false,"tags":["AI","FL"]},{"code":"HRPOL","date":"2026-09-21","src":"HR Insight","title":"“교육은 이벤트가 아니라 구조” — 5,700만 건 교육 세션 분석에서 96%가 HRD 팀장직 축소, 학습 전이는 상사의 교육 전·중·후 역할이 좌우","eTitle":"Training Is a Structure, Not an Event: As 96% of Firms Cut L&D Leadership Roles, Transfer to the Job Depends on What Managers Do Before, During and After","kSum":"SK아카데미 임창현 Research Fellow는 HR 테크 기업 원허들(1Huddle)이 5,700만여 건의 기업 교육·온보딩 세션을 분석한 결과 추적 대상 기업 모두가 시니어 HR 직무를 하나 이상 줄였고 96%는 인재개발 조직의 팀장급 이상 직책을, 71%는 리더 직책 자체를 없앴다며 성장 요구는 커지는데 HRD 기능은 축소되는 역설을 짚었다. 교육이 끝나도 상사·동료·평가 기준이 그대로면 학습은 현업에 착지하지 못한다며 '무엇을 가르칠까'가 아니라 '현장에서 무엇이 달라져야 하나'를 먼저 묻고, 교육 전에는 현장 장면을 정의하고, 교육 중에는 실제 문제로 새 행동을 연습시키고, 교육 후에는 리더와 팀이 그 행동을 반복할 업무 환경과 점검 장치를 설계하라고 제안했다. 브로드와 뉴스트롬의 교육훈련 전이 매트릭스를 들어 상사가 교육 목적을 모르면 복귀한 구성원을 실무 과제로 연결할 수 없다며, 핵심인재 교육 때 소속 임원의 사전 참여를 참여 조건으로 걸었던 사례를 소개했다(구독 기사로 후반부 비공개).","eSum":"Lim Chang-hyun, a research fellow at SK Academy, cites HR tech firm 1Huddle's analysis of some 57 million corporate training and onboarding sessions, in which every tracked company cut at least one senior HR role, 96% cut team-lead or higher positions in talent development and 71% eliminated the function's leader role altogether. Because learning fails to land when managers, peers and evaluation criteria stay the same, he urges designers to ask what must change on the job rather than what to teach: define real work scenes before training, practise new behaviour on real problems during it, and build work routines and checkpoints so leaders and teams repeat the behaviour afterwards. Citing Broad and Newstrom's transfer-of-training matrix, he notes that a manager who does not know a course's purpose cannot link a returning employee to practical tasks, and describes making executives' prior involvement a condition of a high-potential programme (subscriber article; later part not public).","kImp":"육상에서 리더십·BRM 교육을 받은 사관이 승선하기 전에 선장·기관장에게 교육 목표와 선상에서 확인할 행동을 미리 알리고, 승선 첫 달에 그 행동을 함께 점검하는 짧은 대화를 넣어 볼 만하다.","eImp":"Before officers who attended shore-based leadership or BRM courses join a ship, the master or chief engineer could be briefed on the course goals and the behaviours to look for, followed by a short joint check-in during the first month on board.","url":"https://www.hrinsight.co.kr/view/view.asp?in_cate=109&bi_pidx=39567","prio":2,"mar":false,"tags":["TRN","FL"]},{"code":"HRPOL","date":"2026-09-03","src":"HR Dive","title":"신입 첫 주 서류 13건·12시간, '필요한 건 60%뿐' — Adobe 신규 입사자 1,000여 명 조사","eTitle":"Employees say only 60% of onboarding materials are necessary","kSum":"어도비가 최근 2년 안에 입사한 미국 근로자 1,000여 명을 조사한 결과, 신규 입사자는 첫 주에 평균 13건의 온보딩 문서를 받아 약 12시간을 검토했지만 꼭 필요하다고 본 자료는 60%였다. 절반 넘게 기억한다는 응답은 56%에 그쳤고, 상위 10%는 문서가 30건을 넘어 검토에 35시간 이상이 들 수 있었다. 4명 중 1명은 온보딩이 혼란스럽거나 빈틈이 있어 업무 성과나 자신감에 부정적 영향을 받았다고 했고, 5명 중 1명 이상은 입사 결정을 다시 생각하게 됐다고 답했다. 직무별 책임과 기대는 가장 잘 기억됐지만 IT, 법규·컴플라이언스, AI 사용 정책은 가장 덜 기억됐다.","eSum":"An Adobe survey of more than 1,000 U.S. adults who started a job in the past two years found new hires received an average of 13 onboarding documents in their first week and spent about 12 hours reviewing them, yet rated only 60% of the material as necessary. Just 56% said they retained more than half of it, and for the top 10% onboarding ran to more than 30 documents and over 35 hours. One in four said confusing or patchy onboarding hurt their performance or confidence, and more than one in five said it made them question their decision to join. Role-specific responsibilities were retained best, while IT, legal and compliance requirements and AI policies were retained least.","kImp":"승선 직후 숙지(familiarization) 과정도 서명할 문서가 많을수록 정말 중요한 내용이 묻히기 쉽다. 승선 첫 주 자료를 '당장 알아야 할 것'과 '나중에 익힐 것'으로 나누고, 몇 주 뒤 담당 사관이 핵심 내용을 다시 확인하는 후속 점검을 넣어 볼 만하다.","eImp":"Shipboard familiarization suffers the same way: the more forms there are to sign, the easier it is for the essentials to get buried. Split first-week material into 'must know now' and 'learn later', and have a designated officer re-check the essentials a few weeks after joining.","url":"https://www.hrdive.com/news/employees-say-only-60-of-onboarding-materials-are-necessary/829526/","prio":2,"mar":false,"tags":["TRN","RET"]},{"code":"HRPOL","date":"2026-08-25","src":"SHRM","title":"SHRM \"신입의 소통 격차는 지식이 아니라 실전 준비의 문제\" — 8주 역할극·성찰 프로그램 사례","eTitle":"Bridging the Communication Gap for the Early-Career Workforce","kSum":"HR·교육 전문가 차나 소이퍼트(교육학 박사)는 SHRM 기고에서, 초기 경력 직원의 소통 문제는 소통이 중요하다는 걸 몰라서가 아니라 실제 상황에서 쓸 준비가 안 된 데서 온다고 진단했다. 교육은 갈등 해결·발표 같은 고급 기술에 치우치지만 신입은 명확한 업무 글쓰기, 회의 참여, 상대에 맞춘 메시지 같은 기본기에서 더 어려움을 겪는다. 그가 기업 현장에서 운영한 8주 프로그램(10주로 연장 권고)은 시나리오 활동·역할극·성찰·동료 피드백을 평가가 아닌 심리적으로 안전한 학습 환경에서 진행했고, 참가자들은 자신감이 늘고 응답 전에 멈추고 더 경청하게 됐다고 보고했다.","eSum":"Writing for SHRM, HR and learning leader Charna Soifert, EdD, argues that early-career communication gaps stem less from a lack of awareness than from not being ready to communicate in real workplace situations. Training tends to target advanced skills such as conflict resolution and presentations, while new hires struggle more with basics like clear professional writing, meeting participation and audience-centered messaging. Her eight-week workplace program, which she suggests extending to ten, used scenarios, role-play, guided reflection and peer feedback in a psychologically safe, non-evaluative setting, and participants reported more confidence, more active listening and pausing before responding.","kImp":"실습 사관과 신임 3등 항해사·3등 기관사는 규정은 알아도 선교나 기관실에서 상급자에게 이상을 보고하는 '실전 말하기'가 서툴 수 있다. 승선 초기 교육에 보고·복창·이의 제기 상황을 역할극으로 연습하는 짧은 세션을 넣되, 평가와는 분리해 운영해 볼 만하다.","eImp":"Cadets and newly promoted third officers or engineers may know the rules yet struggle to report an abnormality to a senior officer on the bridge or in the engine room. Add short role-play sessions on reporting, read-backs and challenging a decision to early onboard training, kept separate from performance evaluation.","url":"https://www.shrm.org/topics-tools/news/bridging-communication-gap-early-career-workforce","prio":1,"mar":false,"tags":["TRN","PS"]}]}]};
